export default [{"id":848,"question":"ما حكم التأويل في الصِّفات؟","title":"ما حكم التأويل في الصِّفات؟","answer":"الجواب: التأويل منكر، لا يجوز تأويل الصفات، بل يجب إمرارها على ظاهرها على الوجه الذي أراده الله ، من غير تحريفٍ، ولا تكييفٍ، ولا تمثيلٍ، على طريقة العرب وأساليبهم، والله جلَّ وعلا أخبرنا عن صفاته وعن أسمائه وقال: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ [الشورى:11]، فعلينا أن نمرّها كما جاءت، وهكذا قال أهل السنة والجماعة: نمرّها كما جاءت بلا كيفٍ، يعني: أمرُّوها كما جاءت من غير تحريفٍ لها ولا تأويل، بل تمر على ظاهرها، على الوجه الذي يليق بالله، من دون تكييفٍ ولا تمثيلٍ، فيُقال: استوى على العرش استواءً يليق بجلال الله، لا يُشابه خلقه في صفاته، هكذا العين، وهكذا في السمع، وهكذا في اليد، وهكذا في القدم، وهكذا غير ذلك، كلها صفات تليق بالله، لا يُشابه فيها خلقه جلَّ وعلا.\nوقوله سبحانه: تَجْرِي بِأَعْيُنِنَا [القمر:14] وَلِتُصْنَعَ عَلَى عَيْنِي [طه:39] ما يلزم منه التأويل؛ لأنَّ هذه لغة العرب، المقصود من ذلك بيان أنَّ السفينة تجري بكلاءة الله وعنايته، ما يُسمَّى هذا: تأويلًا، هذا بيان للمعنى المراد، وهكذا وَلِتُصْنَعَ عَلَى عَيْنِي أن يُربَّى على عيني، على رعايته سبحانه، وتوفيقه له في تربيته عليه الصلاة والسلام، يعني: موسى.\nوهكذا وَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا [الطور:48] يعني: أنه تحت كلاءة ربه وحفظه وصيانته ونصره وتأييده، إلى غير هذا من الصفات.\nكذلك حديث: مَن تقرَّب إليَّ شبرًا تقرَّبْتُ إليه ذراعًا، ومَن تقرَّب إليَّ ذراعًا تقرَّبْتُ إليه باعًا يُمَرّ كما جاء على الوجه اللائق بالله ، من غير تحريفٍ، ولا تكييفٍ، ولا تمثيلٍ، بل على الوجه الذي أراده الله سبحانه وتعالى.\nهكذا النزول في آخر الليل، وهكذا السمع، وهكذا الغضب، وهكذا الرضا، وهكذا الضحك، تمر كما جاءت على الوجه اللائق بالله، من غير تحريفٍ، ولا تعطيلٍ، ولا تكييفٍ، ولا تمثيلٍ، بل على الوجه اللائق بالله ، من غير مُشابهةٍ لخلقه عزَّ وجلَّ... له الكمال في كل شيءٍ : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ [الشورى:11].","link":"https://binbaz.org.sa/fatwas/20881/ما-حكم-التاويل-في-الصفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0676ما حكم التأويل في الصفات؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأسماء والصفات"]},{"id":862,"question":"كثيرٌ ما يحصل الخلط في اعتقاد الإنسان في آيات الأسماء والصِّفات، فما واجب المسلم في اعتقاده في الصِّفات ومنها: السَّاق والعلو؟ وماذا على مَن كان يُحرِّض على اعتقادٍ خاطئٍ في نفس هذه الصِّفات؟ وماذا على الشاب تجاه مثل هذه الأمور؟ أفيدونا جزاكم الله خيرًا.","title":"ما واجب المسلم تجاه أسماء الله وصفاته؟","answer":"الجواب: الواجب على المسلم في باب الأسماء والصِّفات: أن يسلك مسلك السلف الصالح من أصحاب النبي ﷺ وأتباعهم بإحسانٍ، وهو الإيمان بكل ما جاء في الكتاب العزيز والسنة الصَّحيحة المطهرة في أسماء الله وصفاته، ويمرّها كما جاءت، بلا كيف، يعني: يؤمن بها، ويُقرّ بها، ويعلم أنها حقٌّ، وأنها ثابتةٌ لله عزَّ وجل على الوجه اللائق به ، من دون تحريفٍ، ولا تعطيلٍ، ولا تكييفٍ، ولا تمثيلٍ، ولا تأويلٍ، بل يُقرّها كما جاءت، كما قال مالك والأوزاعي والثوري وغيرهم: \"أمرُّوها كما جاءت بلا كيفٍ\" يعني: أمروها على إثباتها، والإيمان بها، والاعتقاد أنها حقٌّ، وأنها لائقةٌ بالله، من دون تشبيهٍ، ولا تمثيلٍ، ولا تحريفٍ، ولا تعطيلٍ، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ [الشورى:11]، وقال سبحانه: قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص]، وقال : فَلَا تَضْرِبُوا لِلَّهِ الْأَمْثَالَ [النحل:74]، وقال سبحانه: هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65]، فلا يجوز تأويلُها، ولا تحريفُها.\nومن ذلك السَّاق والعلو، العلو ثابتٌ لله، فوق جميع الخلق، وهكذا الاستواء، وهو الاستواء على العرش، بمعنى: ارتفع عليه وعلا على الوجه اللائق به، لا يُشبَّه بخلقه في استوائه على أَسِرَّتهم، أو على سياراتهم، لا، استواء يليق به، لا يُشابه خلقه، ولا يعلم كيفيته إلا هو .\nوهكذا جميع صفاته: كاليد والساق والرِّجْل والأصابع والرضا والغضب والحب وغيرها، كله حقٌّ ثابتٌ لله، لائقٌ بالله، لا يُشابه فيها خلقه ، ولا تُؤَوَّل، ولا تُكَيَّف، بل يجب إثباتها لله على الوجه اللائق به ، من غير تحريفٍ، ولا تعطيلٍ، ولا تشبيهٍ، ولا تمثيلٍ.\nومن أحسن ما صُنف في هذا \"العقيدة الواسطية\" لشيخ الإسلام ابن تيمية، كتاب مختصر مفيد عظيم، ينبغي حفظه لطالب العلم، وهكذا \"النونية\" و\"الحموية\"، كتابان عظيمان في هذا الباب، هكذا كتاب \"التوحيد\" لابن خزيمة، كتاب \"السنة\" لعبدالله ابن الإمام أحمد، وغيرها، الردِّ على بشر.....، كتب عظيمة جدًّا، لكن أخصرها للطالب \"العقيدة الواسطية\"، ذكر فيها عقيدة أهل السنة والجماعة في طريقةٍ واضحةٍ، ليس فيها تكلُّفٌ، وليس فيها تعبٌ.....\nقوله تعالى: يَوْمَ يُكْشَفُ عَنْ سَاقٍ [القلم:42] جاء في الحديث الصَّحيح: أنَّ الله يكشف عن ساقه يوم القيامة لعباده حتى يعرفوه بذلك، ساق يليق بالله، مثل: اليد، ومثل: القدم، ومثل: الأصابع، كلها تليق بالله، لا يُشابه خلقه، لا في قدم، ولا ساق، ولا أصبع، ولا رضا، ولا غضب، ولا في ضحك، ولا في محبة، ولا في غير ذلك: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ الْبَصِيرُ [الشورى:11]، الباب واحدٌ، ومَن تأوَّلها خلاف ذلك فقد خالف أهل السنة، وقد خالف الآيات والأحاديث، فلا يجوز تأويلها بخلاف ذلك، بل يجب إمرارها كما جاءت من غير تحريفٍ، ولا تعطيلٍ، ولا تكييفٍ، ولا تمثيلٍ، ولا زيادةٍ، ولا نقصٍ، ولا تأويلٍ.","link":"https://binbaz.org.sa/fatwas/20909/ما-واجب-المسلم-تجاه-اسماء-الله-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0704ما هو واجب المسلم تجاه أسماء الله وصفاته؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأسماء والصفات"]},{"id":880,"question":"هل أقسام صفات الله  أربعة: صفات لازمة، وصفات طارئة، وصفات خبرية، وفعلية؟ وهل كل الصفات اللازمة تثبت بالسمع والعقل؟ وهل كل الصفات الخبرية صفات لازمة؟","title":"ما أقسام صفات الله تعالى؟","answer":"الجواب: المعروف أنها سمعية مُتلقاة من الكتاب والسنة، كل صفات الله سمعية، وهناك فطرية عقلية، فطر الله عليها العباد، كما فطرهم على الإيمان بعلو الله سبحانه، وقدرته العظيمة، وأنه ربهم وخالقهم، هذه فطرة فطر الله عليها العباد، وجاء بها السمع من الكتاب والسنة، وهي قسمان: ذاتية، وفعلية، تتعلق بمشيئته سبحانه وتعالى.\nفالذاتية: كالسمع والبصر والعلم والقُدرة، هذه صفات ذاتية لازمة له سبحانه وتعالى، من كماله جلَّ وعلا.\nوهناك صفات فعلية تتعلق بمشيئته: كالرضا والغضب، والخلق والرزق والتَّدبير والكلام، كله بمشيئته سبحانه وتعالى، فهو يتكلم إذا شاء، ويرضى إذا شاء، ويغضب إذا شاء، ويُحب مَن يشاء، ويبغض مَن يشاء، على حسب ما دلَّ عليه كتابُ الله وسنةُ الرسول عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/20920/ما-اقسام-صفات-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0715هل أقسام صفات الله أربعة صفات لازمة وصفات طارئة وصفات خبرية وفعلية؟ابن باز.mp3","categories":["الأسماء والصفات"]},{"id":886,"question":"إِنَّ الَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ اللَّهَ يَدُ اللَّهِ فَوْقَ أَيْدِيهِمْ [الفتح:10]، ما اعتقاد أهل السنة والجماعة في قوله تعالى: يَدُ اللَّهِ فَوْقَ أَيْدِيهِمْ؟ وهل هناك تأويلٌ لهذه الصفة أم هي على حقيقتها؟ وما القاعدة أو الضَّابط في مثل هذه الصِّفات؟ أفتونا مأجورين.","title":"ما تفسير قوله تعالى: {يد الله فوق أيديهم}؟","answer":"الجواب: هذه الآية عند أهل السنة والجماعة تدل على أمرين:\nالأمر الأول: إثبات اليد لله ، وأنه سبحانه موصوفٌ باليد، كما قال جلَّ وعلا: مَا مَنَعَكَ أَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ [ص:75]، وقال سبحانه: بَلْ يَدَاهُ مَبْسُوطَتَانِ [المائدة:64]، وهذا بإجماع أهل السنة والجماعة ثابتٌ لله ، صفة اليد لله ثابتةٌ عند أهل السنة والجماعة بالنصِّ وبالإجماع.\nوالأمر الثاني: أنه سبحانه يقرّ هذه البيعة ويرضاها، وأن يد رسوله ﷺ قائمةٌ مقام يده سبحانه في إنفاذ هذه البيعة، يد الله فوق أيديهم، والمراد بهذا إثبات أن يد الرسول ﷺ قائمةٌ مقام يد الله في إثبات هذه البيعة.\nففيه إثبات اليدين جميعًا: يد الله سبحانه التي هي قائمةٌ به سبحانه، وهو فوق العرش، فوق جميع الخلق، ويد الرسول التي بايعتهم بأمر الله وشرع الله ورضاه .\nفلما كان قد رضي هذه البيعة وأقرَّها سبحانه وأمر بها جعل يده فوق أيديهم؛ لبيان تنفيذ هذا الأمر، ورضاه ، ومعلومٌ عند المخاطبين أنَّ المراد بذلك إقراره لهذا الشيء ورضاه به، فكأنَّه وقعه بيده ، وهذا معروفٌ في لغة العرب، يقولون: يد السلطان على يد فلان، يد الملك على يد فلان، من توسّع اللغة، اللغة فيها توسع، ويُسمونها: المجاز، يعني: الجائز في اللغة، جاز يجوز مجازًا، مثل: قال يقول مقالًا، يعني: مما يجوز في اللغة، ويتوسع في اللغة أن يُعبر بهذا التَّعبير لإقرار الشيء وإثباته، وأنه عن رضا المقرّ: من ملكٍ، ورئيس جمهورية، ونحو ذلك.\nفالله عزَّ وجل أقرَّ هذه البيعة على يد رسوله ﷺ، وبيَّن أنَّ يده فوق أيديهم، راضيًا بذلك، ومُقِرًّا لذلك، ومعلومٌ عند أهل الحقِّ أنَّ يده ليست بين أيديهم، وليست معهم، ولكنَّه فوق العرش، فوق جميع الخلق سبحانه وتعالى.\nوهكذا قوله سبحانه: لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا [التوبة:40]، إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى [طه:46]، وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ [الحديد:4]، ليس معناه: أنه مختلطٌ بهم، وأنه بينهم، وأنه عند فرعون مع موسى وهارون، لا، المراد معية الكلاءة والحفظ والتَّأييد والنَّصر، ومعية العلم والاطلاع، وهو فوق العرش جلَّ وعلا، فوق جميع الخلق ، وهكذا قوله جلَّ وعلا: وَنَحْنُ أَقْرَبُ إِلَيْهِ مِنْ حَبْلِ الْوَرِيدِ [ق:16] بعلمه واطِّلاعه وإحاطته وملائكته، وهو فوق العرش ، وهذا معروفٌ في سعة اللغة وطرق مخاطبتها فيما بينها، والقرآن نزل بلغة العرب.","link":"https://binbaz.org.sa/fatwas/20913/ما-تفسير-قوله-تعالى-يد-الله-فوق-ايديهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0708ماهو اعتقاد أهل السنة والجماعة في قوله تعالى يد الله فوق أيديهم؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأسماء والصفات"]},{"id":918,"question":"يقول السائل: سمعنا مَن يقول أنَّ القرآنَ كلام الله قديمٌ، حادث الآحاد، فما معنى هذا؟","title":"حكم قول أنَّ القرآنَ كلام الله قديمٌ حادث الآحاد","answer":"الجواب: كلام الله هو من صفاته جلَّ وعلا، مثل غضبه ورضاه ورحمته وعلمه، ليس بمخلوقٍ، بل الله بصفاته هو الخالق، وما سواه مخلوقٌ. وكلامه جلَّ وعلا جنسه قديم، لم يزل مُتكلِّمًا ، ولكنه حادث الأنواع؛ فكلامه مع محمدٍ ﷺ غير كلامه مع موسى، بعد موسى، وهكذا كلامه يوم القيامة للناس، وكلامه لأهل الجنة: يا أهلها، هل رضيتُم؟ كلامٌ جديدٌ بعدما دخلوا الجنة، وليس بقديمٍ.\nفصفات الله جلَّ وعلا قديمة النوع، حادثة الآحاد، وهكذا غضبه على قوم لوط بعد غضبه على قوم نوح، وقوم عاد، وقوم ثمود، غضبٌ جديدٌ آخر، غير غضبه على أولئك، وغضبه على فرعون وجماعته بعد غضبه على قوم هود، وقوم صالح، وقوم لوط، وقوم شعيب، وهكذا غضبه على قريش وما حصل عليهم يوم بدرٍ من المقتلة العظيمة، كل ذلك بأسباب كُفرهم وضلالهم وغضب الله عليهم، وهكذا غضبه على مَن عصاه إلى يومنا هذا، كل مَن عصاه وخالف أمره غضب عليه، كما قال تعالى: وَمَنْ يَقْتُلْ مُؤْمِنًا مُتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا [النساء:93]، فالمعاصي تُوجب غضب الله، والطاعة تُوجب رضاه؛ فضلًا منه سبحانه.\nقديم جنس الكلام، جنس الرضا، جنس الغضب، لم يزل ربنا مُتكلِّمًا، يغضب على مَن عصاه، ويرضى عمَّن أطاعه، ويرحم مَن يشاء، ويُعذِّب مَن يشاء، ولكن هذه الصِّفات تتجدد؛ فغضبه على فرعون بعد غضبه على قوم نوح، وقوم هود، وقوم صالح، إلى آخره، وغضبه على مَن فعل الشرك والكفر من اليهود والنصارى بعد ذلك، وغضبه على كفار قريش وغيرهم من الكفرة بعد ذلك.\nوهكذا رضاه عمَّن تقدم من المؤمنين غير رضاه عمَّن تأخَّر بعدهم، هذا رضا، وذاك رضا، رضا يتجدد بأسبابٍ، حصول أسباب الرضا، والغضب يتجدد بأسباب حصول الغضب، ويغضب إذا شاء، ويرضى إذا شاء بالأسباب التي تُسبب الغضب والرضا.\nوهكذا الكلام سواء: يتكلم إذا شاء، تكلَّم سابقًا، وتكلم مع نبيه ورسوله موسى، ومع نبيه محمد ﷺ، وتكلم مع الملائكة، ويأمر وينهى، ولا يزال يتكلم إذا شاء ، وهكذا يوم القيامة، وهكذا يُكلّم أهل الجنة، فالرسول يقول: ما منكم من أحدٍ إلا سيُكلِّمه ربُّه يعني: يوم القيامة، ما منكم من أحدٍ إلا سيُكلِّمه ربُّه، ليس بينه وبينه ترجمان، وهذا معنى قوله: مَا يَأْتِيهِمْ مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ [الأنبياء:2] يعني: محدث جديد بعد الكلام الأول، وبعد الكتاب الأول.\nفالحدث حدثان: حدثٌ جدَّ بعد ما قبله، وحدث خلقٍ وإيجاد، فإيجاد الموجودات بعضها بعد بعضٍ هذا إيجاد في الخلق، وإنزال التوراة والإنجيل بعد إنزال الصحف التي على إبراهيم هذا إنزالٌ جديدٌ، وكلامٌ جديد، وإنزال القرآن على محمدٍ ﷺ إنزالٌ جديدٌ، وقرآنٌ جديدٌ، وكلامٌ جديدٌ غير الكلام الذي نزل على موسى وعلى عيسى.\nفينبغي التَّفطن لهذا، والعلم بهذا، وهذا كله لا يُنافي أنها صفات لله  و.\nس: ما يكون هذا في الأزل؟\nالشيخ: لا، الأزل جنس الكلام في الأزل، أما التوراة فجاءت بعد ذلك، والإنجيل جاء بعد ذلك، والقرآن جاء بعد ذلك، وكلام الله يوم القيامة حين يقول: يا آدم، أخرج بعثَ النار كلامٌ جديدٌ، كلامه مع الناس يوم القيامة حين يُكلِّمهم ويُجازيهم ويسألهم عن أعمالهم، كلامه مع أهل الجنة: هل رضيتُم إلى آخره.","link":"https://binbaz.org.sa/fatwas/20966/حكم-قول-ان-القران-كلام-الله-قديم-حادث-الاحاد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0762يقول السائل سمعنا من يقول أن القرآن كلام الله قديم حادث الآحاد , فما معنى ذلك؟ ابن باز.mp3","categories":["الأسماء والصفات"]},{"id":979,"question":"السلام عليكم ورحمة الله وبركاته، السؤال الأول: قال لي أحدُ الإخوان: لا تقل: الله موجود في كل مكان، وهذا خطأ....... وقال لي: الله موجودٌ ويعتلي عرش السَّماوات السبع، وهو أقرب إلينا من حبل الوريد. أفدنا عن هذا القول وفَّقكم الله.","title":"ما حكم من يقول: الله موجود في كل مكان؟","answer":"الجواب: نعم، نعم، الذي قال لك هذا القول قد أصاب وأجاد وأحسن، فالله جلَّ وعلا فوق العرش، فوق جميع الخلق، كما قال : الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]، وقال : إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54]، وقال : فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12]، وقال سبحانه: وَهُوَ الْقَاهِرُ فَوْقَ عِبَادِهِ [الأنعام:18].\nفهو فوق العرش جلَّ وعلا، وعلمه في كل مكانٍ، علمه معنا، يطَّلع علينا، وهو أقرب إلينا من كل شيءٍ  باطِّلاعه وعلمه ورؤيته، أما هو فهو فوق العرش ، فوق جميع الخلق.\nوأما قوله: وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ [الحديد:4] فهذا معناه: بعلمه واطِّلاعه، ليس بذاته، وهو معنا، يعلم أحوالنا، ويطلع على كل شيءٍ، ويعلم ما في قلوبنا، ويعلم ما في جميع أجزاء الدنيا، ولكنه فوق العرش.\nومَن قال: \"إنه موجودٌ في كل مكانٍ\" فهذا كفرٌ وضلالٌ، يقوله الجهمية والمعتزلة ونحوهم من أهل البدع، وهذا من أقبح الكفر والضَّلال، فلا يُقال: إنَّ الله في كل مكانٍ، تعالى الله علوًّا كبيرًا، بل هو كما أخبر عن نفسه: فوق العرش، وعلمه في كل مكانٍ.","link":"https://binbaz.org.sa/fatwas/21031/ما-حكم-من-يقول-الله-موجود-في-كل-مكان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0828ما حكم من يقول الله موجود في كل مكان؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأسماء والصفات"]},{"id":1093,"question":"هذا أخٌ يقول: يُحبُّك في الله، هناك مَن يقول إنه يلزمكم من القول بإجراء النصوص على ظاهرها وعدم التَّأويل أن معية الله ذاتية، أما بتأويلكم فيلزمكم ألا تحجروا على المُؤولين في أشياء أُخرى. نرجو من سماحتكم التَّوضيح.","title":"ما حكم القول بأن معية الله ذاتية؟","answer":"الجواب:\nأحبَّكم الله الذي أحببتُمونا له، التَّحابُّ في الله من أفضل القربات، يقول النبيُّ ﷺ: سبعةٌ يُظلّهم الله في ظلِّه يوم لا ظلَّ إلا ظله، ذكر منهم: رجلين تحابَّا في الله، اجتمعا على ذلك، وتفرَّقا عليه، ويقول الله جلَّ وعلا يوم القيامة: أين المتحابُّون بجلالي؟ اليوم أُظلهم في ظلي يوم لا ظلَّ إلا ظلي، فالتَّحابُّ في الله من أفضل القربات.\nوأما التأويل: فقد أنكره السلفُ وعابوه، وأجروا النصوص على ظاهرها، وهذا أمرٌ معلومٌ، تجدونه في كتب السلف: ككتاب عبدالله بن أحمد، وعثمان بن سعيد، وكتاب \"التوحيد\" لابن خُزيمة، وغيرهم، من كتاب \"الحموية\" و\"التدمرية\" و\"العقيدة الواسطية\"، وغيرها من كتب الأئمة.\nوالمعيَّة ما فيها تأويل: المقصود بالمعية علم الله، ليس المقصود أنه معنا بذاته، مختلط بالناس في بيوتهم، وحماماتهم، ودكاكينهم، هذا لا يقوله عاقل، وإنما يقوله أهلُ الحلول، فالمعية أجمع السلف على ذلك، كما حكاه ابنُ عبدالبر، وأبو عمر الطلمنكي، وغيرهما، أجمع العلماء على أن المراد بقوله: وَهُوَ مَعَكُمْ [الحديد:4]، ولَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا [التوبة:40] يعني: بعلمه، ليس مع النبي في الغار هو والصديق، وليس معنا في بيوتنا، هو فوق العرش جلَّ وعلا، ليس هذا من التأويل، بل هذا من بيان الحقيقة التي بيَّنها الله في كتابه العظيم، حيث قال: أَلَمْ تَرَ أَنَّ اللَّهَ يَعْلَمُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَا يَكُونُ مِنْ نَجْوَى ثَلَاثَةٍ إِلَّا هُوَ رَابِعُهُمْ وَلَا خَمْسَةٍ إِلَّا هُوَ سَادِسُهُمْ وَلَا أَدْنَى مِنْ ذَلِكَ وَلَا أَكْثَرَ إِلَّا هُوَ مَعَهُمْ أَيْنَ مَا كَانُوا ثُمَّ يُنَبِّئُهُمْ بِمَا عَمِلُوا يَوْمَ الْقِيَامَةِ إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ [المجادلة:7]، فبدأها بالعلم، وختمها بالعلم.\nفالمقصود بذلك أنه محيطٌ بهم، وعالم بأحوالهم، ويرى مكانهم، ولا تخفى عليه خافيةٌ سبحانه وتعالى، كما قال : وَمَا تَكُونُ فِي شَأْنٍ وَمَا تَتْلُو مِنْهُ مِنْ قُرْآنٍ وَلَا تَعْمَلُونَ مِنْ عَمَلٍ إِلَّا كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ [يونس:61]، فهو شاهدٌ علينا، وعلى كلِّ شيءٍ شهيد ، وهو فوق العرش، وعالم بنا ومعنا، وهو فوق العرش، ومَن قال خلافَ ذلك، وأنه مع العباد في بيوتهم، وفي حماماتهم، وفي حوانيتهم، وفي خيامهم؛ فهو كافرٌ ضالٌّ عند أهل السنة والجماعة. نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/21158/ما-حكم-القول-بان-معية-الله-ذاتية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0954ما حكم من يقول أن معيَّة الله ذاتية؟ ابن باز فتاوى المحاضرات.mp3","categories":["الأسماء والصفات"]},{"id":1155,"question":"ما حكم التَّسمِّي بـ: عبدالرشيد، وعبدالموجود، وعبدالباقي، وسائر الأسماء التي فيها تعبيد لصفةٍ من صفات الله لم يثبت له اسمٌ؟","title":"حكم أسماء عبدالرشيد، عبدالموجود، عبدالباقي","answer":"الجواب:\nالقاعدة: أنه لا يجوز التَّعبيد لغير الله، لا بد أن يكون المعبَّد له اسمٌ معروفٌ من أسماء الله، فلا يُقال: عبدالموجود، ولا: عبدالقديم؛ لأنَّ هذا ما ثبت من أسماء الله ، ولا عبدالرشيد، إلا بدليلٍ، الرشيد: لا أتذكر الآن شيئًا من النصوص في الرشيد، وإذا ثبت من أسمائه الرشيد جاز، والباقي مشهورٌ: عبدالباقي، من حيث المعنى هو الباقي جلَّ وعلا، لكن لا أعلم نصًّا فيه ذكر اسم الباقي، ولكن معناه صحيح، فإنه جلَّ وعلا هو الآخر، هو الأول والآخر، والباقي بمعنى الآخر، فالأمر فيها سهلٌ، في مسألة عبدالباقي.","link":"https://binbaz.org.sa/fatwas/21208/حكم-اسماء-عبدالرشيد-عبدالموجود-عبدالباقي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1004ما حكم التسمي بعد الرشيد وعبد الموجود وعبد الباقي؟.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":1330,"question":"من أثبت أن لله يدًا لكنه أوَّل هذا الحديث؟","title":"حكم تأويل اليد لله عز وجل بالقوة والقدرة","answer":"الجواب:\nالمبتدعة يؤولونها بالنعمة والقوة، وهذا غلط، وخلاف قول أهل السنة والجماعة.  القوة صفة غير، والقدرة صفة أخرى، واليد صفة خاصة، اليد والقدم والعين والسمع؛ كل هذا صفات خاصة مستقلة غير القوة والقدرة.","link":"https://binbaz.org.sa/fatwas/21421/حكم-تاويل-اليد-لله-عز-وجل-بالقوة-والقدرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أثبت أن لله يدًا لكنه أول هذا الحديث.mp3","categories":["الأسماء والصفات"]},{"id":1331,"question":"بَسْطُ الله  يده من الصفات الذاتية أو الفعلية؟","title":"هل بَسْط الله عز وجل يده من الصفات الفعلية؟","answer":"الجواب:\nمن الصفات الفعلية. والأخذ والعطاء والضحك والرضا والغضب من الصفات الفعلية.","link":"https://binbaz.org.sa/fatwas/21422/هل-بسط-الله-عز-وجل-يده-من-الصفات-الفعلية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/بسط الله عز وجل يده من الصفات الذاتية أو الفعلية.mp3","categories":["الأسماء والصفات"]},{"id":1358,"question":"الغَيْرَة تثبت صفة؟","title":"هل الغَيْرة من صفات الله تعالى؟","answer":"الجواب:\nنعم من صفات الله، الغضب والرضا والغَيْرة من صفات الله.","link":"https://binbaz.org.sa/fatwas/21451/هل-الغيرة-من-صفات-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الغيرة من صفات الله.mp3","categories":["الأسماء والصفات"]},{"id":1378,"question":"الله خلق آدم والجنة، هل التوراة من مخلوقاته أو من صفاته؟","title":"هل التوراة من مخلوقات الله أو صفاته؟","answer":"الجواب:\nالتوراة كلام الله، التوراة والإنجيل والكتب كلام الله، أنزلها على أنبيائه، والتوراة من جُملة كلامه المُنَزَّل ومن كتبه؛ أنزلها على موسى، والإنجيل على عيسى، والزَّبُور على داود، والقرآن على محمد، عليهم الصلاة والسلام، والرسل هكذا قال تعالى: لَقَدْ أَرْسَلْنَا رُسُلَنَا بِالْبَيِّنَاتِ وَأَنْزَلْنَا مَعَهُمُ الْكِتَابَ وَالْمِيزَانَ [الحديد:25]، كل الرسل عليهم الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21471/هل-التوراة-من-مخلوقات-الله-او-صفاته","audio":"undefined","categories":["الأسماء والصفات"]},{"id":1431,"question":"مَن وقع في تأويل الصفات هل هي من الأمور الاجتهادية؟","title":"حكم التأويل في صفات الله تعالى","answer":"الجواب:\nلا، لا، هذا باطل، هذا من الضلال، هذا مِن دِين الجهمية والمعتزلة، كفر أكبر -نسأل الله العافية- نفي الصفات كفرٌ أكبر؛ لأنَّه تكذيبٌ لله -نسأل الله العافية- وتكذيبٌ للرسول ﷺ، فالذي يقول: \"إن الله ليس له رحمة، ولا يُوصَف بالعزة، ولا بالعفو، ولا بالمغفرة، ولا بالرحمة\" فهذا كفرٌ أكبر.\nس: يُؤوِّلها مثلًا؟\nج: كلها كفرٌ أكبر.","link":"https://binbaz.org.sa/fatwas/21526/حكم-التاويل-في-صفات-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التأويل في الصفات.mp3","categories":["الأسماء والصفات"]},{"id":1568,"question":"\"يمين الله في الأرض\" الحديث؟","title":"ما صحة ومعنى \"يمين الله في الأرض\"؟","answer":"الجواب:\nلا، هذا أثر عن ابن عباس، ما هو مرفوع، بل موقوف.\nس: يُحمَل على أي شيءٍ؟\nج: معناه: أن استلامه قربةٌ إلى الله، كأنَّه صافح الله، مَن استلمه كأنَّه صافح ربَّه؛ حثًّا على استلامه وترغيبًا في ذلك.\nس: حث على الاستلام؟\nج: ترغيب في الاستلام.\nس: لكن بعيد عن التشبيه؟\nج: لا ما فيه تشبيه ولهذا قال: \"فكأنما\"، \"فكأنما\" دال على التشبيه.","link":"https://binbaz.org.sa/fatwas/21671/ما-صحة-ومعنى-يمين-الله-في-الارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قول يمين الله في الأرض حديث وما معناه.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":1633,"question":"قول بعض العلماء: \"خصَّ اللهُ موسى بكلامه\" هل قولهم صحيح؟","title":"ما صحة أن الله تعالى خصَّ موسى بكلامه؟","answer":"الجواب:\nلا، ما خصَّ موسى، كلَّم محمدًا أيضًا، فمحمد وموسى الكليمان، ومحمد وإبراهيم الخليلان.\nس: كذلك آدم؟\nج: نعم، في القرآن كلَّم آدم.","link":"https://binbaz.org.sa/fatwas/21738/ما-صحة-ان-الله-تعالى-خص-موسى-بكلامه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قول بعض العلماء خصَّ اللهُ موسى بكلامه.mp3","categories":["الأسماء والصفات"]},{"id":1961,"question":"أحيانًا يقول الإنسانُ مثلًا: بوجه الله ما تفعل كذا؟","title":"حكم قول: \"بوجه الله ما تفعل كذا\" ونحوه","answer":"الجواب:\nظاهر الحديث يَعُمُّه، إلا فيما يتعلق بالجنة، تَرْكُ هذا.\nس: يعني: مثلًا إذا صار بين شخصين..؟\nج: يقول: \"أنا أستجير بالله\"... أو: \"أعوذ بالله\"، ما يقول: \"بوجه الله\"، وإنما \"بالله\".\nس: أحيانًا في حال التَّعجب يقول: \"وجه الله\"؟\nج: البعض يقول: \"يا وجه الله\"، هذا ما يجوز له، هذه الصّفات ما تُدْعَى، ما يُقال: \"يا علم الله\"، و\"يا كلام الله\"، و\"يا وجه الله\"، و\"يا يد الله\"، و\"يا أصبع الله\"، لا، \"يا الله، يا رحمن، يا رحيم\"، الدعاء لله وحده بأسمائه .","link":"https://binbaz.org.sa/fatwas/22076/حكم-قول-بوجه-الله-ما-تفعل-كذا-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم قول بوجه الله ما تفعل كذا.mp3","categories":["الأسماء والصفات"]},{"id":1965,"question":"\"السيد\" ثبت أنه اسم من أسماء الله؟","title":"هل \"السيد\" من أسماء الله؟ وحكم قوله للبشر","answer":"الجواب:\nجاء في الحديث الصحيح لما قالوا له ﷺ: أنت سيدنا، قال: السيد الله تبارك تعالى يعني: الرئيس، يعني: الكامل.\nس: سواء كان كلمة: سيد، أو سيدي؟\nج: لا يُقال: سيدي، أما \"سيد\" فما يُخالف: \"سيد بني فلان\"، مثلما قال ﷺ عن الحسن: إنَّ ابني هذا سيِّد، أما التعريف \"السيد\" فيُترك، لما قيل: يا رسول الله، أنت سيدنا، قال: السيد الله تبارك وتعالى، أما إذا قال: سيد بني جُمح، سيد بني عدنان، سيد عتبان، سيد الحبتان، مثلما قال النبي ﷺ للأنصار: قوموا إلى سيِّدكم يعني: سعد بن معاذ، بالإضافة، أو سيِّد مُقيَّد: سيد جهينة، سيد قريش.","link":"https://binbaz.org.sa/fatwas/22080/هل-السيد-من-اسماء-الله-وحكم-قوله-للبشر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من هو السيد وحكم قول سيد، أو سيدي.mp3","categories":["الأسماء والصفات"]},{"id":2218,"question":"لماذا كانت صفة التَّكبر صفةَ كمالٍ في الرب وصفةَ نقصٍ في العبد؟","title":"حقيقة صفة التَّكَبُّر في حق الربِّ والعبد","answer":"الجواب:\nلأنَّ المُتَكَبّر مُتَنَزّه عن النقائص والعيوب، أما التّكبر في حقِّ العبد فهو: الترفع عن الناس، فيرى الناس دونه، وأنهم حقيرون بالنسبة إليه، وأنه فوقهم.\nس: ينبغي على المؤمن التّواضع؟\nج: واجب، نعم.","link":"https://binbaz.org.sa/fatwas/22341/حقيقة-صفة-التكبر-في-حق-الرب-والعبد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صفة التَّكبر صفةَ كمالٍ في الرب وصفةَ نقصٍ في العبد.mp3","categories":["الأسماء والصفات"]},{"id":2221,"question":"هل يُرى الله  في الدنيا؟","title":"هل يمكن رؤية الله عز وجل في الدنيا؟","answer":"الجواب:\nلا، ما يُرى إلا في الآخرة، يراه المؤمنون في الآخرة، قال في الدنيا: لَنْ تَرَانِي [الأعراف:143]، وقال : واعلموا أنه لن يرى أحدٌ منكم ربَّه حتى يموت، حتى النبي محمد ﷺ، وحتى موسى لما أراد رؤيته قال له الربُّ: لَنْ تَرَانِي وَلَكِنِ انْظُرْ إِلَى الْجَبَلِ..، أما في الآخرة فيراه المؤمنون في الموقف وفي الجنة.\nس: وقول ابن عباس: رآه بفؤاده؟\nج: هذه رؤيا النوم... وعلم القلب.","link":"https://binbaz.org.sa/fatwas/22344/هل-يمكن-روية-الله-عز-وجل-في-الدنيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رؤية الله عز وجل في الدنيا.mp3","categories":["الأسماء والصفات"]},{"id":2244,"question":"هل من أسماء الله تعالى: الرفيق؟","title":"هل \"الرفيق\" مِن أسماء الله تعالى؟","answer":"الجواب:\nنعم، من أسماء الله تعالى: إنَّ الله رفيقٌ، مثل: جميلٌ يُحبّ الجمال.","link":"https://binbaz.org.sa/fatwas/22367/هل-الرفيق-من-اسماء-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرفيق هل هو من أسماء الله.mp3","categories":["الأسماء والصفات"]},{"id":2964,"question":"في معية الله ؟","title":"ما معنى معية الله سبحانه وتعالى؟","answer":"الجواب: كل الناس في معية الله وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ [الحديد:4] يعني في علمه وإحاطته جل وعلا وهو فوق العرش وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ [الحديد:4] بعلمه واطلاعه ورؤيته لنا وإحاطته لنا وقدرته علينا سبحانه وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ [الحديد:4] يعني بالعلم والقدرة، وهو فوق العرش فوق جميع الخلق .","link":"https://binbaz.org.sa/fatwas/23120/ما-معنى-معية-الله-سبحانه-وتعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى معية الله.mp3","categories":["الأسماء والصفات"]},{"id":3016,"question":"الحديث القدسي: وإنْ تقرَّب إليّ شِبْرا تقرَّبت إليه باعًا... إلى آخر الحديث، يُعتبر مِنْ أحاديث الصفات؟","title":"معنى الصِّفَة في حديث \"تقرَّبت إليه باعًا..\"؟","answer":"الجواب: نعم، يُجرى على ظاهره، على الوجه اللائق بالله، من أحاديث الصفات، على الوجه اللائق بالله.","link":"https://binbaz.org.sa/fatwas/23174/معنى-الصفة-في-حديث-تقربت-اليه-باعا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث وإن تقرب إليّ شبرا تقربت إليه باعا.. هل هذا من أحاديث الصفات.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":3263,"question":"صفتا السمع والبصر لله  هل هي متعلقة بالمشيئة؟","title":"هل تتعلق صفتا السمع والبصر لله بالمشيئة؟","answer":"الجواب: لا، صفاتُ ذات، السمع والبصر من صفات الذات، واليد والقدم كلها صفاتُ ذات، والوجه من صفات الذات، أما الذي يتعلق بالمشيئة..... غضبه ورضاه وكلامه وخلقه وإيجاده، كل هذه صفات اختيارية تتعلق بالمشيئة.","link":"https://binbaz.org.sa/fatwas/23427/هل-تتعلق-صفتا-السمع-والبصر-لله-بالمشيىة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تتعلق صفتي السمع والبصر لله بالمشيئة.mp3","categories":["الأسماء والصفات"]},{"id":3319,"question":"بعض أهل العلم يُخَطِّئ من قال بإثبات الملل له تعالى؟","title":"حكم إثبات صفة الملل لله عز وجل","answer":"الجواب: لا هذا غلط، ملل يليق بالله مثل، وَمَكَرُوا وَمَكَرَ اللَّهُ [آل عمران: 54]، يُخَادِعُونَ اللَّهَ وَهُوَ خَادِعُهُمْ [النساء: 142]، اللَّهُ يَسْتَهْزِئُ [البقرة: 15] كلها تليق بالله، إِنَّهُمْ يَكِيدُونَ كَيْدًا  ۝  وَأَكِيدُ كَيْدًا [الطارق: 15 - 16] كلها أوصاف تليق بالله على الوجه الذي يليق به، لا يشبه صفات المخلوقين كسائر الصفات.","link":"https://binbaz.org.sa/fatwas/23485/حكم-اثبات-صفة-الملل-لله-عز-وجل","audio":"undefined","categories":["شروح الحديث","الأسماء والصفات"]},{"id":3320,"question":"من قال إن الملل والمخادعة والكيد تكون بمقابل، لا تكون من الله  ابتداء؟","title":"هل تكون صفاتُ الملل والكيد مِن الله ابتداء؟","answer":"الجواب: مثل ما أخبر سبحانه، يكيد لهم بحق، ويخادعهم بحق، المذموم الخداع بالباطل، والمكر بالباطل، والاستهزاء بالباطل، أما إذا كان بحق فغير مذموم، لا من الله ولا من المخلوقين.","link":"https://binbaz.org.sa/fatwas/23486/هل-تكون-صفات-الملل-والكيد-من-الله-ابتداء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الملل والمخادعة والكيد هل تكون من الله ابتداء.mp3","categories":["الأسماء والصفات"]},{"id":3558,"question":"هل يجوز للإنسان حينما يشرح بعض الصفات أن يجعل أصبعه ...؟","title":"حكم الإشارة بالأصبع في شرح صفات الله","answer":"الجواب: مثل ما أشار النبي ﷺ؛ إذا كان للبيان والإيضاح بالحقيقة، ما هو للتمثيل ولا للتشبيه، ولكن للإيضاح.","link":"https://binbaz.org.sa/fatwas/23740/حكم-الاشارة-بالاصبع-في-شرح-صفات-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الإشارة بصفات الله للشرح والإيضاح.mp3","categories":["الأسماء والصفات"]},{"id":3743,"question":"يقول الذي نقل عن المهلب أن الرحمة رحمتان: رحمة من صفة الذات، وهي لا تتعدد، ورحمة من صفة الفعل، وهي المشار إليها؟","title":"ما معنى أن الرحمة رحمتان؟","answer":"الجواب: هذا مستقيم؛ لأن رحمته صفة ذاته ما هي مخلوقة، وصف له، مثل: العلم والقدرة والحكمة، هذه أوصاف ذاتية، الرحمن الرحيم.  ورحمة نوع ثان، خلقها جل وعلا، وجعلها من عموم مخلوقاته يرحم بها عباده، أنزل منها رحمة واحدة، منها ما حصل لهم من التعاطف والتراحم والتعاون وما حصل من المآكل والمشارب والمساكن والهواء والماء، كل هذا من رحمته  هذه مخلوقة، وهي من آثار رحمته التي هي وصفه ..... الرحمة المخلوقة من صفة الفعل كالخلق.\nس: يعني ما يريد الوصف؟\nالشيخ: وصف نشأ عن فعله عن إيجاده  كما أوجد الخلق الخلق والعطاء من الأوصاف الفعلية والرحمة القائمة به وصف ذاتي وقائم به كالعلم وصف ذاتي والقدرة وصف ذاتي.\nس: مستقيم هذا التقسيم؟\nالشيخ: نعم لا بأس، وبعضهم يقول أن الضابط ما كان بالاختيار والمشيئة فهذه وصف فعل، وما كان لا يتعلق بالمشيئة فهذا يقال له وصف الذات، وصف ذاتي، فالرحمة المخلوقة نشأت عن المشيئة، فالوصف الذاتي الذي هو قائم به سبحانه وصف ذاتي كالعلم ولا يتعلق بالمشيئة كالعلم والقدرة والوجه واليد وأشباه ذلك مما هي أوصاف ذاتية ملازمة.","link":"https://binbaz.org.sa/fatwas/23935/ما-معنى-ان-الرحمة-رحمتان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الرحمة من صفات الله وهي رحمتان رحمة من صفة الذات ورحمة من صفة الفعل.mp3","categories":["الأسماء والصفات"]},{"id":3936,"question":"الكَنَف (في حديث يضع كَنَفَه عليه..) ؟","title":"معنى \"يضع كَنَفَه عليه..\" في الحديث","answer":"الجواب: الله أعلم، نؤمن به ونقول لا يعلم كيفيته إلا هو .\nس: ما جاء أنه الرحمة؟\nالشيخ: هذا تأويل، لا يعلم صفته إلا هو .","link":"https://binbaz.org.sa/fatwas/24156/معنى-يضع-كنفه-عليه-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بالكنف في حديث يدنو أحدكم من ربّه حتّى يضع كنفه عليه..mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4135,"question":"قوله: يأتيهم الله في الصورة التي يعرفونها؟","title":"معنى \"يأتيهم الله في الصورة التي يعرفونها\"","answer":"الجواب: التي وعدهم بها: يَوْمَ يُكْشَفُ عَنْ سَاقٍ [القلم:42]، ساقه يعني .","link":"https://binbaz.org.sa/fatwas/24381/معنى-ياتيهم-الله-في-الصورة-التي-يعرفونها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى قوله يأتيهم الله في الصورة التي يعرفونها.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4175,"question":"س: المراد بـ لا يمل..؟","title":"معنى \"لا يمل حتى تملّوا\" في الحديث","answer":"الجواب: كسائر الصفات؛ صفة تليق بالله، قد يكون من ثمراتها قطع الثواب كما قال السلف..... أن الله يُحب نشاطهم في الأعمال حتى يملُّوا، فإذا ملُّوا ينبغي لهم أن يستريحوا حتى لا يملُّوا العبادة، يكلفون ما يُطيقون.  فالملل الذي نُسب إليه غير الملل الذي يُنسب إلينا، مللنا نقص، والملل الذي نُسب إليه سبحانه ملل ليس فيه نقص؛ كالمكر والخداع والكيد، كلها تليق بالله، ليس فيها نقص، تليق بالله  وتُناسبه على وجهٍ لا يُشابه فيه خلقه .","link":"https://binbaz.org.sa/fatwas/24431/معنى-لا-يمل-حتى-تملوا-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الملل في حديث فإن الله لا يمل حتى تملّوا..mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4203,"question":"الرحمة فيها مخلوقة... والتسعة والتسعين غير مخلوقة؟","title":"هل الرحمة منها مخلوقة وغير مخلوقة؟","answer":"الجواب: كل المائة مخلوقة \"إن الله خلق مائة رحمة\"، لكن الوصف القائم بالله غير مخلوق، وهو وصفه ، أما هذه فرحمة خارجية.","link":"https://binbaz.org.sa/fatwas/24464/هل-الرحمة-منها-مخلوقة-وغير-مخلوقة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إن الله خلق مائة رحمة... كل المائة مخلوقة.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4210,"question":"الكنف؟","title":"معنى حديث \"حتّى يضع عليه كنفه..\"","answer":"الجواب: الله أعلم، ... كما قال، كما جاء في الحديث، لا يعلم كيفيته إلا هو ، وقال بعضهم: هو سترة، ولهذا قال: سترتها عليك. والله أعلم، مثل هذا مثل سائر الصفات، فالأوْلى أن يقال: الله أعلم بمراده، يُروى كما جاء على الوجه الذي يليق بالله .","link":"https://binbaz.org.sa/fatwas/24473/معنى-حديث-حتى-يضع-عليه-كنفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى الكنف، في حديث..حتّى يضع عليه كنفه...mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4216,"question":"س: \"الصبور\" من أسماء الله الحسنى؟","title":"هل \"الصبور\" من أسماء الله الحسنى؟","answer":"الجواب: ما أعرف فيه شيئًا، ما أتذكر فيه شيئًا، لكن في معناه أنه صبور، لكن كونه يعد من الأسماء الحسنى هذا يحتاج إلى دليل، يحتاج إلى حديث.....\nالصفات كلها بالتوقيف لا بالرأي، لا تثبت لله إلا بالتوقيف، والأسماء الحسنى كذلك...\n\nس: قَالَ الْقَاضِي: وَالصَّبُورُ مِنْ أَسْمَاءِ اللَّهِ تَعَالَى، وَهُوَ الَّذِي لَا يُعَاجِلُ الْعُصَاةَ بِالِانْتِقَامِ.\nالشيخ: يحتاج إلى دليل، يحتاج إلى حديث صحيح.","link":"https://binbaz.org.sa/fatwas/24480/هل-الصبور-من-اسماء-الله-الحسنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل  الصبور  من أسماء الله الحسنى.mp3","categories":["الأسماء والصفات"]},{"id":4350,"question":"هل يوصف الله بالمكر؟","title":"هل يوصف الله تعالى بالمكر؟","answer":"الجواب: في مقابل الماكر، مثلما وصف نفسه: وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ [الأنفال:30]، في مقابل الظلمة الماكرين، مكر حق ما هو مكر لعب، مكر بحق، واستهزاء بحق، وخداع بحق.\nس: هذا من باب القصاص؟\nج: القصاص والمقابلة نعم.\nس: وتأويل الصفات هذه؟\nالجواب: تأويلها غلط، لكن ثمراتها، من باب بيان ثمراتها وهو الانتقام والعقوبة لمن مكر وخادع واستهزأ، هذا من ثمراتها، ومن مقتضاها العقوبة، مثل ما أنه يغضب، ومن مقتضى غضبه أن يعاقب من غضب عليه، يغضب سبحانه ويرضى فمن موجبات الغضب عقوبة من غضب عليه، ومن موجبات الرضا والرحمة الإحسان إلى من رحمه ورضي عنه.","link":"https://binbaz.org.sa/fatwas/24626/هل-يوصف-الله-تعالى-بالمكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يوصف الله بالمكر.mp3","categories":["الأسماء والصفات"]},{"id":4383,"question":"هل الدهر من أسماء الله؟","title":"هل الدهر من أسماء الله تعالى؟","answer":"الجواب: لا، خالق الدهر، الدهر هو الزمان، الله خالقه، ولهذا قال جل وعلا: أقلب ليله ونهاره.\nس: .. يقول أنا الدهر؟\nج: يعني أنا خالق الدهر مثل ما في الحديث: أقلب ليله ونهاره نص الحديث أقلب ليله ونهاره.\nس: أليس من صفات الله؟\nج: لا، الدهر هو المخلوق، هو الزمان.","link":"https://binbaz.org.sa/fatwas/24660/هل-الدهر-من-اسماء-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الدهر من أسماء الله.mp3","categories":["الأسماء والصفات"]},{"id":4480,"question":"التَّسمية بعبدالستار وعبدالستير؟","title":"هل تجوز التَّسمية بعبد الستار وعبد الستير؟","answer":"الجواب: عبدالستير ما فيه شيء، أما عبدالستار حتى الآن ما وقفتُ على شيءٍ منه، وإن كانت مُستعملةً، والله هو الستار ، ثم لم أقف على حديثٍ فيه لفظ الستار حتى الآن.","link":"https://binbaz.org.sa/fatwas/24760/هل-تجوز-التسمية-بعبد-الستار-وعبد-الستير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التَّسمية بعبد الستار وعبد الستير.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":4528,"question":"إنَّ الله جميل؟","title":"معنى \"إنَّ الله جميل..\"","answer":"الجواب: وصف لله بالجمال، والجمال معروف ضد الدَّمامة والقباحة، فهو أجمل شيء سبحانه، وأكرم شيء، وأكمل في كل شيء سبحانه، فهو أكمل في جميع الأوصاف: من علم، وفضل، وحكمة، وحلم، وقوة، وقدرة، وعلم، وغير هذا، فله الجمال من جميع الوجوه، والكمال من كل الوجوه .","link":"https://binbaz.org.sa/fatwas/24808/معنى-ان-الله-جميل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى إنَّ الله جميل.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":4530,"question":"التَّسمي بصفات الله  هل يُتسمَّى بها؟","title":"حكم التسمي بصفة من صفات الله","answer":"الجواب: هذه فيها تفصيل، فالذي لا يليق إلا بالله مثل: خالق الخلق، ومثل: الخلَّاق، ومثل: الرزَّاق، وفي شيء يجوز للمخلوق: العزيز، الجميل، الرحيم، وأشباه ذلك بالمؤمنين رءوف رحيم.\nس: عبدالجليل؟\nج: هذا من أسماء الله، اسم كريم، الجليل من أسماء الله، مثل عبدالرحيم.","link":"https://binbaz.org.sa/fatwas/24810/حكم-التسمي-بصفة-من-صفات-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسمي بصفة من صفات الله.mp3","categories":["الأسماء والصفات"]},{"id":4734,"question":"إطلاق الصَّانع على الله؟","title":"معنى وحكم إطلاق «الصَّانع » على الله تعالى؟","answer":"يعني: صانع العالم، من باب الإثبات، لا من باب أنه موصوف، يقال: الصانع، ولو قال: \"الخالق\" لكان أفضل؛ لأنَّ الشريعة جاءت بالخالق، وجاءت بالفعل للصنع: صُنْعَ اللَّهِ الَّذِي أَتْقَنَ كُلَّ شَيْءٍ [النمل:88]، لكن الصانع ما نعلم أنه جاء ذكره، لكن عبَّروا به مثلما يُقال: الموجود، والشيء، من باب نفي الحجة.\nوقد يُقال من باب الإيضاح للعقول، الله جعل للناس عقولًا يفهمون بها ويعقلون بها ما ينفعهم وما يضرهم، فالعباد يعرفون أي: يخضعون لهذا المدبر للكون، والقائم بهذا الكون، ففي فطرة الإنسان تعظيم هذا الذي خلق هذا الكون، ودبَّر هذا الكون، وجعل فيه ما جعل، فلا يزال هذا العقل ينمو ويزداد خضوعًا، ويزداد ذلًّا لهذا الذي خلق هذا العالم، والإنابة إليه، والتَّعلق به إلى أن تكمل المعرفة، فجاءت الرسل لتكميل هذه المعرفة وتأييدها ونصرها وتفصيلها؛ حتى يكون هذا الإنسان العاقل وهذا الجني العاقل أكمل ما كان في بصيرته بخالقه وصانعه، وأداء حقه، وترك ما يُغضبه، فإنَّ نفوس العباد وعقولهم مفطورة على هذه الأشياء؛ على الخضوع، وعلى الذل والتقرب لمن بيده التدبير والإعطاء والمنع، فالعاقل يخضع لهذا الشيء، فليس هناك إلا صانع هذا العالم وهو الله .","link":"https://binbaz.org.sa/fatwas/25046/معنى-وحكم-اطلاق-الصانع-على-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى إطلاق الصَّانع على الله.mp3","categories":["الأسماء والصفات"]},{"id":4736,"question":"القيُّوم؟","title":"ما معنى اسم الله القيُّوم؟","answer":"القيوم الذي لم يزل كذلك، الأزلي والمستقبل: اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ [البقرة:255].","link":"https://binbaz.org.sa/fatwas/25053/ما-معنى-اسم-الله-القيوم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى القيُّوم.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":4845,"question":"جاء في بعض الروايات نزول الله في ثلث الليل الآخر، وبعضها ثلث الليل الأول؟","title":"هل النزول الإلهي كل ليلة في الثلث الأول أم الآخر؟","answer":"بعض العلماء أجاب أنها باختلاف الجهات، بعض الجهات يكون الثلث الأول هو الثلث الأخير من جهة اختلاف المطالع أمريكا وغير أمريكا وأوروبا وغير أوروبا والمغرب الأقصى فتختلف الأوقات، وبعضهم يقول: أنه وهم من بعض الرواة، والصواب: الثلث الأخير، وقد ألف في هذا الشيخ تقي الدين.","link":"https://binbaz.org.sa/fatwas/25292/هل-النزول-الالهي-كل-ليلة-في-الثلث-الاول-ام-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نزول الله عز وجل إلى السماء الدنيا كل ليلة.mp3","categories":["الأسماء والصفات"]},{"id":4848,"question":"تفسير النَّفس بالذَّات في حق الله عز وجل؟","title":"ما حكم تفسير النَّفس لله عز وجل بالذَّات؟","answer":"ما أعلم فيه مانعًا، يُفسر بالذات، ويفسر بمعنى آخر أخصّ من الذات، ظاهر النصوص يشمل الذات، ويشمل معنًى آخر، مثلما قال جلَّ وعلا: تَعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ [المائدة:116] على الوجه الذي يليق بالله، لا يعلم كيفيَّتها إلا هو .","link":"https://binbaz.org.sa/fatwas/25299/ما-حكم-تفسير-النفس-لله-عز-وجل-بالذات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تفسير النَّفس لله عز وجل بالذَّات.mp3","categories":["الأسماء والصفات"]},{"id":4965,"question":"إثبات اسم الجميل لله ؟","title":"هل يثبُت اسم الجميل لله تعالى؟","answer":"الجواب: ثابت في الحديث الصحيح: إن الله جميل يحب الجمال، إن الله طيب لا يقبل إلا طيبا، إن الله رفيق يحب الرفق في الأمر كُلِّه.","link":"https://binbaz.org.sa/fatwas/27665/هل-يثبت اسم-الجميل-لله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يثبُت اسم الجميل لله ؟.mp3","categories":["الأسماء والصفات"]},{"id":5317,"question":"أسماء الله وصفاته هل هي من قبيل المُحْكَم وليست من قبيل المتشابه، أما أنها من حيث المعنى من المُحْكَم ومن حيث الكيفية من المتشابه؟","title":"هل أسماء الله وصفاته من المُحْكَم أم المتشابه؟","answer":"الجواب: هي من المُحْكَم، أسماء الله الحسنى من المُحْكَم من جهة المعنى، ولكن من جهة الكيفية لا يعلمها إلا الله، ولهذا قال السلف  ورحمهم في الصفات قالوا فيها: معلومة والكيف مجهول، الاستواء معلوم، الرحمة معلومة، الغضب معلوم، الرضا معلوم، الضحك معلوم، والكيف غير معلوم، الكيف مجهول. فالذي عليه أهل السنة والجماعة: الإيمان بالأسماء والصفات، وأنها حق، وأنها معلومة المعنى، لكن كيفيتها لا يعلمها إلا الله، ولهذا قال مالك رحمه الله: الاستواء معلوم والكيف مجهول.[1]","link":"https://binbaz.org.sa/fatwas/30979/هل-اسماء-الله-وصفاته-من-المحكم-ام-المتشابه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 037.mp3","categories":["الأسماء والصفات"]},{"id":5318,"question":"دعاء الصفة من صفات الله ما حكمه؟","title":"هل يجوز دعاء الصفة من صفات الله؟","answer":"الجواب: ما يجوز دعاء الصفة، يتوسل بها، اللهم إني أسألك بمحبتك، أعوذ بالله برضاه من سخطه وبعفوه من عقوبته. يُتوسل بها، أما أن تُسأل: لا تُسأل، ما قال: يا عين الله افعل بنا، يا يد الله ارزقنا، أو يا كلام الله انصرنا، لا، قال: يا الله يا رحمن يا رحيم، يسأل باسمه جل وعلا، الصفات لا تُسأل بإجماع المسلمين، كما قال شيخ الإسلام رحمه الله، وإنما يُتوسل بها، ويُستعاذ بها، اللهم إني أعوذ برضاك من سخطك، وبعفوك من عقوبتك، برحمتك أستغيث يا ربي، وما أشبه ذلك.[1]","link":"https://binbaz.org.sa/fatwas/30980/هل-يجوز-دعاء-الصفة-من-صفات-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 038.mp3","categories":["الأسماء والصفات"]},{"id":5347,"question":"أليس من أسماء الله: النَّاصر؟","title":"ما حكم التسمِّي بـ\"عبد الناصر\"؟","answer":"الجواب: النَّصير: نِعْمَ الْمَوْلَى وَنِعْمَ النَّصِيرُ [الأنفال:40]، أما الناصر فما أعرف فيه شيئًا من الرِّوايات. س: اسم عبد الناصر؟ ج: تركه أوْلى، إذا رأى عبد النَّصير، أو عبد الملك؛ لأنَّ الناصر لا نعرفه في شيءٍ من الرِّوايات الصَّحيحة.[1]","link":"https://binbaz.org.sa/fatwas/31038/ما-حكم-التسمي-بـعبد-الناصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fat7_majed 001.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":5358,"question":"هل يقصد هنا بالنَّفس الذَّات، أحسن الله إليك؟","title":"ما معنى النفس في حديث \"ذكرته في نفسي\"؟","answer":"الجواب: نعم. س: يرد على مَن أنكروا أنَّ لله  ذاتًا؟ ج: الذات والنفس، النفس نفسه، ذاته جلَّ وعلا . س: يعني النفس هي الذات، مُترادفتان؟ ج: الذات وما أراده الله  لا يعلم كيفيتها إلا هو ، نؤمن بنفسه؛ أنَّ له نفسًا على الوجه اللائق به جلَّ وعلا، لا يعلم كيفيتها إلا هو .[1]","link":"https://binbaz.org.sa/fatwas/31059/ما-معنى-النفس-في-حديث-ذكرته-في-نفسي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima001.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":5359,"question":"النفس صفة لله كسائر الصِّفات؟","title":"هل النفس صفة لله عز وجل كسائر الصِّفات؟","answer":"الجواب: نعم، على الوجه اللائق به، لا يعلم كيفيتها إلا هو . س: يعني صفة النَّفس ليست هي الذات؟ ج: غير الذات، نعم: تعْلَمُ مَا فِي نَفْسِي وَلَا أَعْلَمُ مَا فِي نَفْسِكَ [المائدة:116]. س: بعض الإخوة الحاضرين كتب سؤالًا حول هذا أحسن الله إليك؟ ج: النفس غير الذات، الذات شيء، والنفس شيء، لا أحد أغير من الله، لا شخصَ أغير من الله. س: لكن الذَّات ورد فيها النصُّ؟ ج: نعم، كل النصوص في الذات: اللَّهُ خَالِقُ كُلِّ شَيْءٍ [الزمر:62]، إِنَّ رَبَّكُمُ اللَّهُ [الأعراف:54]، كل هذا يرجع إلى الذات، موصوفة بالنفس أيضًا. س: الذات في اللغة؟ ج: حقيقة الشيء، ذات الشيء حقيقته.[1]","link":"https://binbaz.org.sa/fatwas/31063/هل-النفس-صفة-لله-عز-وجل-كساىر-الصفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima003.mp3","categories":["الأسماء والصفات"]},{"id":5363,"question":"قوله: الله قديم؟","title":"ما حكم قول أن الله قديم؟","answer":"الجواب: ما أعرف أنه ورد فيه شيء من الأحاديث الصحيحة، وإن استعمله بعضُ الناس، لكن المعنى صحيح، المعنى القِدَم الذي ليس قبله عَدَم بمعنى الأول، والأول هو الوارد في النصوص، وهو سبحانه لم يسبقه شيءٌ، هو الأول قبل كل شيءٍ سبحانه؛ ولهذا لم يرد في أسمائه سبحانه، قال الله: كَالْعُرْجُونِ الْقَدِيمِ [يس:39] سمَّاه: قديمًا، فأسماء الله جاء فيها الأول؛ لأنه الذي لا يُشبهه شيء . س: لكن: أعوذ بالله العظيم وبوجهه الكريم وسلطانه القديم؟ ج: هذا وصفٌ للسلطان. س: قيَّدها بقوله: الله القديم لم يزل. ج: نعم. س: يكون هذا من باب الخبر؟ ج: هذا ينفي –يعني- ما قد يُتوهم. س: الباقي أحسن الله إليك ثابت؟ ج: ما أعرفه. س: يكون مقصوده أنه يُخبر عن الله بهذا؟ ج: الأسماء توقيفية، لا يثبت فيها إلا ما جاء في النصوص، لكن معناه صحيح، هو الباقي الدائم جلَّ وعلا، المعنى صحيح، هو الباقي الدائم، لكن لا يُقال من أسمائه إلا بدليلٍ.[1]","link":"https://binbaz.org.sa/fatwas/31070/ما-حكم-قول-ان-الله-قديم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima005.mp3","categories":["الأسماء والصفات"]},{"id":5368,"question":"قوله: لا يسار (شمال) لخالقنا؟","title":"ما حكم نفي الشمال عن المولى جل وعلا؟","answer":"الجواب: هذا فيه نزاع، والصواب أنها ثابتة، كما في حديث ابن عمر: يقبض السَّماوات بيمينه، والأرض بشماله، وإن كان فيها بعض الضعف؛ لأنها من رواية بعض أولاد عمر، فيه بعض الضعف، لكن الروايات الأخرى تُؤيدها؛ لأنَّ تسمية إحداهما يمينًا تدل على أن الأخرى تُسمَّى شمالًا، وقال النبيُّ ﷺ: وكلتا يدي ربي يمين مباركة، كلها يمين في الفضل والشرف، وإن سُميت الثانية: يسارًا وشمالًا، لكنها في الشرف يمين: كلتا يدي ربي يمين مباركة، كما في الحديث الصحيح: والمقسطون على منابر من نورٍ يوم القيامة عن يمين الرحمن، وكلتا يدي ربي يمين مباركة، والله جلَّ وعلا يقول: وَالسَّمَاوَاتُ مَطْوِيَّاتٌ بِيَمِينِهِ [الزمر:67]، وفي الحديث: الأرض بشماله نعم. س: يقول: إذ اليسار من صفة المخلوقين؟ ج: كأنه خفي عليه الحديث رحمه الله، ما علَّق عليه؟ الطالب: لا. س: تعبير المؤلف باليسار مُستقيم؟ ج: اليسار هي الشمال، نعم.[1]","link":"https://binbaz.org.sa/fatwas/31081/ما-حكم-نفي-الشمال-عن-المولى-جل-وعلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima011.mp3","categories":["الأسماء والصفات"]},{"id":5369,"question":"هل يُقال أنَّ الله  له قدم وساق؟","title":"هل يصح القول أنَّ لله قدمًا وساقًا؟","answer":"الجواب: نعم، يليقان بجلاله، لا يعلم كيفيتهما إلَّا هو. س: لكن هل المقصود بالساق \"ساق\" أم الساق هي القدم؟ ج: يَوْمَ يُكْشَفُ عَنْ سَاقٍ [القلم:42] عن ساقٍ غير القدم، القرآن يُخاطب العربَ، يخاطب الناس، ساق تليق بالله، وقدم تليق بالله، لا يعلم كيفيتهما إلا هو . س: الرحمن يضع قدمه بعد خروج أهل الإيمان من النار؟ ج: ظاهر السياق -والله أعلم- أنه بعد خروجهم؛ لأنه ينزوي بعضُها إلى بعضٍ وتمتلئ، نسأل الله العافية. س: وهل يُقال أنَّ للقدم أصابع كما لليد أصابع؟ ج: الله أعلم، نقول كما جاء الحديثُ فقط ولا نزيد.[1]","link":"https://binbaz.org.sa/fatwas/31084/هل-يصح-القول-ان-لله-قدما-وساقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/tawheed_ibnkhozaima012.mp3","categories":["الأسماء والصفات"]},{"id":5495,"question":"التَّسمية بعبد السيد؟","title":"ما حكم التسمية بعبد السيد وعبد الموجود؟","answer":"الجواب: تركه أولى؛ لأنه يشتبه، وإلا فالسيد من أسماء الله، لكن كونه يتسمَّى بأسماء واضحة: بعبد الرحمن، بعبد العزيز، عبد السميع، عبد العليم، أولى، وإلا فالسيد مثلما قال ﷺ: السيد الله تبارك وتعالى والحديث لا بأسَ به. س: التَّسمية بعبد الموجود؟ ج: هو موجود سبحانه، لكن ليس من أسمائه الموجود. س: وإطلاق كلمة إذا نادى مثلًا يقول: يا سيد؟ ج: سيد أمرها سهل، لكن لا يقول: سيدي، تركها أفضل، \"سيد\" لا بأس، النبي ﷺ قال: إنَّ ابني هذا سيد الحسن، وكان يقول لرؤساء القبائل: مَن سيد بني فلان؟ مَن سيد بني فلان؟ يعني: مَن رئيسهم؟ ويقول في سعد بن معاذ: قوموا إلى سيدكم لما جاء يحكم في بني قريظة، يعني: رئيسهم.[1]","link":"https://binbaz.org.sa/fatwas/31404/ما-حكم-التسمية-بعبد-السيد-وعبد-الموجود","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 008.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":5516,"question":"توجد بعض الكتب في الأسواق والمكتبات تُقرر أنَّ مذهب السَّلف هو تفويض المعاني والكيفية؟","title":"هل مذهب السَّلف هو تفويض المعاني والكيفية؟","answer":"الجواب: لا، تفويض الكيفية فقط، والذي يقول: تفويض المعاني، غلط، مذهب السلف تفويض الكيفية، نعرف معنى \"الرحمن\"، ونعرف معنى \"الرحيم\"، ونعرف معنى \"السميع\"، ونعرف معنى \"البصير\"، ونعرف معنى \"العزيز\" و\"الحكيم\"، لكن الكيفية لا نعلمها: كيف رحمته؟ كيف استوى؟ كيف علمه؟ لا نعرف الكيفية، هؤلاء يسمون: المُفَوِّضة، وهو مذهب باطل.[1]","link":"https://binbaz.org.sa/fatwas/31449/هل-مذهب-السلف-هو-تفويض-المعاني-والكيفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 031.mp3","categories":["الأسماء والصفات"]},{"id":5523,"question":"الذي ينفي بعض الصِّفات أو كلها يَكْفُر؟","title":"ما حكم مَنْ ينفي صفات الله أو بعضها؟","answer":"الجواب: هذا فيه تفصيل، تُقام عليه الحجَّة؛ لأنه قد يجهل بعض الصِّفات، يُبين له، الذي دلَّ عليه القرآن والسُّنة يكفُر، مثل: إذا جحد الرحمن أو الرحيم أو الحكيم أو القدوس أو الملك، إذا كان عاميًّا يُبين له أنه جاء به القرآن وجاءت به السنة. س: إذا كان يؤولها يا شيخ؟ ج: التأويل... ما في خلاف، مثل الأشاعرة وغيرهم، لا يكفرون؛ لأنَّ التأويل فيه شبهة، بخلاف المعتزلة والجهمية فإنهم كفار؛ لأنهم أنكروا الصِّفات بالكلية، وأنكروا الأسماء والصِّفات، فالجهمية ما عندهم أسماء وصفات، نسأل الله العافية.[1]","link":"https://binbaz.org.sa/fatwas/31456/ما-حكم-من-ينفي-صفات-الله-او-بعضها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 038.mp3","categories":["الأسماء والصفات"]},{"id":5626,"question":"القوة والصفة؟","title":"ما تفسير قوله تعالى: {وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ..}؟","answer":"الجواب: نعم، اليد الصفة، وتُطلق على النِّعمة والقوة: وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ يعني: بقوةٍ: وَاذْكُرْ عَبْدَنَا دَاوُودَ ذَا الْأَيْدِ [ص:17] ذا القوة: أُولِي الْأَيْدِي وَالْأَبْصَارِ أولو القوة والبصر في دين الله. س: وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ يُفهم منها إثبات الأيدي لله؟ ج: القوة: وَالسَّمَاءَ بَنَيْنَاهَا بِأَيْدٍ بقوةٍ، والله - جلَّ وعلا - له يدان: بَلْ يَدَاهُ مَبْسُوطَتَانِ [المائدة:64]، اليدان غير هنا: بَنَيْنَاهَا بِأَيْدٍ هنا بالقوة.[1]","link":"https://binbaz.org.sa/fatwas/31623/ما-تفسير-قوله-تعالى-والسماء-بنيناها-بايد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 001.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":5627,"question":"ما حكم المُتشابه على الصِّفات؟","title":"ما حكم المُتشابه في صفات الله عز وجل؟","answer":"الجواب: بالنسبة إلى بعض الناس مثلما قال ابنُ عباس: يهلكون عند متشابهه. وإلا فهي من المُحكم، واضحة من المُحكم الذي لا شكَّ فيه، فهي من المُحكمات بالنظر إلى معانيها، ومن المتشابهة بالنظر إلى الكيفية، لا يعلم كيفيتها إلا الله، فهي مُحكمة من جهة المعنى، متشابهة من جهة الكيفية، لا يعلم كيفيتها إلا هو .[1]","link":"https://binbaz.org.sa/fatwas/31624/ما-حكم-المتشابه-في-صفات-الله-عز-وجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 002.mp3","categories":["الأسماء والصفات"]},{"id":5628,"question":"مَن قال: إنَّ الصفات تمر على ظاهرها إلَّا ما جاء الدليلُ من صرفها عن ظاهرها؟","title":"هل يجوز صرفُ بعض صفات الله عن ظاهرها؟","answer":"الجواب: الصِّفات على ظاهرها، على معناها الذي يليق بالله، لكن لا يعلم كيفيتها إلا هو، نعرف معنى \"الرحمن\" معناها: الرحمة، و\"العز\" معناها: العزة، و\"العليم\" معناها: العلم، و\"الاستواء\" معناها: العلو، لكن الكيفية هي التي إلى الله - جلَّ وعلا -. س: صرفها عن ظاهرها يحتاج دليلًا؟ ج: ما يجوز صرفها عن ظاهرها إلا بدليلٍ يدل على معنى قاله الله ورسوله.[1]","link":"https://binbaz.org.sa/fatwas/31625/هل-يجوز-صرف-بعض-صفات-الله-عن-ظاهرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alsana albaghawi 003.mp3","categories":["الأسماء والصفات"]},{"id":5646,"question":"يُقال: الله في السَّماء أو فوق السَّماء؟","title":"هل يُقال: الله في السَّماء؟ أو فوق السَّماء؟","answer":"الجواب: أين الله؟ قالت: في السَّماء لما سأل الجارية، قال: أين الله؟ قالت: في السَّماء. أي: في العلو، السَّماء المراد بها العلو، مثلما قال تعالى: أَأَمِنْتُمْ مَنْ فِي السَّمَاءِ [الملك:16] يعني: في العلو؛ لأنَّ السماء يُطلق على أمرين: يُطلق على السَّماء المبنية، يُقال لها: سماء. ويُطلق على العلو يُقال: سماء.[1]","link":"https://binbaz.org.sa/fatwas/31658/هل-يقال-الله-في-السماء-او-فوق-السماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/alaistiqama 007.mp3","categories":["الأسماء والصفات"]},{"id":6114,"question":"إذا كان والدي قد سماني باسم: عبدالمعطي، والعلماء اليوم منهم من ينكر الأسماء، سوى الواردة في القرآن من أسماء الله تعالى، فهل علي أن أغير اسمي إلى عبدالقدوس، أو غيره؟","title":"حكم التسمي بـ عبد المعطي","answer":"الجواب: لا، المعطي من أسماء الله، ثبت في الصحيحين من حديث معاوية، عن النبي -عليه الصلاة والسلام- أنه قال: إنما أنا قاسم، والله هو المعطي فالمعطي من أسماء الله، اسم عبدالمعطي لا بأس.","link":"https://binbaz.org.sa/fatwas/1523/حكم-التسمي-بـ-عبد-المعطي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_453.mp3","categories":["أحكام المولود","الأسماء والصفات"]},{"id":6880,"question":"ما معنى أن الله واحد في صفاته، وأسمائه، مع أن هناك من يشترك معه في التسمية من العباد؟","title":"معنى أن الله واحد في أسمائه وصفاته","answer":"الجواب:\nمعنى ذلك أنه واحد في معنى الصفات، الحكيم العليم الرحمن الرحيم، والقدير، وإن سمي بعض الأطباء حكيمًا، وإن سمي بعض الناس حكيمًا، وإن سمي بعض الناس عزيزًا، إلى غير ذلك، لكن العزة المطلقة لله وحده، والحكمة المطلقة لله وحده، والقدرة المطلقة لله وحده. فالمعنى: من اعتقد أن غير الله يشاركه في هذا المعنى، وأن له مثل صفة الله في العزة، أو في الحكمة، أو في الرحمة، أو في القدرة، أو في العلم؛ كفر بالله، أما كونه يشارك في بعض الشيء، له قدرة تليق بالمخلوق، فهذا لا يقع فيه الشرك، الله سمى نفسه سميعًا بصيرًا، وسمى عبده سميعًا بصيرًا.  فالمقصود: أن جنس المشاركة في جنس القدرة، جنس العلم، جنس السمع، جنس البصر، لكن قدرة محدودة، وعلم محدود، وبصر محدود، فالإنسان له بصر محدود، وسمع محدود، وعلم محدود، وقدرة محدودة، هذه ليس فيها شركة لله  هذه الله الذي أعطاه إياها، ومنّ بها عليه  لكن إذا قال: له قدرة من جنس قدرة الله، وأنه يتصرف في الكون كما يشاء، أو أنه يعلم المغيبات، أو ما أشبه كالله هذا هو المعنى.","link":"https://binbaz.org.sa/fatwas/2779/معنى-ان-الله-واحد-في-اسماىه-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1271.mp3","categories":["الأيمان والنذور","الأسماء والصفات"]},{"id":6896,"question":"ما معنى أن الله واحد في صفاته، وأسمائه، مع أن هناك من يشترك معه في التسمية من العباد؟","title":"معنى أن الله واحد في أسمائه وصفاته","answer":"الجواب:\nمعنى ذلك أنه واحد في معنى الصفات، الحكيم العليم الرحمن الرحيم، والقدير، وإن سمي بعض الأطباء حكيمًا، وإن سمي بعض الناس حكيمًا، وإن سمي بعض الناس عزيزًا، إلى غير ذلك، لكن العزة المطلقة لله وحده، والحكمة المطلقة لله وحده، والقدرة المطلقة لله وحده. فالمعنى: من اعتقد أن غير الله يشاركه في هذا المعنى، وأن له مثل صفة الله في العزة، أو في الحكمة، أو في الرحمة، أو في القدرة، أو في العلم؛ كفر بالله، أما كونه يشارك في بعض الشيء، له قدرة تليق بالمخلوق، فهذا لا يقع فيه الشرك، الله سمى نفسه سميعًا بصيرًا، وسمى عبده سميعًا بصيرًا.  فالمقصود: أن جنس المشاركة في جنس القدرة، جنس العلم، جنس السمع، جنس البصر، لكن قدرة محدودة، وعلم محدود، وبصر محدود، فالإنسان له بصر محدود، وسمع محدود، وعلم محدود، وقدرة محدودة، هذه ليس فيها شركة لله  هذه الله الذي أعطاه إياها، ومنّ بها عليه  لكن إذا قال: له قدرة من جنس قدرة الله، وأنه يتصرف في الكون كما يشاء، أو أنه يعلم المغيبات، أو ما أشبه كالله هذا هو المعنى.","link":"https://binbaz.org.sa/fatwas/2779/معنى-ان-الله-واحد-في-اسماىه-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1271.mp3","categories":["الأيمان والنذور","الأسماء والصفات"]},{"id":6974,"question":"اختلفت مع بعض إخوان لي اليوم، فهل الله  في السماء، لا ينزل الأرض، أم أنه كما تقول الآية: وَهُوَ الَّذِي فِي السَّمَاءِ إِلَهٌ وَفِي الْأَرْضِ إِلَهٌ [الزخرف:84] نرجو إفادتنا، جزاكم الله خيرًا؟","title":"بيان علو الله جل وعلا","answer":"الجواب:\n\nالله  في السماء في العلو -جل وعلا- فوق العرش  كما قال : الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]\n\nوقال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] وقال : أَأَمِنْتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الْأَرْضَ [الملك:16] قال: بَلْ رَفَعَهُ اللَّهُ إِلَيْهِ [النساء:158] يَا عِيسَى إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ [آل عمران:55].\n\nفهو سبحانه فوق السماء، فوق العرش -جل وعلا- وليس في الأرض، بل هو فوق جميع الخلق  هذا الذي عليه أهل السنة والجماعة من أصحاب النبي ﷺ ومن تبعهم بإحسان، وهو الذي جاءت به الرسل جميعًا -عليهم الصلاة والسلام- أن الله فوق السماء، فوق العرش، في العلو، في جهة العلو -جل علا- وعلمه في كل مكان  لا يخفى عليه خافية  وجميع أعمال العباد تصعد إليه إن كانت صالحة، وإن كانت غير صالحة؛ ردت على أصحابها، ولا حول ولا قوة إلا بالله.\n\nأما قوله -جل وعلا-: وَهُوَ الَّذِي فِي السَّمَاءِ إِلَهٌ وَفِي الْأَرْضِ إِلَهٌ [الزخرف:84] معناه: أنه إله أهل السماء، وإله أهل الأرض، وهكذا قوله سبحانه: وَهُوَ اللَّهُ فِي السَّمَاوَاتِ وَفِي الْأَرْضِ يَعْلَمُ سِرَّكُمْ وَجَهْرَكُمْ [الأنعام:3] يعني هو إله لأهل السماء، وهو إله لأهل الأرض، يعني يعبدونه وحده  فهو إله الجميع: إله أهل السماء، وإله أهل الأرض، وإن كان فوق العرش -جل وعلا- فيعبده الملائكة في السماء، ويعبده المؤمنون في الأرض أينما كانوا، فهو إلههم، وفوقهم سبحانه، فوق جميع الخلق .\n\nس: مَا يَكُونُ مِنْ نَجْوَى ثَلَاثَةٍ إِلَّا هُوَ رَابِعُهُمْ [المجادلة:7]؟\n\nج: يعني بعلمه.\n\nس:  وَهُوَ مَعَكُمْ أَيْنَ مَا كُنْتُمْ [الحديد:4]؟\n\nج: يعني بعلمه  وهو فوق عرشه -جل وعلا-.","link":"https://binbaz.org.sa/fatwas/2909/بيان-علو-الله-جل-وعلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1357.mp3","categories":["الأيمان والنذور","الأسماء والصفات"]},{"id":8875,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى برنامج من العراق- الأنبار بتوقيع المستمعة (أ.أ.) أختنا لها أربعة أسئلة: تقول في سؤالها الأول: يوجد كتاب اسمه القول الأسنى في الأسماء الحسنى وبه أشياء وأعمال أعتقد أنها سحر، ومن الأمثلة الموجودة فيه: أن يكتب الشخص (جل جلاله) ثلاث وسبعين مرة على قرطاس ويمحيه ثم يشربه، وبذلك يصبح وقوراً بين الناس، فهل هو سحر أم ماذا؟","title":"تقييم كتاب (القول الأسنى في الأسماء الحسنى)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفلم أطلع على هذا الكتاب ولكن ما ذكرته السائلة مما قال فيه: وهو أن يكتب (جل جلاله) مرات معدودة ثم يشربها ويكون بهذا وقوراً هذا لا أصل له، هذا من الكذب، وهذا مما يدل على أن الكتاب ليس بمضبوط وأن صاحبه غير مضبوط، وأنه لا ينبغي الاعتماد عليه. نعم.","link":"https://binbaz.org.sa/fatwas/7031/تقييم-كتاب-القول-الاسنى-في-الاسماء-الحسنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_139/13901.mp3","categories":["الأسماء والصفات"]},{"id":8926,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من ليبيا باعثها أحد الإخوة من هناك يقول: إبراهيم محمد العبدلي، أخونا له مجموعة من الأسئلة:في سؤاله الأول يقول: هناك بعض الناس يقولون بأن الخطوط التي في كفي يدي الإنسان إنها على شكل رقمين (18) في اليد اليمنى و(81) في اليد اليسرى والمجموع تسعة وتسعين ويقول: إنها بعدد أسماء الله الحسنى، فهل لهذا أثر صحيح؟","title":"هل الخطوط التي في يد الإنسان هي عدد الأسماء الحسنى؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الذي قاله بعض الناس لا أصل له ولم يبلغنا عن أحد من أهل العلم أنه قاله، بل هو شيء مؤتفك لا أصل له ولا ينبغي التعويل عليه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7083/هل-الخطوط-التي-في-يد-الانسان-هي-عدد-الاسماء-الحسنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_143/14301.mp3","categories":["الأسماء والصفات"]},{"id":9262,"question":"نترك بقية أسئلة الأخ عبدالرحمن مبروك سلامة من جمهورية مصر العربية إلى حلقة قادمة إن شاء الله وننتقل إلى رسالة وصلت إلى البرنامج من الأخت (ن.ر.و.) مصرية أيضاً مقيمة في الكويت، أختنا تقول: دائماً نقول: الله عز وجل، الله رب الأرباب، ما معنى عز وجل، وما معنى رب الأرباب؟","title":"معنى (عز وجل) و(رب الأرباب)","answer":"الجواب: معنى عز وجل يعني: صار عزيزاً وجليلاً عظيماً، فله العزة الكاملة كما قال تعالى: وَلِلَّهِ الْعِزَّةُ وَلِرَسُولِهِ [المنافقون:8]، يعني: القهر والغلبة والقوة، وكذلك جل، يعني: صار جليلاً له الجلال والعظمة والكبرياء سبحانه وتعالى، فهو الجليل العظيم، وهو العزيز الذي هو أعز شيء وأجل شيء ، وهو القاهر لعباده والعزيز الغالب لهم، وهو الذي يتصف بالجلال الكامل يعني: بالعظمة الكاملة.\nوأما رب الأرباب فمعناه: رب المخلوقات فإن الدار لها رب، والأرض لها رب، والنخل له رب، والأنعام لها رب يعني: مالك، وهكذا، يسمى: رب الدار، رب الأنعام، رب الأرض، يعني: صاحبها، فهو رب هذه الأرباب يعني: رب هذه المخلوقات التي لها أتباع، صاحب الغنم يقال: رب الغنم، وصاحب الدار يقال: رب الدار، وصاحب الإبل يقال: رب الإبل، فالمعنى: أن الله هو رب الجميع وإن سموا أرباباً هم لكنهم مملوكون له سبحانه وهم عبيده، فهو رب الأرباب يعني: رب المخلوقات جميعاً، مربوبها ورابها، عبيدها وأحرارها، جمادها وعاقلها إلى غير ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/7425/معنى-عز-وجل-ورب-الارباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_153/15312.mp3","categories":["الأسماء والصفات"]},{"id":9296,"question":"وفي آخر رسالته أضاف سؤالاً رابعاً قال فيه: قال تعالى: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] فيسأل عن معنى الاستواء؟","title":"معنى قوله تعالى:(الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى)","answer":"الجواب: قوله : الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]، فسره علماء السنة بأنه العلو والارتفاع، يعني: ارتفع فوق العرش وعلا فوقه سبحانه وتعالى بدون كيف، أهل السنة والجماعة وهم أصحاب النبي ﷺ وأتباعهم بإحسان يقولون في صفات الرب : إن الواجب إثباتها وإمرارها كما جاءت بلا كيف، يعني: نثبتها لله ونؤمن بها وأنها حق، ولكن لا نكيفها، لا نقول: إنها بكيفية كذا وكيفية كذا، سئل مالك بن أنس إمام دار الهجرة في زمانه، وأحد الأئمة الأربعة، سئل رحمة الله عليه عن قوله جل وعلا: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى ، كيف استوى؟ فأطرق طويلاً ثم قال رحمه الله: الاستواء معلوم، والكيف مجهول، والإيمان به واجب، فالواجب على أهل العلم والإيمان، وعلى جميع المسلمين أن يؤمنوا بأسماء الله وصفاته التي جاءت في القرآن العظيم أو السنة الصحيحة، وأن يمروها كما جاءت من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، بل يؤمنون بأنها صفات الله وأنها أسماؤه وأنها حق، وأن معانيها حق يليق بالله جل وعلا، معانيها تليق بالله لا يشابه خلقه في شيء من صفاته سبحانه وتعالى.\nفالاستواء: هو العلو والارتفاع فوق العرش، وهو معلوم من حيث اللغة العربية، ولكن كيفيته مجهولة، ما نعلم كيف استوى، ولكن نقول: إنه استوى على عرشه وارتفع فوق عرشه ارتفاعاً يليق بجلاله وعظمته لا يشابه الخلق في صفاتهم، لا في الاستواء ولا في غيره؛ لقوله : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] ؛ ولقوله : فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74] وقوله سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، فهو سبحانه الكامل في ذاته وأسمائه وصفاته وأفعاله لا شبيه له، ولا سمي له، ولا كفء له، ولا ند له سبحانه وتعالى.\nهذا هو الواجب على أهل الإسلام أن يؤمنوا بهذه الصفات الاستواء والرحمة، والسمع والبصر، والغضب والوجه، واليد والقدم، والأصابع وغير هذا من صفاته سبحانه وتعالى، كلها يجب إثباتها لله على الوجه اللائق بالله من غير تحريف ولا تعطيل لصفات الله، ولا تكييف لها، ولا تمثيل لها، بل يقال: إنها حق، وإنها ثابتة لله على الوجه اللائق به ، لا يشابه خلقه في شيء من صفاته جل وعلا؛ لأنه سبحانه وتعالى لا مثيل له، لا في ذاته، ولا في صفاته . نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7464/معنى-قوله-تعالىالرحمن-على-العرش-استوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_236/23607.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":9367,"question":"أم مجاهد سودانية بدولة الإمارات تسأل أيضًا سؤالًا آخر وتقول فيه: قال زوجي في إحدى خطب الجمعة: إن الله في السماء مستوٍ على العرش، بائن من خلقه، وهو في السماء السابعة، فذهب أحد الناس يستنكر عليه وشنع به، ونطلب من سماحتكم القول الواضح في هذا الموضوع جزاكم الله خيرا؟","title":"إثبات صفة العلو لله جل وعلا","answer":"الجواب: قد أحسن زوجك فيما قال، وأصاب الحق فيما قال، فالله  فوق العرش فوق جميع السماوات، وفوق جميع الخلق، كما قال : إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] والاستواء معناه: العلو والارتفاع، يعني: ثم علا على العرش وارتفع عليه ، فهو فوق العرش وعلمه في كل مكان عند أهل السنة والجماعة، وهذا هو الذي جاءت به الرسل عليهم الصلاة والسلام، وعلى رأسهم نبينا وإمامنا محمد عليه الصلاة والسلام.\nوهو قول أصحاب النبي جميعًا ، كلهم درجوا على أن الله في العلو فوق العرش فوق جميع الخلق، وعلمه في كل مكان سبحانه وتعالى، كما قال جل وعلا: فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12] وقال: وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] فله العلو الكامل ، من جميع الوجوه: علو الذات، وعلو القدر والشرف، وعلو السلطان والقهر ، وهو فوق العرش فوق جميع الخلق، استوى على العرش استواءً يليق بجلاله وعظمته، كما قال سبحانه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] قال هذا في سبعة مواضع من كتابه العظيم، فالواجب على كل مسلم وعلى كل مسلمة الإيمان بذلك، والإمرار للصفات كما جاءت من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، وإنكار الاستواء من مذهب الجهمية ، مذهب أهل البدع، فالواجب على أهل الإسلام ذكورًا وإناثًا أن يؤمنوا بذلك كما جاء في القرآن العظيم، وأن يسيروا على نهج أهل السنة في إثبات علو الله فوق جميع الخلق فوق السماء السابعة فوق جميع الخلق، فوق العرش، فإن العرش فوق السماء السابعة، فوق السماء السابعة الكرسي، ثم هناك بحر بين أسفله وأعلاه كما بين السماوات والأرض ثم بعد ذلك العرش، فالعرش فوق الماء، والعرش هو سقف المخلوقات وهو أعلاها، والله فوق العرش  فوق جميع الخلق جل وعلا، ولهذا قال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ أَلا لَهُ الْخَلْقُ وَالأَمْرُ تَبَارَكَ اللَّهُ رَبُّ الْعَالَمِينَ [الأعراف:54] وقال : الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] وقال: ثُمَّ اسْتَوَى عَلَى الْعَرْشِ الرَّحْمَنُ فَاسْأَلْ بِهِ خَبِيرًا [الفرقان:59] في آيات سبع كلها دالة على علوه، وفوقيته واستوائه على العرش ، فالذي أنكر على زوجك هو الذي قد أخطأ وغلط ووافق أهل البدع وخالف أهل السنة، وأما زوجك في إخباره بأن الله فوق العرش فوق السماء فوق جميع الخلق فقد أصاب، ووافق أهل السنة، ووافق الكتاب والسنة، وخالف أهل البدع.\nفنسأل الله لنا ولكم ولزوجك ولجميع المسلمين التوفيق والهداية والاستقامة على الحق.","link":"https://binbaz.org.sa/fatwas/7531/اثبات-صفة-العلو-لله-جل-وعلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18607.mp3","categories":["الأسماء والصفات"]},{"id":9371,"question":"شيخ عبدالعزيز نعود في بداية لقائنا إلى رسالة الأخ: عبدالله بن محمد بن عبد الله أخونا في حلقة مضت عرضنا بعض أسئلته وفي هذه الحلقة يسأل ويقول: ورد حديث عن النبي ﷺ ينهى فيه عن تقبيح الوجه، وأن الله خلق آدم على صورته، فما الاعتقاد السليم نحو هذا الحديث؟","title":"معنى قوله: (إن الله خلق آدم على صورته)","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالحديث ثابت عن رسول الله عليه الصلاة والسلام أنه قال: إذا ضرب أحدكم فليتق الوجه فإن الله خلق آدم على صورته وفي لفظ آخر: على صورة الرحمن وهذا لا يلزم منه التشبيه والتمثيل، فالمعنى عند أهل العلم أن الله خلق آدم سميعًا بصيرًا متكلمًا إذا شاء، وهذا هو وصف الله ، فإنه سميع بصير متكلم ذو وجه جل وعلا، وليس المعنى التشبيه والتمثيل بل الصورة التي لله غير الصورة التي للمخلوق، وإنما المعنى أنه سميع بصير ذو وجه ومتكلم إذا شاء.\nوهكذا خلق الله آدم سميعًا بصيرًا ذا وجه وذا يد وذا قدم ويتكلم إذا شاء، لكن ليس السميع كالسميع وليس البصير كالبصير وليس المتكلم كالمتكلم وليس الوجه كالوجه بل لله صفاته سبحانه وتعالى لا يشابهه فيها شيء بل تليق به سبحانه، وللعبد صفاته التي تليق به صفات يعتريها الفناء والنقص والضعف، أما صفات الله سبحانه فهي كاملة لا يعتريها نقص ولا ضعف ولا فناء ولا زوال، ولهذا قال : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] .. وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] فلا يجوز ضرب الوجه ولا تقبيح الوجه. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7535/معنى-قوله-ان-الله-خلق-ادم-على-صورته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_157/15701.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":9481,"question":"له سؤال أخير في الحقيقة، ولا أدري يعني أن هذا السؤال هو وغيره من الأسئلة تأخذ طابع الأسئلة العلمية التي ربما تحتاج إجابتها لإفاضة، ونحن نحبذ في هذا البرنامج إرسال الأسئلة على سبيل الفتوى فيما يتعلق بالعبادات النافعة لجميع الناس، أما الأسئلة الخاصة العلمية فحبذا لو ترسل إلى أصحاب الفضيلة على عناوينهم الخاصة ليعود الجواب مفصلاً فيها، فمثل سؤال الأخ الذي يقول فيه، وأعرضه أنا ليكون نموذجاً، وأنا أعلم أن سماحة الشيخ سيجيب عليه جزاه الله خيراً وبارك الله فيه، لكن أحببت أن أقدم هذه المقدمة حتى يخفف الناس من مثل هذه الأسئلة، يقول: سمعنا من بعض العلماء أن أهل السنة والجماعة يتأولون بعض الآيات في -ربما يقصد- في الصفات، فهل هذا صحيح أنه من مذهبهم التأويل، أم أنهم يضطرون إلى ذلك، أفيدونا أفادكم الله؟","title":"مذهب أهل السنة في آيات وأحاديث الصفات","answer":"الجواب: الصواب الذي قرره أهل العلم من أهل السنة والجماعة أنه لا تأويل في آيات الصفات ولا في أحاديثها، وإنما المؤولون هم الجهمية والمعتزلة ، والأشاعرة في بعض الصفات، وأما أهل السنة والجماعة المعروفون بعقيدتهم النقية فإنهم لا يؤولون، بل يمرون آيات الصفات وأحاديثها كما جاءت من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، لا الاستواء، ولا القدم، ولا اليد، ولا الأصابع، ولا الضحك، ولا الرضا، ولا الغضب، كلها يمرونها كما جاءت، مع الإيمان بأنها حق، وأنها صفات لربنا جل وعلا يجب إثباتها له سبحانه وتعالى، على الوجه اللائق به من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، بعض الناس يؤول الضحك بأنه الرضا، أو يؤول المحبة بأنها إرادة الثواب أو بمعنى كذا، والرحمة كذلك، وهذا كله لا يرضاه أهل السنة والجماعة ، بل الواجب إمرارها كما جاءت وأنها حق، فهو سبحانه يحب محبة حقيقية تليق به لا يشابه فيها محبة المخلوقين، يرضى، ويغضب، ويكره، صفات حقيقية يتصف بها ربنا على الوجه اللائق به سبحانه وتعالى، لا يشابه فيها خلقه، كما قال : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، وهكذا يضحك كما جاءت به النصوص ضحكاً يليق بجلاله لا يشابه خلقه في شيء من صفاته، وهكذا استواؤه على عرشه استواء يليق بجلاله وعظمته لا يشابه خلقه في شيء من صفاته .\nولاشك أن هذه السؤالات إذا كانت من العلماء رأساً بالكتابة حتى يبسط فيها الجواب مناسب، ولكن إذا اختصر الكلام فيها في هذا البرنامج للفائدة العامة فلا بأس مع الاختصار.\nالمقصود أن التأويل لا يجوز، بل الواجب إمرار آيات الصفات وأحاديثها كما جاءت، لكن مع الإيمان بأنها حق، وأنها صفات لله لائقة به، أما التفويض فلا يجوز، المفوضة قال أحمد فيهم: إنهم شر من الجهمية ، فلا يجوز التفويض، والتفويض أن يقولوا: الله أعلم بمعناها وبس، هذا لا، معانيها معلومة عند العلماء. قال مالك رحمه الله: الاستواء معلوم والكيف مجهول. وهكذا جاء هذا عن أم سلمة وعن ربيعة بن أبي عبد الرحمن، وعن غيرهم من أهل العلم، معاني الصفات معلوم يعلمه أهل السنة والجماعة، معنى الرضا والغضب والمحبة والاستواء والضحك، وأنها معانٍ غير المعاني الأخرى، فالضحك غير الرضا، والرضا غير الغضب، والغضب غير المحبة، والسمع غير البصر كلها معلومة، لكنها لا تشابه صفات المخلوقين، ربنا يقول سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74]، ويقول سبحانه: )لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ( [الشورى:11]، ويقول : وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، هذا هو الحق الذي عليه أهل السنة من أصحاب النبي ﷺوأتباعهم بإحسان، ومن تأول ذلك فقد خالف أهل السنة في الصفة أو في أكثر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7649/مذهب-اهل-السنة-في-ايات-واحاديث-الصفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24110.mp3","categories":["الأسماء والصفات"]},{"id":9487,"question":"له سؤال أخير في الحقيقة، ولا أدري يعني أن هذا السؤال هو وغيره من الأسئلة تأخذ طابع الأسئلة العلمية التي ربما تحتاج إجابتها لإفاضة، ونحن نحبذ في هذا البرنامج إرسال الأسئلة على سبيل الفتوى فيما يتعلق بالعبادات النافعة لجميع الناس، أما الأسئلة الخاصة العلمية فحبذا لو ترسل إلى أصحاب الفضيلة على عناوينهم الخاصة ليعود الجواب مفصلاً فيها، فمثل سؤال الأخ الذي يقول فيه، وأعرضه أنا ليكون نموذجاً، وأنا أعلم أن سماحة الشيخ سيجيب عليه جزاه الله خيراً وبارك الله فيه، لكن أحببت أن أقدم هذه المقدمة حتى يخفف الناس من مثل هذه الأسئلة، يقول: سمعنا من بعض العلماء أن أهل السنة والجماعة يتأولون بعض الآيات في -ربما يقصد- في الصفات، فهل هذا صحيح أنه من مذهبهم التأويل، أم أنهم يضطرون إلى ذلك، أفيدونا أفادكم الله؟","title":"مذهب أهل السنة في آيات وأحاديث الصفات","answer":"الجواب: الصواب الذي قرره أهل العلم من أهل السنة والجماعة أنه لا تأويل في آيات الصفات ولا في أحاديثها، وإنما المؤولون هم الجهمية والمعتزلة ، والأشاعرة في بعض الصفات، وأما أهل السنة والجماعة المعروفون بعقيدتهم النقية فإنهم لا يؤولون، بل يمرون آيات الصفات وأحاديثها كما جاءت من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، لا الاستواء، ولا القدم، ولا اليد، ولا الأصابع، ولا الضحك، ولا الرضا، ولا الغضب، كلها يمرونها كما جاءت، مع الإيمان بأنها حق، وأنها صفات لربنا جل وعلا يجب إثباتها له سبحانه وتعالى، على الوجه اللائق به من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، بعض الناس يؤول الضحك بأنه الرضا، أو يؤول المحبة بأنها إرادة الثواب أو بمعنى كذا، والرحمة كذلك، وهذا كله لا يرضاه أهل السنة والجماعة ، بل الواجب إمرارها كما جاءت وأنها حق، فهو سبحانه يحب محبة حقيقية تليق به لا يشابه فيها محبة المخلوقين، يرضى، ويغضب، ويكره، صفات حقيقية يتصف بها ربنا على الوجه اللائق به سبحانه وتعالى، لا يشابه فيها خلقه، كما قال : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، وهكذا يضحك كما جاءت به النصوص ضحكاً يليق بجلاله لا يشابه خلقه في شيء من صفاته، وهكذا استواؤه على عرشه استواء يليق بجلاله وعظمته لا يشابه خلقه في شيء من صفاته .\nولاشك أن هذه السؤالات إذا كانت من العلماء رأساً بالكتابة حتى يبسط فيها الجواب مناسب، ولكن إذا اختصر الكلام فيها في هذا البرنامج للفائدة العامة فلا بأس مع الاختصار.\nالمقصود أن التأويل لا يجوز، بل الواجب إمرار آيات الصفات وأحاديثها كما جاءت، لكن مع الإيمان بأنها حق، وأنها صفات لله لائقة به، أما التفويض فلا يجوز، المفوضة قال أحمد فيهم: إنهم شر من الجهمية ، فلا يجوز التفويض، والتفويض أن يقولوا: الله أعلم بمعناها وبس، هذا لا، معانيها معلومة عند العلماء. قال مالك رحمه الله: الاستواء معلوم والكيف مجهول. وهكذا جاء هذا عن أم سلمة وعن ربيعة بن أبي عبد الرحمن، وعن غيرهم من أهل العلم، معاني الصفات معلوم يعلمه أهل السنة والجماعة، معنى الرضا والغضب والمحبة والاستواء والضحك، وأنها معانٍ غير المعاني الأخرى، فالضحك غير الرضا، والرضا غير الغضب، والغضب غير المحبة، والسمع غير البصر كلها معلومة، لكنها لا تشابه صفات المخلوقين، ربنا يقول سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74]، ويقول سبحانه: )لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ( [الشورى:11]، ويقول : وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، هذا هو الحق الذي عليه أهل السنة من أصحاب النبي ﷺوأتباعهم بإحسان، ومن تأول ذلك فقد خالف أهل السنة في الصفة أو في أكثر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7649/مذهب-اهل-السنة-في-ايات-واحاديث-الصفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24110.mp3","categories":["الأسماء والصفات"]},{"id":9939,"question":"وأولى رسائل هذه الحلقة وردتنا من المستمع صالح العبد العزيز المحمد الطوالة من الزلفي، يقول الأخ صالح في رسالته: لقد قرأت في رياض الصالحين بتصحيح السيد علوي المالكي ومحمود أمين النواوي فقرأت حديثًا قدسيًا يتطرق إلى هرولة الله سبحانه وتعالى، والحديث هو المروي عن أنس  عن النبي ﷺ فيما يرويه عن ربه  قال: إذا تقرب العبد إلي شبرًا تقربت إليه ذراعًا، وإذا تقرب إلي ذراعًا تقربت منه باعًا وإذا أتاني يمشي أتيته هرولة رواه البخاري .فقال المعلقان في تعليقهما عليه: إن هذا من باب التمثيل وتصوير المعقول بالمحسوس لزيادة إيضاحه، فمعناه: أن من أتى شيئًا من الطاعات ولو قليلًا أثابه الله بأضعافه وأحسن إليه بالكثير، وإلا فقد قامت البراهين القطعية على أنه ليس هناك تقرب حسي ولا مشي ولا هرولة من الله  عن صفات المحدثين، فهل ما قالاه في المشي والهرولة موافقًا لما قاله سلف الأمة على إثبات صفات الله وإمرارها كما جاءت، وإذا كان هناك براهين دالة على أنه ليس هناك مشي ولا هرولة فنرجو منكم إيضاحها والله الموفق؟","title":"طريقة السلف في إثبات صفات الله عز وجل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن الحديث المذكور صحيح، فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: يقول الله : من ذكرني في نفسه ذكرته في نفسي، ومن ذكرني في ملأ ذكرته في ملأ خير منهم، ومن تقرب إلي شبرًا تقربت منه ذراعًا، ومن تقرب مني ذراعًا تقربت منه باعًا، ومن أتاني يمشي أتيته هرولة وهذا الحديث الصحيح يدل على عظيم فضل الله ، وأنه بالخير إلى عباده أجود فهو أسرع إليهم بالخير والكرم والجود منهم في أعمالهم ومسارعتهم إلى الخير والعمل الصالح، ولا مانع من إجراء الحديث على ظاهره على طريق السلف الصالح، فإن أصحاب النبي ﷺ سمعوا هذا الحديث من رسول الله ﷺ ولم يعترضوه ولم يسألوا عنه ولم يتأولوه وهم صفوة الأمة وخيرها، وهم أعلم الناس باللغة العربية، وأعلم الناس بما يليق بالله وما يليق نفيه عن الله .\nفالواجب في مثل هذا أن يتلقى بالقبول وأن يحمل على خير المحامل، وأن هذه الصفة تليق بالله، لا يشابه فيها خلقه، فليس تقربه إلى عبده مثل تقرب العبد إلى غيره، وليس مشيه كمشيهم، ولا هرولته كهرولتهم وهكذا غضبه وهكذا رضاه، وهكذا مجيئه يوم القيامة وإتيانه يوم القيامة لفصل القضاء بين عباده، وهكذا استواؤه على العرش، وهكذا نزوله في آخر الليل كل ليلة كلها صفات تليق بالله جل وعلا، لا يشابه فيها خلقه، فكما أن استواءه على العرش ونزوله في آخر الليل في الثلث الأخير من الليل ومجيئه يوم القيامة لا يشابه استواء خلقه ولا مجيء خلقه ولا نزول خلقه، فهكذا تقربه إلى عباده العابدين له والمسارعين إلى طاعته تقربه إليهم لا يشابه تقربهم وليس قربه منهم كقربهم منه، وليس مشيه لهم كمشيهم، ولا هرولته كهرولتهم، بل هو شيء يليق بالله لا يشابهه في خلقه سبحانه وتعالى كسائر الصفات، فهو أعلم بصفاته وأعلم بكيفيتها .\nوقد أجمع سلف الأمة على أن الواجب في صفات الرب وأسمائه إمرارها كما جاءت، واعتقاد معناها وأنه حق يليق بالله ، وأنه لا يعلم كيفية صفاته إلا هو، كما أنه لا يعلم كيف ذاته إلا هو .\nفالصفات كالذات، فكما أن الذات يجب إثابتها لله وأنه  هو الكامل في ذلك فهكذا صفاته يجب إثباتها له سبحانه مع الإيمان والاعتقاد بأنها أكمل الصفات وأعلاها، وأنها لا تشابه صفات الخلق كما قال : قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:1-4]، وقال : فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74] وقال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] فرد على المشبهة بقوله: لَيْسَ كَمِثْلِهِ شَيْءٌ [الشورى:11] فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74]، ورد على المعطلة بقوله: وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] ، قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ [الإخلاص:1-2]، إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [البقرة:220] إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ [الحج:75] إِنَّ اللَّهَ غَفُورٌ رَحِيمٌ [البقرة:173] إِنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ [البقرة:20] إلى غير ذلك.\nفالواجب على المسلمين علماء وعامة الواجب عليهم جميعًا إثبات ما أثبته الله لنفسه إثباتًا بلا تمثيل، ونفي ما نفاه الله عن نفسه، وتنزيه الله عما نزه عنه نفسه تنزيهًا بلا تعطيل، هكذا يقول أهل السنة والجماعة من أصحاب النبي ﷺ وأتباعهم من سلف الأمة كالفقهاء السبعة وكـمالك بن أنس والأوزاعي والثوري والشافعي وأحمد وأبي حنيفة وغيرهم من أئمة الإسلام أمروها كما جاءت وأثبتوها كما جاءت من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل.\nوأما ما قاله المعلقان في هذا علوي وصاحبه محمود فهو كلام ليس بجيد وليس بصحيح، ولكن مقتضى هذا الحديث أنه سبحانه أسرع بالخير إليهم وأولى بالجود والكرم ولكن ليس هذا هو المعنى، المعنى شيء وهذه الثمرة وهذا المقتضى شيء آخر فهو يدل على أنه أسرع بالخير إلى عباده منهم ولكنه ليس هذا هو المعنى بل المعنى يجب إثباته لله من التقرب والمشي والهرولة شيء يجب إثباته لله على الوجه اللائق به سبحانه وتعالى من غير أن يشابه خلقه في شيء من ذلك، فنثبته لله على الوجه الذي أراده الله من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل. نعم.\nالمقدم: يعني قولهما يا سماحة الشيخ: إن هذا من تصوير المعقول بالمحسوس.\nالشيخ: هذا غلط، هكذا يقولون في أشياء كثيرة يقوله المؤولون والأصل عدم التأويل الواجب عدم التأويل وعدم التكييف وعدم التمثيل والتحريف بل تمر آيات الصفات وأحاديثها كما جاءت ولا يتعرض لها بتأويل ولا بتحريف ولا بتعطيل بل نثبتها لله كما أثبتها لنفسه وكما خاطبنا بها إثباتًا يليق بالله لا يشابه في خلقه سبحانه وتعالى. نعم.\nكما نقول في الغضب واليد والوجه والأصابع والكراهة والنزول والاستواء الباب واحد باب الصفات باب واحد، وهكذا المجيء يوم القيامة اللي يقول:... ما يجي يوم القيامة ولا ينزل يكذب، فالمجيء هو المشي. نعم.\nالمقدم: جزاكم الله خير وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8107/طريقة-السلف-في-اثبات-صفات-الله-عز-وجل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_200/20001.mp3","categories":["الأسماء والصفات"]},{"id":10858,"question":"يوجد في يدي الإنسان خطوط في اليد اليمنى رقم (18) وفي اليسرى (81) يصبح المجموع (99)، يقابل هذه أسماء الله الحسنى، هل هذا صحيح؟","title":"هل الخطوط التي في يد الإنسان تقابل عدد أسماء الله الحسنى؟","answer":"الجواب:  لا أعلم لهذا أصلًا، أقول: لا أعلم لهذا أصلًا بالكلية، بل هذا من الخرافات التي لا نعلم لها أصلًا.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9035/هل-الخطوط-التي-في-يد-الانسان-تقابل-عدد-اسماء-الله-الحسنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_357/35703.mp3","categories":["الأسماء والصفات"]},{"id":11477,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، حماة، باعث الرسالة المستمع أنور الحسين أخونا يقول: أرجو أن تتفضلوا بتفسير قول الله تعالى: الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ الرَّحْمَنُ فَاسْأَلْ بِهِ خَبِيرًا [الفرقان:59]، جزاكم الله خيرًا.","title":"ما معنى: {ثُمَّ اسْتَوَى عَلَى الْعَرْشِ}؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. هذه الآية من آيات الصفات، فالله -جل وعلا- بين فيها، وفي غيرها أنه خالق السماوات والأرض، وما بينهما، فهو الخلاق العليم لكل شيء، لا خالق سواه، ولا رب سواه  قال تعالى: اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ عَلَى كُلِّ شَيْءٍ وَكِيلٌ [الزمر:62]، وقال سبحانه: وَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا [الفرقان:2]، وقوله: ثُمَّ اسْتَوَى عَلَى الْعَرْشِ الرَّحْمَنُ [الفرقان:59]، هذا وصف لنفسه بأنه استوى على العرش، وهذا في سبعة مواضع من القرآن، قال -جل وعلا- في سورة طه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]، وفي سورة الأعراف: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54]. فهذه الآية العظيمة وما جاء في معناها في المواضع السبعة كلها دالة على إثبات الاستواء، وأن الله -جل وعلا- استوى على العرش استواءً يليق بجلاله، وعظمته، لا يشابه خلقه في شيء من صفاته، بل هو سبحانه له صفات خاصة تليق به على أكمل وجه، وخير وجه، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، قال سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، قال : هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65]، قال سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74]. فالاستواء هو العلو والارتفاع، يعني: ارتفع فوق العرش، وعلا فوق العرش ارتفاعًا يليق بجلاله، لا يشابه خلقه في استوائهم على سطوحهم، أو على سفنهم، أو على سياراتهم، لا، استواء يليق به، وارتفاع يليق به، لا يشابه خلقه في شيء من صفاته، لكنه العلو، ولهذا يقال: استوى على السفينة، يعني: صار فوقها، استوى على السطح؛ صار فوقها، استوى على الدابة؛ صار فوقها، فالاستواء على الشيء العلو فوقه، والارتفاع فوقه، لكن استواء الرب يليق به، لا يشابه المخلوقات في استوائها. وهكذا بقية الصفات، الرحمة رحمة تليق بالله، فهو الرَّحْمَنِ الرَّحِيمِ [الفاتحة:3]، رحمته خاصة وعامة تعم المخلوقات كلهم، ورحمته خاصة بالمؤمنين تخصهم، وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا [الأحزاب:43]، إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ [التوبة:117]. فالمقصود: أن الرحمة وصف خاص غير الإرادة، بعض أهل العلم يأول يقول: الرحمن معناه: إرادة الإنعام، والرحمة إرادة الإنعام، هذا غلط، هذا تأويل، والصواب عند أهل السنة أن الرحمة غير الإرادة، الإرادة صفة مستقلة، له سبحانه إرادتان: قدرية، وشرعية.  فالقدرية مثل قوله -جل وعلا-: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]  ومثل قوله -جل وعلا-: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهدِيَهُ يَشْرَحْ صَدْرَهُ لِلإِسْلامِ [الأنعام:125]. وهناك شرعية مثل قوله -جل وعلا-: يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ الَّذِينَ مِنْ قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ [النساء:26] إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا [الأحزاب:33] هذه إرادة شرعية، يعني: أراد الله شرعًا أن يطهر أهل بيت النبي ﷺ وأراد شرعًا أن يبين للناس أحكام دينهم، ويفهمهم إياه، لكن من الناس من يفهم ويتعلم، ومن الناس من يعرض، ليس كلهم مهتدين. أما الإرادة القدرية فهي نافذة، لا يمنعها شيء، كما قال : إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]، هذه إرادة قدرية نافذة، وهكذا قوله جل وعلا: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهدِيَهُ يَشْرَحْ صَدْرَهُ لِلإِسْلامِ [الأنعام:125]، هذه إرادة كونية، إذا أراد الله هداية العبد إرادة كونية؛ شرح صدره للإسلام ومن عليه بالقبول حتى يهتدي. وهكذا الغضب صفة خاصة تليق بالله، بعض العلماء يقول: إرادة الانتقام، وهذا غلط، الإرادة غير الانتقام، الإرادة شيء، والغضب شيء آخر، والغضب يوصف الله به كما قال -جل وعلا-: وَغَضِبَ اللَّهُ عَلَيْهِ [النساء:93] يعني: قاتل النفس. فالمقصود: أن الغضب وصف لله، يغضب على أعدائه غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ [الفاتحة:7]، من اليهود والنصارى والكفرة مغضوب عليهم، غضب الله وصف يليق بالله، لا يشابه الخلق فيه، كالرضا وكالرحمة وكإلارادة وغير ذلك صفة مستقلة، فهو رحيم بالمؤمنين، رحيم بالناس، ويغضب على من عصاه، وخالف أمره، وغضبه يليق به، لا يشابه غضب المخلوقين، كما أن رضاه لا يشابه رضا المخلوقين، وهكذا استواءه، وهكذا محبته، وهكذا رحمته، كلها صفات حق، لا تشابه صفات المخلوقين عند أهل السنة والجماعة؛ لأن الله سبحانه يقول: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، هو سبحانه الرحمن، وهو الرحيم موصوفًا بالرحمة، صفة تليق بالله، لا يشابه فيها خلقه -جل وعلا- يغضب على من عصاه غضبًا يليق بالله، لا يشابه خلقه في غضبهم.  وهكذا إرادته، وهكذا يده، وهكذا سمعه، وبصره، كلها صفات تليق بالله، لا يشابه خلقه في شيء من صفاته -جل وعلا- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم. من الأسئلة التي يسألها أخونا حول هذه الآية الكريمة سؤال يقول: هل الأيام المذكورة في هذه الآية الكريمة هي كأيامنا، أم أن اليوم بألف سنة كما في بعض الآيات الكريمة؟ الشيخ: الله أعلم، لكن ظاهر إطلاق الرب -جل وعلا- أنها كأيامنا، يعني: أطلق بالنسبة للستة الأيام، ويحتمل أنها كل يوم بألف كما قال -جل وعلا-: وَإِنَّ يَوْمًا عِنْدَ رَبِّكَ كَأَلْفِ سَنَةٍ مِمَّا تَعُدُّونَ [الحج:47]، لكن إطلاقه الآيات في هذا يدل على أنها كأيامنا، وهو سبحانه قادر أن يخلق كل شيء في لحظة، كن فيكون، لكنه -جل وعلا- خلقها في أيام؛ ليعلم عباده تنظيم أمورهم، وتنظيم أعمالهم حتى لا يعجلوا، فهو  قادر على أن يخلقها في لحظة، ومع هذا خلقها في ستة أيام، وهو قادر على أن يخلقها في أقل من ذلك -جل وعلا- لتعليم عباده وتوجيههم إلى العناية بالأمور، وعدم العجلة في الأمور؛ حتى يوقعوا الأشياء، ويوجدوها على الوجه الذي يليق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9655/ما-معنى-ثم-استوى-على-العرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38201.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":11480,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، حماة، باعث الرسالة المستمع أنور الحسين أخونا يقول: أرجو أن تتفضلوا بتفسير قول الله تعالى: الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ وَمَا بَيْنَهُمَا فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ الرَّحْمَنُ فَاسْأَلْ بِهِ خَبِيرًا [الفرقان:59]، جزاكم الله خيرًا.","title":"ما معنى: {ثُمَّ اسْتَوَى عَلَى الْعَرْشِ}؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه. هذه الآية من آيات الصفات، فالله -جل وعلا- بين فيها، وفي غيرها أنه خالق السماوات والأرض، وما بينهما، فهو الخلاق العليم لكل شيء، لا خالق سواه، ولا رب سواه  قال تعالى: اللَّهُ خَالِقُ كُلِّ شَيْءٍ وَهُوَ عَلَى كُلِّ شَيْءٍ وَكِيلٌ [الزمر:62]، وقال سبحانه: وَخَلَقَ كُلَّ شَيْءٍ فَقَدَّرَهُ تَقْدِيرًا [الفرقان:2]، وقوله: ثُمَّ اسْتَوَى عَلَى الْعَرْشِ الرَّحْمَنُ [الفرقان:59]، هذا وصف لنفسه بأنه استوى على العرش، وهذا في سبعة مواضع من القرآن، قال -جل وعلا- في سورة طه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]، وفي سورة الأعراف: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54]. فهذه الآية العظيمة وما جاء في معناها في المواضع السبعة كلها دالة على إثبات الاستواء، وأن الله -جل وعلا- استوى على العرش استواءً يليق بجلاله، وعظمته، لا يشابه خلقه في شيء من صفاته، بل هو سبحانه له صفات خاصة تليق به على أكمل وجه، وخير وجه، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، قال سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4]، قال : هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65]، قال سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ إِنَّ اللَّهَ يَعْلَمُ وَأَنْتُمْ لا تَعْلَمُونَ [النحل:74]. فالاستواء هو العلو والارتفاع، يعني: ارتفع فوق العرش، وعلا فوق العرش ارتفاعًا يليق بجلاله، لا يشابه خلقه في استوائهم على سطوحهم، أو على سفنهم، أو على سياراتهم، لا، استواء يليق به، وارتفاع يليق به، لا يشابه خلقه في شيء من صفاته، لكنه العلو، ولهذا يقال: استوى على السفينة، يعني: صار فوقها، استوى على السطح؛ صار فوقها، استوى على الدابة؛ صار فوقها، فالاستواء على الشيء العلو فوقه، والارتفاع فوقه، لكن استواء الرب يليق به، لا يشابه المخلوقات في استوائها. وهكذا بقية الصفات، الرحمة رحمة تليق بالله، فهو الرَّحْمَنِ الرَّحِيمِ [الفاتحة:3]، رحمته خاصة وعامة تعم المخلوقات كلهم، ورحمته خاصة بالمؤمنين تخصهم، وَكَانَ بِالْمُؤْمِنِينَ رَحِيمًا [الأحزاب:43]، إِنَّهُ بِهِمْ رَءُوفٌ رَحِيمٌ [التوبة:117]. فالمقصود: أن الرحمة وصف خاص غير الإرادة، بعض أهل العلم يأول يقول: الرحمن معناه: إرادة الإنعام، والرحمة إرادة الإنعام، هذا غلط، هذا تأويل، والصواب عند أهل السنة أن الرحمة غير الإرادة، الإرادة صفة مستقلة، له سبحانه إرادتان: قدرية، وشرعية.  فالقدرية مثل قوله -جل وعلا-: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]  ومثل قوله -جل وعلا-: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهدِيَهُ يَشْرَحْ صَدْرَهُ لِلإِسْلامِ [الأنعام:125]. وهناك شرعية مثل قوله -جل وعلا-: يُرِيدُ اللَّهُ لِيُبَيِّنَ لَكُمْ وَيَهْدِيَكُمْ سُنَنَ الَّذِينَ مِنْ قَبْلِكُمْ وَيَتُوبَ عَلَيْكُمْ [النساء:26] إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا [الأحزاب:33] هذه إرادة شرعية، يعني: أراد الله شرعًا أن يطهر أهل بيت النبي ﷺ وأراد شرعًا أن يبين للناس أحكام دينهم، ويفهمهم إياه، لكن من الناس من يفهم ويتعلم، ومن الناس من يعرض، ليس كلهم مهتدين. أما الإرادة القدرية فهي نافذة، لا يمنعها شيء، كما قال : إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]، هذه إرادة قدرية نافذة، وهكذا قوله جل وعلا: فَمَنْ يُرِدِ اللَّهُ أَنْ يَهدِيَهُ يَشْرَحْ صَدْرَهُ لِلإِسْلامِ [الأنعام:125]، هذه إرادة كونية، إذا أراد الله هداية العبد إرادة كونية؛ شرح صدره للإسلام ومن عليه بالقبول حتى يهتدي. وهكذا الغضب صفة خاصة تليق بالله، بعض العلماء يقول: إرادة الانتقام، وهذا غلط، الإرادة غير الانتقام، الإرادة شيء، والغضب شيء آخر، والغضب يوصف الله به كما قال -جل وعلا-: وَغَضِبَ اللَّهُ عَلَيْهِ [النساء:93] يعني: قاتل النفس. فالمقصود: أن الغضب وصف لله، يغضب على أعدائه غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلا الضَّالِّينَ [الفاتحة:7]، من اليهود والنصارى والكفرة مغضوب عليهم، غضب الله وصف يليق بالله، لا يشابه الخلق فيه، كالرضا وكالرحمة وكإلارادة وغير ذلك صفة مستقلة، فهو رحيم بالمؤمنين، رحيم بالناس، ويغضب على من عصاه، وخالف أمره، وغضبه يليق به، لا يشابه غضب المخلوقين، كما أن رضاه لا يشابه رضا المخلوقين، وهكذا استواءه، وهكذا محبته، وهكذا رحمته، كلها صفات حق، لا تشابه صفات المخلوقين عند أهل السنة والجماعة؛ لأن الله سبحانه يقول: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، هو سبحانه الرحمن، وهو الرحيم موصوفًا بالرحمة، صفة تليق بالله، لا يشابه فيها خلقه -جل وعلا- يغضب على من عصاه غضبًا يليق بالله، لا يشابه خلقه في غضبهم.  وهكذا إرادته، وهكذا يده، وهكذا سمعه، وبصره، كلها صفات تليق بالله، لا يشابه خلقه في شيء من صفاته -جل وعلا- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم. من الأسئلة التي يسألها أخونا حول هذه الآية الكريمة سؤال يقول: هل الأيام المذكورة في هذه الآية الكريمة هي كأيامنا، أم أن اليوم بألف سنة كما في بعض الآيات الكريمة؟ الشيخ: الله أعلم، لكن ظاهر إطلاق الرب -جل وعلا- أنها كأيامنا، يعني: أطلق بالنسبة للستة الأيام، ويحتمل أنها كل يوم بألف كما قال -جل وعلا-: وَإِنَّ يَوْمًا عِنْدَ رَبِّكَ كَأَلْفِ سَنَةٍ مِمَّا تَعُدُّونَ [الحج:47]، لكن إطلاقه الآيات في هذا يدل على أنها كأيامنا، وهو سبحانه قادر أن يخلق كل شيء في لحظة، كن فيكون، لكنه -جل وعلا- خلقها في أيام؛ ليعلم عباده تنظيم أمورهم، وتنظيم أعمالهم حتى لا يعجلوا، فهو  قادر على أن يخلقها في لحظة، ومع هذا خلقها في ستة أيام، وهو قادر على أن يخلقها في أقل من ذلك -جل وعلا- لتعليم عباده وتوجيههم إلى العناية بالأمور، وعدم العجلة في الأمور؛ حتى يوقعوا الأشياء، ويوجدوها على الوجه الذي يليق، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9655/ما-معنى-ثم-استوى-على-العرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_382/38201.mp3","categories":["التفسير","الأسماء والصفات"]},{"id":11728,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من الطائف رمزت إلى اسمها بالحرف (ن)، أختنا تسأل عن قوله : وَاللَّهُ غَالِبٌ عَلَى أَمْرِهِ [يوسف:21]، هل كلمة غالب صفة من صفات الله، وما معنى هذه الآية؟ جزاكم الله خيرًا.","title":"\"الغالب\" من صفات الله جل وعلا","answer":"الجواب:  معناها أنه سبحانه غالب على أمره، ولا يغلبه الناس، بل ما شاءه؛ كان، ونفذ، وإن لم يرض الناس، كما قال الله -جل وعلا- في كتابه العظيم: إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْ فَيَكُونُ [يس:82]، وَلَوْ شَاءَ رَبُّكَ مَا فَعَلُوهُ [الأنعام:112]، لِمَنْ شَاءَ مِنْكُمْ أَنْْ يَسْتَقِيمَ ۝ وَمَا تَشَاءُونَ إِلَّا أَنْ يَشَاءَ اللَّهُ رَبُّ الْعَالَمِينَ [التكوير:28-29] فمشيئته نافذة  فإذا قال: ما شاء الله، لا قوة إلا بالله؛ فهذا كلام طيب والله سبحانه هو الغالب على أمره، يعني مشيئته نافذة، إِنَّمَا أَمْرُهُ إِذَا أَرَادَ شَيْئًا أَنْ يَقُولَ لَهُ كُنْْ فَيَكُونُ[يس:82]، فليس لأحد أن يغلبه، لا يغلبه أحد، بل ما شاءه نفذ وإن لم يرض الناس، وإن لم يرد الناس، سواء كان ذلك الشيء إماتة إنسان، أو نصر قوم، أو هزيمتهم، أو غير ذلك من الشؤون، أمره هو الغالب  أمره -جل وعلا- هو الغالب لأمر الناس، لا يغلبه شيء -جل وعلا- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9911/الغالب-من-صفات-الله-جل-وعلا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42109.mp3","categories":["الأسماء والصفات"]},{"id":11923,"question":"إحدى الأخوات المستمعات تقول: المرسلة (س. ف) تسأل عن معنى الصمد؟","title":"معنى الصمد","answer":"الجواب:  الصمد: فسر بمعنيين عند العلماء: أحدهما: أنه الذي لا جوف له، ليس من جنس المخلوقين، المخلوق له جوف يأكل ويشرب ويطعم، والله لا جوف له مصمت، كما قال تعالى: (الصمد) وكله فسر بالصمد. وفسر الصمد بمعنى آخر: وهو أنه تصمد إليه الخلائق في حاجاتها، وترجوه، وتسأله، وتضرع إليه في حاجاتها سبحانه، وكله حق، هو الصمد لا جوف له، وهو الصمد ترفع إليه الحاجات -جل وعلا-: قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ [الإخلاص: 1-2] إذا أردت تقول للرؤساء المقصودين: صمد؛ لأنه يقصد في طلب الحاجات، والله سبحانه هو الذي يقصد من جميع الخلائق ... طلب الحاجة وهو سبحانه ..... لا يطعم، ولا يحتاج إلى طعام، ولا إلى شراب، وليس من جنس المخلوقين، .... أو يحتاج إلى غداء، بل هو الغني عن كل ما سواه، وهو يطعم ولا يطعم  نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10107/معنى-الصمد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42624.mp3","categories":["الأسماء والصفات"]},{"id":11967,"question":"رسالة بتوقيع أحد الإخوة المستمعين يقول: طالب علم من جدة، أخونا له عدة قضايا من بينها هذه القضية، يقول: من المعلوم عند أهل السنة أن القرآن كلام الله، منزل غير مخلوق، منه بدأ وإليه يعود، ولكن هذه الحروف التي كتب بها القرآن هل هي غير مخلوقة، أم أنها حروف عربية؟ أي: هل كان القرآن مكتوب في اللوح المحفوظ بهذه الحروف، أم أن هذه الحروف وجدت مع العرب، أرجو بيان مذهب السلف فيما سبق، والرد على الإشكالات إن كان هناك إشكالات، وجزاكم الله خيرًا.","title":"هل حروف القرآن غير مخلوقة، أم أنها حروف عربية؟","answer":"الجواب:  هذا الكلام الذي سأل عنه السائل قد أجاب عنه أهل السنة والجماعة، وأجمعوا على أن القرآن كلام الله، منزل غير مخلوق، منه بدأ وإليه يعود، حروفه ومعانيه، فالقرآن هو كلام الله، حروف ومعاني، تكلم الله به -جل وعلا- وتبعه جبرائيل، وبلغه محمدًا -عليه الصلاة والسلام- فالقرآن كله حروفه ومعانيه هو كلام الله، ومن قال: إنه مخلوق؛ فقد كفر عند أهل السنة والجماعة، هو كلام الله حروفًا ومعاني، وهو موجود في اللوح المحفوظ بحروفه ومعانيه، كما قال سبحانه: بَلْ هُوَ قُرْآنٌ مَجِيدٌ ۝ فِي لَوْحٍ مَحْفُوظٍ [البروج:21-22]. فالقرآن كله كلام الله، منزل غير مخلوق، منه بدأ وإليه يعود بحروفه ومعانيه جميعًا، كما نص على ذلك أهل السنة والجماعة، وكما نص على ذلك أيضًا أبو العباس شيخ الإسلام ابن تيمية -رحمه الله- في كتبه، ومنها: العقيدة الواسطية، فقد ذكر فيها عقيدة أهل السنة والجماعة، فالقرآن كلام الله، حروف ومعاني جميعًا، ولا يكون كلام إلا بحروف ومعاني، الكلام حروف ومعاني من حيث هو، فكلام الله حروف ومعاني، نزل به جبرائيل على النبي الكريم محمد -عليه الصلاة والسلام- وأثبته الله في اللوح المحفوظ كما بين في كتابه العظيم  ومن قال خلاف ذلك؛ فقد قال الشر، وابتدع في الدين، وخالف أهل السنة والجماعة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10152/هل-حروف-القران-غير-مخلوقة-ام-انها-حروف-عربية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42908.mp3","categories":["الأسماء والصفات"]},{"id":11968,"question":"عن أبي هريرة  عن النبي ﷺ قال: خلق الله آدم على صورته، طوله ستون ذراعًا الحديث متفق عليه، أرجو من سماحتكم شرح هذا الحديث شرحًا وافيًا، وبيان ما يقع فيه من سوء تأويل، وما يقع فيه من إشكالات، والإجابة عن هذه الإشكالات جزاكم الله خيرًا.","title":"معنى حديث: (خلق الله آدم على صورته)","answer":"الجواب:  هذا الحديث قد أشكل على بعض الناس، وتأوله على أن المراد على صورة آدم، خلق الله آدم على صورة آدم، وهذا غلط، وليس من فصيح الكلام، بل المراد خلقه الله على صورته هو  ولهذا في الحديث الآخر: خلق الله آدم على صورة الرحمن وهي رواية جيدة، أثبتها الإمام أحمد وغيره، الإمام أحمد وإسحاق بن راهويه وآخرون، تفسر هذه رواية شبهة الضمير: (على صورته) أي: صورة الرحمن، والمعنى: أنه  خلق آدم سميعًا بصيرًا يتكلم، وله وجه، وله يد، وله قدم، وهكذا ربنا سبحانه: سميع بصير يتكلم وله وجه وله يدان وله قدم سبحانه كما أخبر عن نفسه: بَلْ يَدَاهُ مَبْسُوطَتَانِ [المائدة:64].  وقال -جل وعلا-: مَا مَنَعَكَ أَنْْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ [ص:75] وقال النبي ﷺ: إن جهنم لا تزال تقول: هل من مزيد؟ حتى يضع الله بها رجله وفي رواية: قدمه فينزوي بعضها إلى بعض وتقول: قط قط وليس المراد أنه شبيه له، وأنه مثله لا، بل المراد أنه على صورته من حيث أنه سميع بصير متكلم، ذو وجه، ذو قدم، ذو يد، لكن ليس السميع كالسميع، وليس البصير كالبصير، وليست اليد كاليد، ولا القدم كالقدم، ولا الكلام كالكلام، قال الله سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقال سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌٌ [الإخلاص:4] وقال : فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74] هذا قول أهل السنة والجماعة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10153/معنى-حديث-خلق-الله-ادم-على-صورته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_429/42909.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":12376,"question":"ماذا يجب على المؤمن أن يعتقده في صفات الله  حتى يكون سليم الاعتقاد كما كان عليه سلفنا الصالح؟","title":"عقيدة المؤمن في أسماء الله وصفاته","answer":"الجواب:  الواجب على المؤمن أن يعتقد أن الله  موصوف بصفات الكمال، وأن أسماءه كلها حسنى كما قال : وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى [الأعراف:180] وهكذا يعتقد أنها كاملة، وأنه لا شبيه له ولا مثيل له، ولا نقص فيها بوجه من الوجوه، لقوله سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] ، هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65]، فَلا تَجْعَلُوا لِلَّهِ أَندَادًا [البقرة:22]. هذا هو الواجب على كل مؤمن ومؤمنة أن يعتقد أن الله -جل وعلا- له الأسماء الحسنى الكاملة، وله الصفات الكاملة، التي ليس فيها نقص، ولا عيب ولا خلل، الرضا والغضب والرحمة والإحسان والجود والكرم والعزة، وكونه مستحق العبادة، كونه الحكيم، وكونه العليم إلى غير هذا، هذه صفات كاملة، يوصف بها على أنها كاملة من كل الوجوه، ويسمى بها أنه عليم، حكيم قدير على ما سمى به نفسه  فهو سبحانه له الأسماء الحسنى، كما سمى نفسه، وله معانيها العظيمة كل معانيها كاملة، ليس له فيها نظير، ولا شبيه، ولا مثيل، بل له الأسماء الحسنى، وله المثل الأعلى في جميع الصفات . نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10571/عقيدة-المومن-في-اسماء-الله-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_400/40009.mp3","categories":["الأسماء والصفات"]},{"id":12662,"question":"من تشاد رسالة بعث بها المستمع صالح سليمان يوسف وعيسى أبو بكر موسى، يسأل عن تفسير قول الحق -تبارك وتعالى-: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] بعض الناس يقولون: إن الله  موجود في أي مكان بذاته، وإذا كان الكلام كذلك فما هو دليل الآية القرآنية؟","title":"معنى قوله: (الرحمن على العرش استوى) عند أهل السنة","answer":"الجواب:  الآية الكريمة معناها واضح عند أهل السنة والجماعة، قد أخبر الله سبحانه في سبعة مواضع من القرآن أنه استوى على العرش، منها: هذه الآية، ومنها: قوله سبحانه في سورة الأعراف وفي سورة يونس: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [يونس:3] ومعنى استوى: ارتفع وعلا، وهو استواء يليق بجلال الله، لا يشابه خلقه في استوائهم، لا يشابه خلقه في استوائهم على الدابة، أو على السفينة، أو السيارة، أو الطائرة، لا، استواء يليق به، لا يماثل خلقه  كما قال -جل وعلا-: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، وقال سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] وقال : فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74] والله -جل وعلا- فوق العرش. ومن قال: إنه في كل مكان، فقد غلط، وضل عن سواء السبيل، وهو كافر عند جمع من أهل العلم من أهل السنة والجماعة؛ لأن الله فوق العرش، وعلمه في كل مكان . فالقول بأنه في كل مكان من قول أهل البدع والضلال والإلحاد. أما أهل السنة والجماعة فيقولون: إنه فوق العرش، قد استوى عليه استواء يليق بجلاله وعظمته، وعلمه في كل مكان سبحانه لا يخفى عليه خافية  والعرش هو سقف المخلوقات، وأعلاها، والله فوقه  يعلم أحوال عباده، لا تخفى عليه خافية، جل وعلا. فالواجب على كل مسلم أن يعتقد ذلك، وأن يؤمن بذلك على الوجه اللائق بالله  من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل كما قال ربنا -عز وجل-: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]  هذا قول أهل السنة والجماعة من أصحاب النبي ﷺ وأتباعهم بإحسان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10872/معنى-قوله-الرحمن-على-العرش-استوى-عند-اهل-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45814.mp3","categories":["الأسماء والصفات"]},{"id":13571,"question":"هذا سائل يقول في هذا  سماحة الشيخ! بينوا لنا كيف كانت عقيدة أصحاب رسول الله ﷺ في صفات الله  وفي توحيد الله، وفي القرآن، وفي البعث والجزاء، جزاكم الله خيرًا.","title":"عقيدة السلف في صفات الله والبعث والجزاء","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابهـ ومن اهتدى بهداه، أما بعد.  فهذا سؤال عظيم، جدير بالعناية، عقيدة أصحاب النبي ﷺ في أسماء الله، وصفاته، وفي البعث، والنشور، وفي غير ذلك، هي ما دل عليه القرآن العظيم، والسنة المطهرة الصحيحة عن رسول الله -عليه الصلاة والسلام- فهم  تلقوا عن نبيهم العقيدة التي دل عليها القرآن العظيم، وهي: الإيمان بالله، وأنه ربهم، ومعبودهم الحق  الذي لا تجوز العبادة إلا له  فهو الذي يصلى له، ويدعى، ويستغاث به، وينذر له، ويصلى له، ويسجد، ويذبح له.. إلى غير ذلك، العبادة حقه . فعقيدتهم أن العبادة حق الله وحده، وأنه لا يصرف منها شيء لغير الله، لا لملك مقرب، ولا لنبي مرسل، وقد كانوا في الجاهلية يعبدون الأصنام، ويدعونها، ويستغيثون بها، والأشجار، والأحجار، فلما بعث الله نبيه محمد ﷺ وهداهم الله للإسلام؛ عرفوا أن ما هم عليه هو الباطل، وأنه الشرك الأكبر، وأن العبادات كلها يجب أن تكون لله وحده. وعقيدتهم في أسماء الله وصفاته، الإيمان بها، وإمرارها كما جاءت، وعدم التكييف والتمثيل، فهم يؤمنون بأن الله هو السميع البصير الحكيم العليم الرحمن الرحيم، وأنه على العرش استوى فوق جميع الخلق، وأنه العلي العظيم  وأنه الحي القيوم، وأنه مصرف لعباده كيف يشاء، مدبر الأمور، وخالق الخلق، ورازق العباد، لا شبيه له، ولا مثل له، ولا كفء له قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:1-4]، ويقول سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]. فهذه عقيدة أصحاب النبي ﷺ في أسماء الله وصفاته، يؤمنون بأنه سبحانه فوق العرش، فوق جميع الخلق، وأنه العلي العظيم، وأن الأعمال ترفع إليه -الأعمال الصالحة- كما قال -جل وعلا-: إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ وَالْعَمَلُ الصَّالِحُ يَرْفَعُهُ [فاطر:10] وقال -جل وعلا-: تَعْرُجُ الْمَلائِكَةُ وَالرُّوحُ إِلَيْهِ [المعارج:4] والعروج: الصعود من أسفل إلى أعلى، وقال -جل وعلا-: فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12]، قال: وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] وقال في حق عيسى: إِنِّي مُتَوَفِّيكَ وَرَافِعُكَ إِلَيَّ [آل عمران:55] وقال: بَلْ رَفَعَهُ اللَّهُ إِلَيْهِ [النساء:158]. فهو فوق العرش، فوق جميع الخلق، فهو العلي الأعلى، هو فوق العرش، كما قال تعالى: رَفِيعُ الدَّرَجَاتِ ذُو الْعَرْشِ [غافر:15] فهو فوق العرش، فوق جميع الخلق، قد استوى عليه، والاستواء: هو العلو والارتفاع فوق العرش، استواءً يليق بجلال الله، لا يشابه خلقه في استوائهم، ولا في كلامهم، ولا في غير ذلك، فهو  العلي الأعلى فوق العرش بلا كيف، أهل السنة والجماعة، وهم أصحاب النبي ﷺ وأتباعهم لا يكيفون، لا يقولون: استوى كيف استوى؟ بل يقولون: استوى على العرش بلا كيف، يعني: على الكيف الذي يعلمه سبحانه، لا نعلم كيفية صفاته -جل وعلا- بل نقول: استوى بلا كيف، وهو الرحمن الرحيم، وهو العزيز الحكيم، وهو السميع البصير بلا كيف، لكن نعلم يقينًا أن صفاته كاملة، وأنه لا شبيه له، ولا مثل له، قال تعالى: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]. فلا يجوز لأحد أن يكيفها، ولا أن يمثلها، فالمشبهة كفار، من شبه الله بخلقه، فقد كفر وكذب قوله تعالى: لَيْسَ كَمِثْلِهِ شَيْءٌ [الشورى:11] ومن عطل صفاته، وأنكرها كـالجهمية كفر، أو عطل معانيها كـالمعتزلة كفر، فالواجب إثبات أسمائه وصفاته لفظها ومعناها، يجب إثبات الأسماء والصفات لفظًا ومعنى لله  فهو موصوف بها وهو  له معناها، فهو العلي، وله العلو، رحمان له الرحمة، سميع يسمع، بصير يبصر.. إلى غير ذلك، كلها حق على الوجه اللائق بالله، لا شبيه له في ذلك، ولا كفء له، ولا ند له . وكلام الله منزل غير مخلوق، تكلم بالقرآن، وكلامه منزل غير مخلوق، وهكذا كلم موسى، كلم محمد ﷺ يكلم الملائكة، كلامه حق يسمع، ليس كمثله شيء، كلامه تقول فيه كسائر الصفات، كلام صحيح حقيقي، لا يشبه كلام المخلوقين، صفة من صفاته، كالسمع والبصر والرضا والغضب والرحمة، وغير ذلك من صفاته، جل وعلا. فالواجب على جميع المكلفين الإيمان بأسمائه، وصفاته، والإيمان بكل ما أخبر الله به ورسوله، من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، ومن دون زيادة، أو نقص، بل يجب إثبات ما أثبته الله ورسوله، ونفي ما نفاه الله ورسوله، هذا هو عقيدة أهل السنة والجماعة، وعقيدة الصحابة  وأرضاهم. وأما الذين غيروا وبدلوا فليسوا من الصواب في شيء، وليسوا من أهل السنة في شيء كـالجهمية، والمعتزلة، والرافضة.. وغيرهم، أهل السنة والجماعة يؤمنون بأن الله سبحانه واحد لا شريك له، ويعتقدون معنى قول: لا إله إلا الله، وأن معناها: لا معبود حق إلا الله، فهم يؤمنون بأنه سبحانه المعبود الحق، وأنه لا إله غيره، لا شريك له، ويؤمنون بأنه سبحانه ذو الأسماء الحسنى، والصفات العلى، وأن أسماءه كلها حسنى، وأن صفاته كلها علا، لا يشبه شيئًا من خلقه  في شيء من صفاته. والواجب على جميع المكلفين الإيمان بذلك، والسير على منهج الصحابة -رضي الله عنه وأرضاهم- وهو توحيد الله، والإخلاص له، والإيمان بأنه يستحق العبادة، والإيمان بأسمائه وصفاته، وأنها حق، وأنه سبحانه لا شبيه له، ولا مثل له، ولا كفء له، ولا يقاس بخلقه  لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]  وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74] هذا هو دين الله، هذا هو الحق الذي جاءت به الرسل -عليهم الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11909/عقيدة-السلف-في-صفات-الله-والبعث-والجزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52301.mp3","categories":["الأسماء والصفات"]},{"id":13982,"question":"هذا طالب من ليبيا رمز لاسمه بـ (أ. أ. أ) يقول: سماحة الشيخ! ما هو مذهب أهل السنة والجماعة في الأسماء والصفات؟","title":"مذهب أهل السنة في أسماء الله وصفاته","answer":"الجواب: مذهب أهل السنة والجماعة: إثبات أسماء الله وصفاته الواردة في القرآن والسنة الصحيحة وإمرارها كما جاءت من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ[الشورى:11] كما نص على ذلك أهل العلم كابن القيم في كتبه كالصواعق والنونية وغيرها، وشيخ الإسلام ابن تيمية رحمه الله في كتبه كالحموية والتدمرية والواسطية، والإمام ابن خزيمة رحمه الله في كتاب التوحيد، وعبد الله بن أحمد في كتاب السنة وغيرهم، هذا طريق أهل السنة والجماعة يؤمنون بأسماء الله وصفاته ويمرونها كما جاءت في القرآن والسنة الصحيحة، إثباتًا بلا تمثيل وتنزيهًا بلا تعطيل، ويقولون: إن أسماءه وصفاته تليق به جل وعلا لا يشابه فيها خلقه ، ولهذا قال مالك وغيره: \"أمروها كما جاءت بلا كيف\" وهكذا يقول سفيان الثوري وابن عيينة والأوزاعي وغيرهم من أهل العلم، وقد جمع جملة من كلامهم شيخ الإسلام ابن تيمية رحمه الله في الحموية، وهكذا جمعها غيره من أهل العلم مثل ابن أبي العز في شرح الطحاوية، وابن القيم في الصواعق المرسلة وغيرهم، وكذلك ابن خزيمة رحمه الله وعبد الله بن أحمد والشيخ عثمان بن سعيد الدارمي في الرد على المريسي إلى غير ذلك.\nالمقصود أن مذهب أهل السنة والجماعة هو الإيمان بأسماء الله وصفاته الواردة في الكتاب والسنة الصحيحة وإمرارها كما جاءت من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، ولا زيادة، ولا نقص، بل هي توقيفية حسب ما جاء في القرآن والسنة، فيثبتونها إثباتًا بلا تمثيل، وينزهون الله عن مشابهة خلقه تنزيهًا بلا تعطيل  نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12397/مذهب-اهل-السنة-في-اسماء-الله-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53909.mp3","categories":["الأسماء والصفات"]},{"id":13985,"question":"هذا طالب من ليبيا رمز لاسمه بـ (أ. أ. أ) يقول: سماحة الشيخ! ما هو مذهب أهل السنة والجماعة في الأسماء والصفات؟","title":"مذهب أهل السنة في أسماء الله وصفاته","answer":"الجواب: مذهب أهل السنة والجماعة: إثبات أسماء الله وصفاته الواردة في القرآن والسنة الصحيحة وإمرارها كما جاءت من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ[الشورى:11] كما نص على ذلك أهل العلم كابن القيم في كتبه كالصواعق والنونية وغيرها، وشيخ الإسلام ابن تيمية رحمه الله في كتبه كالحموية والتدمرية والواسطية، والإمام ابن خزيمة رحمه الله في كتاب التوحيد، وعبد الله بن أحمد في كتاب السنة وغيرهم، هذا طريق أهل السنة والجماعة يؤمنون بأسماء الله وصفاته ويمرونها كما جاءت في القرآن والسنة الصحيحة، إثباتًا بلا تمثيل وتنزيهًا بلا تعطيل، ويقولون: إن أسماءه وصفاته تليق به جل وعلا لا يشابه فيها خلقه ، ولهذا قال مالك وغيره: \"أمروها كما جاءت بلا كيف\" وهكذا يقول سفيان الثوري وابن عيينة والأوزاعي وغيرهم من أهل العلم، وقد جمع جملة من كلامهم شيخ الإسلام ابن تيمية رحمه الله في الحموية، وهكذا جمعها غيره من أهل العلم مثل ابن أبي العز في شرح الطحاوية، وابن القيم في الصواعق المرسلة وغيرهم، وكذلك ابن خزيمة رحمه الله وعبد الله بن أحمد والشيخ عثمان بن سعيد الدارمي في الرد على المريسي إلى غير ذلك.\nالمقصود أن مذهب أهل السنة والجماعة هو الإيمان بأسماء الله وصفاته الواردة في الكتاب والسنة الصحيحة وإمرارها كما جاءت من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، ولا زيادة، ولا نقص، بل هي توقيفية حسب ما جاء في القرآن والسنة، فيثبتونها إثباتًا بلا تمثيل، وينزهون الله عن مشابهة خلقه تنزيهًا بلا تعطيل  نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12397/مذهب-اهل-السنة-في-اسماء-الله-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53909.mp3","categories":["الأسماء والصفات"]},{"id":14080,"question":"مستمعٌ من الرياض -هو عمر إبراهيم سوداني- بعث برسالةٍ ضمنها عددًا من الأسئلة:في سؤاله الأول يقول: ورد في كتاب \"العقيدة الواسطية\" لشيخ الإسلام في صفحة (88): سأل سائلٌ رسول الله ﷺ: أين كان ربنا قبل أن يخلق السماوات والأرض؟ وأجاب: بأنه كان في عماء ... الحديث، ما معنى هذا الحديث؟","title":"معنى حديث: أين كان ربنا قبل أن يخلق السماوات والأرض؟","answer":"الجواب: هذا الحديث معناه: أنه كان في سحابٍ، قال العلماء: معنى \"العماء\": السحاب. قال بعضهم: الغليظ. وقال بعضهم: الرقيق. والحديث في سنده بعض المقال. والله جلَّ وعلا له صفات الكمال من كل الوجوه، ومُنزَّهٌ عن صفات النقص والعيب من كل الوجوه ، كما قال : قُلْ هُوَ اللَّهُ أَحَدٌ  ۝  اللَّهُ الصَّمَدُ  ۝  لَمْ يَلِدْ وَلَمْ يُولَدْ  ۝  وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص]، وقال : لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]. وهذا الحديث مشهورٌ من حديث أبي رزين العقيلي من رواية وكيع بن حدس، وهذا الرجل -وكيع- ليس من المشهورين بالثقة. وفي هذا الحديث أن الرسول ﷺ لما سئل: أين كان ربنا قبل أن يخلق السماوات والأرض؟ قال: كان في عماء، ما فوقه هواء، وما تحته هواء، فإن صحَّ فالمعنى مثلما قال العلماء -علماء اللغة-: العماء: السحاب. قال بعضهم: السحاب الرقيق. وقال بعضهم: السحاب الغليظ. هذا معناه لو صحَّ. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12527/معنى-حديث-اين-كان-ربنا-قبل-ان-يخلق-السماوات-والارض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61406.mp3","categories":["شروح الحديث","الأسماء والصفات"]},{"id":14534,"question":"أحفظ حديثًا عن رسول الله ﷺ يقول معناه: إن لله تسعة وتسعين اسمًا، مائة إلا واحدًا، من أحصاها دخل الجنة ولكنني أملك قائمة بأسماء الله الحسنى، وبعد أن أحصيتها وجدتها مائة اسم، هل اسم الستار من أسماء الله الحسنى؟وجهونا جزاكم الله خيرًا.","title":"هل الستار من أسماء الله تعالى؟","answer":"الجواب: لا أعلم في ذلك ما يدل على أن الستار من أسمائه، وإن كان يستعمله الناس، لكن لا أعلم في ذلك حديثًا صحيحًا عن النبي ﷺ، وإنما جاء الستير: إن ربكم حيي ستير، يستحي من عبده إذا رفع يديه إليه أن يردهما صفرًا. فأما الستار فلا أعلم به حديثًا صحيحًا يدل على أنه من أسمائه سبحانه، وأسماء الله موجودة في كتابه العزيز، وفيما صح في السنة عن النبي -عليه الصلاة والسلام-، وهي أكثر من مائة إلا واحد، ولكن هذه المائة إلا واحد رتب عليها النبي ﷺ أن من أحصاها دخل الجنة، وفي اللفظ الآخر: من حفظها دخل الجنة يعني: من أحصاها وعمل بمقتضاها، أما مجرد حفظها من دون عمل ما يكون سببًا لدخول الجنة، ولا يكون صاحبها محصيًا لها، فإذا أحصاها واستقام على معناها، دخل الجنة، نعم.","link":"https://binbaz.org.sa/fatwas/13029/هل-الستار-من-اسماء-الله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_634/nour_63411.mp3","categories":["الأسماء والصفات"]},{"id":14542,"question":"هذا سائل للبرنامج أخوكم من السودان (ل. ع. ل) يقول في هذا  سماحة الشيخ، الإيمان بالأسماء والصفات من أهم شروط اكتمال العقيدة الصحيحة، ومنها: الاستواء على العرش، ولكن نجد في بعض البلاد بأنهم يقولون: بأن الله في كل مكان، بماذا تنصحونهم؟ وإن ماتوا على هذا هل هم خارج الملة؟ أفتونا بالتفصيل.جزاكم الله خيرًا.","title":"ما حكم من يقول بأن الله في كل مكان؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فهذا سؤال مهم عظيم، يجب على كل مسلم أن ينتبه له، وقد أوضحه الرب -جل وعلا- في كتابه العظيم، أوضح الجواب في كتابه العظيم ، وهو الإيمان بعلو الله واستوائه على عرشه، قد دل كتاب الله العظيم في سبعة مواضع على أنه سبحانه فوق العرش، قد استوى عليه استواء يليق بجلاله وعظمته، لا يشابه خلقه في شيء من ذلك ، كما قال -جل وعلا- في سورة الأعراف: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهَارَ يَطْلُبُهُ حَثِيثًا وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّرَاتٍ بِأَمْرِهِ أَلا لَهُ الْخَلْقُ وَالأَمْرُ تَبَارَكَ اللَّهُ رَبُّ الْعَالَمِينَ [الأعراف:54] في سبعة مواضع من القرآن، ومنها قوله -جل وعلا- في سورة طه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]. فالذي عليه أهل السنة والجماعة الإيمان بذلك، وأنه سبحانه فوق العرش في العلو قد استوى على العرش استواءً يليق بجلاله وعظمته، كما قال تعالى: فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12] قال سبحانه: وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255] قال سبحانه: تَعْرُجُ الْمَلائِكَةُ وَالرُّوحُ إِلَيْهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ [المعارج:4] قال سبحانه: إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ وَالْعَمَلُ الصَّالِحُ يَرْفَعُهُ [فاطر:10] إلى آيات كثيرة تدل على علوه سبحانه، وأنه فوق العرش، فوق جميع الخلق، وهذا قول أهل السنة والجماعة، وهو الذي جاءت به الأنبياء -عليهم الصلاة والسلام- جميعًا، وهو الذي دل عليه القرآن العظيم، ودلت عليه سنة الرسول ﷺالمتواترة، وأجمع عليه المسلمون، الصحابة ومن بعدهم، ومن زعم أن الله في كل مكان فقد كفر؛ لأنه مكذب لله ولرسوله، ومكذب لجماعة المسلمين. فالواجب على كل من يعتقد هذا الاعتقاد أن يتوب إلى الله، وأن يقلع عن ذنبه العظيم، وأن يؤمن بأن الله سبحانه في العلو فوق العرش فوق جميع الخلق -جل وعلا-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13039/ما-حكم-من-يقول-بان-الله-في-كل-مكان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_555/55505.mp3","categories":["الأسماء والصفات"]},{"id":14769,"question":"مجموعة من طلاب العلم بعثوا بهذا السؤال، يقولون في سؤالهم: نود من سماحة الشيخ أن يتحدث عن مذهب أهل السنة والجماعة في الأسماء والصفات؛ لأننا اختلفنا كثيرًا مع الإخوان في ذلك حول هذا الموضوع، وجهونا سماحة الشيخ.","title":"منهج أهل السنة والجماعة في الأسماء والصفات","answer":"الجواب: مذهب أهل السنة والجماعة في أسماء الله وصفاته: أنهم يؤمنون بها، ويثبتونها كما جاءت في القرآن والسنة، ويمرونها كما جاءت؛ من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، هكذا قول أهل السنة والجماعة، وهم أصحاب النبي ﷺ ومن سلك سبيلهم، يؤمنون بأسماء الله وصفاته الواردة في القرآن الكريم، أو في السنة الصحيحة، ويثبتونها لله على الوجه اللائق بالله، من غير تحريف لها، ومن غير تعطيل، ومن غير تكييف، ولا تمثيل، يعني: لا يحرفونها ويغيرونها، ولا يعطلونها كما تفعل الجهمية والمعتزلة. ولا يمثلون صفات الله بصفات خلقه، ولا يكيفون ويقولون: كيفيتها كذا، كيفيتها كذا، لا، بل يمرونها كما جاءت، من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، مثل: الرحمن، نقول: هو موصوف بالرحمة على الوجه اللائق بالله، ليست مثل رحمة المخلوقين، ولا نعلم كيفيتها، ولا نزيد ولا ننقص، وهكذا نقول: إن الله موصوف بالاستواء: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]. أما كيف استوى؟ الله أعلم، ولا نقول كما تقول الجهمية:إنه استولى، لا، نقول: استوى، يعني: ارتفع وعلا فوق العرش، الاستواء هو العلو والارتفاع، لكن على الوجه اللائق بالله، لا يشابه استواء المخلوقين على دوابهم، أو في سطوحهم، لا، استواؤه يليق به، ويناسبه، لا يماثل صفات المخلوقين، ولا يعلم كيفيته إلا هو . كذلك كونه يغضب، يغضب صحيح هو يغضب -جل وعلا- على من عصاه، وخالف أمره، لكن ليس مثل غضبنا، ولا نكيف ونقول: كيفيته كذا وكذا، لا، نقول: يغضب غضبًا يليق بجلاله لا يشابه صفات المخلوقين، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] قال تعالى: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] قال تعالى: فَلا تَجْعَلُوا لِلَّهِ أَندَادًا [البقرة:22] يعني: أشباهًا ونظراء. وهكذا نقول: إنه يعطي ويمنع، وإنه يحب، وأنه يكره، لكن على الوجه اللائق بالله، لا يشابه صفات المخلوقين في محبتهم وكراهتهم وبغضهم وسخطهم، لا، صفاته تليق به، وهكذا نقول: له وجه، وله يد، وله قدم، وله سمع، وله بصر، لكن ليس مثل أسماعنا، ولا مثل أبصارنا، ولا مثل أيدينا، ولا مثل وجوهنا، وجه يليق بالله، يد تليق بالله، سمع يليق بالله، عين تليق بالله، لا يشابه خلقه في شيء من صفاته -جل وعلا-، كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقد أخبر عن نفسه: إنه سميع بصير، إِنَّهُ عَزِيزٌ حَكِيمٌ [الأنفال:63]: بَلْ يَدَاهُ مَبْسُوطَتَانِ [المائدة:64]، مَا مَنَعَكَ أَنْ تَسْجُدَ لِمَا خَلَقْتُ بِيَدَيَّ [ص:75] يقول النبي ﷺ: لا تزال جهنم يلقى فيها، وهي تقول: هل من مزيد؟ حتى يضع الجبار فيها قدمه فينزوي بعضها إلى بعض، ثم تقول: قط قط يعني: حسبي حسبي، وهكذا بقية الصفات نمرها كما جاءت، مع الإيمان بها، وإثباتها لله على الوجه اللائق بالله، من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، نقول: إنها ثابتة، وإنها حق، ولا يعلم كيفيتها إلا هو سبحانه، كما قال -جل وعلا-: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]. ولما سئل مالك بن أنس -رحمه الله- عن الاستواء، قال: الاستواء معلوم، والكيف مجهول، والإيمان به واجب، والسؤال عن ذلك بدعة، يعني: عن الكيفية. وهكذا قال سفيان الثوري، وابن عيينة والأوزاعي، والإمام أحمد بن حنبل، والإمام إسحاق بن راهويه، وغيرهم من أئمة السلف، وهكذا الصحابة والتابعون على هذا الطريق، لا يمثلون صفات الله بصفات خلقه، ولا يكيفونها، ولا يقولون: كيف كيف؟ بل يقولون: نثبتها لله، على الوجه اللائق بالله، من غير تحريف، ولا تعطيل، ولا تكييف، ولا تمثيل، بل نقول كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13263/منهج-اهل-السنة-والجماعة-في-الاسماء-والصفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_561/56108.mp3","categories":["الأسماء والصفات"]},{"id":14915,"question":"طيب بالنسبة لشق السؤال الثاني يقول: وحكم التسمية باسم الجلالة على البشر مثل البصير والعزيز وغيرها؟","title":"حكم تسمية الشخص بالبصير والعزيز وغيرهما","answer":"الجواب: أسماء الرب قسمان: قسم منها يجوز، وقسم لا يجوز، ما يقال: الخلاق، ولا الرزاق، ولا رب العالمين، ولا، لكن مثل عزيز وبصير لا بأس، الله سمى بعض مخلوقاته كذلك: فَجَعَلْنَاهُ سَمِيعًا بَصِيرًا [الإنسان:2] قال: قَالَتِ امْرَأَةُ الْعَزِيزِ [يوسف:51] فمثل هذه الأشياء تطلق على المخلوق عزيز قومه، وكذا البصير بالأمور أو بصير بمعنى المبصر، كذلك حكيم، يعني: من الحكمة، لا بأس بهذه الأشياء؛ لأن هذه مشتركة، للمخلوق نصيب منها، والله له الأكمل منها ، لكن الأسماء المختصة بالله لا تطلق على غير الله، لا يقال: الله لابن آدم، ولا الرحمن، ولا الخلاق، ولا الرزاق، ولا خالق الخلق، ولا أشباهه مما يختص بالله ، نعم.","link":"https://binbaz.org.sa/fatwas/13424/حكم-تسمية-الشخص-بالبصير-والعزيز-وغيرهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_646/nour_64607.mp3","categories":["الأسماء والصفات"]},{"id":15009,"question":"هذا سائل من جمهورية مصر العربية، يقول: ما هو مذهب أهل السنة والجماعة في الأسماء والصفات؟ وما الفرق -يا سماحة الشيخ- بين الأسماء والصفات؟","title":"مذهب أهل السنة والجماعة في الأسماء والصفات","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فمذهب أهل السنة والجماعة في أسماء الله وصفاته: هو إثباتها، وإمرارها كما جاءت، على الوجه اللائق بالله ، من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، عملًا بقوله سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقوله سبحانه: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180] فقد سمى نفسه بأسماء، ووصف نفسه بصفات؛ فالواجب إثباتها، وإمرارها كما جاءت: كالرحيم والعزيز والقدير والسميع والبصير والرؤوف والغفور والعليم، إلى غير ذلك، يجب إثباتها لله على الوجه اللائق بالله، من غير تحريف للفظها، ولا تعطيل لمعناها، ولا تكييف، ما يقول: كيفيتها كذا، ولا كيفيتها كذا، ولا أنها مثل كذا، مثل كذا، قال الله تعالى: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقال رجل لـمالك -رحمه الله-، الإمام مالك بن أنس -رحمه الله- قال له رجل: يا أبا عبد الله الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5]، كيف استوى؟ فقال له -رحمه الله-: \"الاستواء معلوم، والكيف مجهول، والإيمان به واجب، والسؤال عن ذلك بدعة\". وهكذا جاء هذا المعنى عن ربيعة بن أبي عبدالرحمن شيخ مالك، وجاء معناه عن أم سلمة -رضي الله عنها-، معنى الاستواء معلوم، يعني: معروف معناه: أنه العلو فوق العرش، هذا الاستواء، كما قال تعالى:  الرّحْمنُ عَلََى الْعَرْشِ اسْتَوَى [طه:5] وقال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] في سبعة مواضع من القرآن، صرح فيها سبحانه بأنه استوى على العرش، يعني: ارتفع عليه، وعلا عليه -جل وعلا-، استواءً يليق بجلاله، لا يشابه الخلق في استوائهم، ولا يكيف، ما يقال: كيفيته كذا، كيفيته كذا، بل يقال: الله أعلم بالكيفية، فالاستواء حق ومعلوم، وهو العلو فوق العرش، أما الكيفية فلا يعلمها إلا هو . وهكذا قال جميع أهل السنة من الصحابة ومن بعدهم، كلهم يقولون هذا المعنى: الاستواء، الرحمة، العلم، القدرة، كلها معلومة، أما الكيف غير معلوم، والإيمان بهذا واجب؛ نؤمن بأن الله سميع، عليم، حكيم، رؤوف، رحيم، قدير، سميع، بصير، لطيف، إلى غير ذلك من أسمائه، ولكن لا نكيفها، بل نقول: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] معناها حق. فالرحمن: هذا اسم، والرحيم: صفة، العليم: اسم، والعلم: صفة، القدير: اسم، والقدرة: صفة، هذا هو الفرق بينهما، فتقول: اللهم إني أسألك بقدرتك، أسألك بعلمك كذا وكذا، هذه صفة، اللهم إني أسألك بأنك العليم بأنك الرحمن، توسل بالأسماء، كما قال تعالى: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا [الأعراف:180]. فالصفة هي المعنى، والاسم: هو اللفظ المشتمل على الذات والمعنى، يقال له: اسم، أما المعنى فقط يقال له: وصف، الرحمن هذا يسمى علم اسم؛ لأنه دال على الذات وعلى الصفة وهي الرحمة، العليم: اسم؛ لأنه دال على الذات وعلى العلم، السميع: اسم؛ لأنه دال على الذات وعلى السمع، البصير: اسم؛ دال على الذات والبصر، هذه يقال لها: أسماء، أما الصفات: فالعلم صفة، الرحمة صفة، القدرة صفة، السمع صفة، وهكذا، يجب إمرار الجميع كما جاءت، وإثباتها لله -كما قال أهل السنة والجماعة- على الوجه اللائق بالله سبحانه، من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، صفات الله تليق به، لا يشابه خلقه في شيء من صفاته -جل وعلا-، كما قال سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74] وقال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] ، نعم. المقدم: أحسن الله إليكم، وأثابكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13503/مذهب-اهل-السنة-والجماعة-في-الاسماء-والصفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_563/56301.mp3","categories":["الأسماء والصفات"]},{"id":15354,"question":"المستمع حسين علي محمد، بعث يسأل عن تفسير بعض الآيات القرآنية، منها: قوله تعالى أعوذ بالله من الشيطان الرجيم : أَأَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الأَرْضَ فَإِذَا هِيَ تَمُورُ [الملك:16] وقوله تعالى: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [يونس:3] يرجو أن تفسروا هذه الآيات، وعنون لها بقوله: آيات عن العلو والاستواء.","title":"تفسير بعض الآيات الدالة على علو الله","answer":"الجواب: هذه الآيات الكريمات فسرها أهل العلم من أهل السنة والجماعة كـالبغوي في التفسير، وابن كثير، وابن جرير، وغيرهم، ومعناها عند أهل السنة واضح، فقوله -جل وعلا-: أَأَمِنتُمْ مَنْ فِي السَّمَاءِ: يفسر بمعنيين:  أحدهما: في السماء يعني: المبنية السماوات المعروفة، فيكون معنى في يعني: على، من على السماوات، كما قال -جل وعلا-: فَسِيرُوا فِي الأَرْضِ [آل عمران:137] يعني: على الأرض، قال -جل وعلا- عن فرعون أنه قال لخصومه: وَلَأُصَلِّبَنَّكُمْ فِي جُذُوعِ النَّخْلِ [طه:71] يعني: على جذوع النخل. والمعنى الثاني: أن المراد بالسماء العلو، جهة العلو، فتكون (في) للظرفية، والمعنى (أأمنتم من في العلو) وهو الله سبحانه، فإنه في العلو فوق العرش -جل وعلا-، قد استوى على العرش استواء يليق بجلاله وعظمته، لا يشابه الخلق في شيء من صفاته ، فهو فوق جميع الخلق، في أعلى شيء، فوق جميع الخلق . وهكذا قصد فرعون اللعين حين قال: يَا هَامَانُ ابْنِ لِي صَرْحًا لَعَلِّي أَبْلُغُ الأَسْبَابَ [غافر:36] يعني: الطرق، أَسْبَابَ السَّمَاوَاتِ[غافر:37] يعني: طرق السموات، فَأَطَّلِعَ إِلَى إِلَهِ مُوسَى [غافر:37] عرف الخبيث أنه في العلو؛ لأن موسى بلغه أنه في العلو؛ ولهذا زعم هذا الزعم، وهو لا يستطيع ذلك، ولا هامان، فإن العلو إلى السماوات لا يستطيعه المخلوق إلا بأمر من الله ، كما عرج الله بنبينا محمد ﷺ إلى العلو، مع جبرائيل -عليه الصلاة والسلام-. فالسماوات لها أبواب، ولها حرس، لا يستطيع أحد الدخول إليها إلا بإذن من الله ، وهذه من مكابرة فرعون من مكابرته ودعاواه الباطلة، وهو يعلم أن الله في العلو، كما أخبره موسى، فلهذا قال هذه المقالة، وهي من أدلة أهل السنة على أن الله في العلو، وأن موسى بلغ فرعون أن الله في العلو، فلهذا قال هذه المقالة. وهكذا قوله سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] يعني: ثم علا على العرش، وهذا قاله سبحانه في سبعة مواضع في كتابه -جل وعلا-، بين في ذلك استواءه على العرش  وأنه فوق العرش، كما قال في سورة طه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] فالمعنى الاستواء: العلو والارتفاع، ومنه استوى على السفينة يعني: ارتفع عليها، ومنه اسْتَوَتْ عَلَى الْجُودِيِّ [هود:44] يعني: ارتفعت على الجودي. فالاستواء معناه: العلو والارتفاع، استوى فلان على الدابة يعني: صار على ظهرها، واستوى على السطح: صار فوق السطح، واستوى على الجمل: صار فوق الجمل، فمعنى استوى على العرش يعني: ارتفع فوق العرش -جل وعلا-، واستواؤه يناسبه سبحانه، ويليق به ، ولا يشابه الخلق في استوائهم على دوابهم، وعلى الجبال، وعلى غير هذا. وهكذا كل صفات الله تليق به ، ولا يشبه فيها خلقه -جل وعلا- كما قال سبحانه: لََيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقال : وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] وقال سبحانه: فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ[النحل:74] وقال : هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65] يعني: لا سمي له، ولا كفء له ، وهكذا أمثال هذه الآيات كلها تدل على علو الله، وأنه فوق العرش، مثل وَهُوَ الْعَلِيُّ الْعَظِيمُ [الشورى:4] .. فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ [غافر:12] هو العلي العلو الكامل، علو الذات، وعلو القهر والسلطان، وعلو المكان، فهو فوق العرش -جل وعلا-، فوق جميع الخلق . والعرش سقف المخلوقات وأعلاها، والله فوقه ، ومع هذا لا يخفى عليه شيء من أحوال عباده، يعلم كل شيء ، نعم، الله أكبر! نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13857/تفسير-بعض-الايات-الدالة-على-علو-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_498/49804.mp3","categories":["الأسماء والصفات","فتاوى متنوعة"]},{"id":15692,"question":"سماحة الشيخ، هذا السائل من تشاد أبشا، يقول: هل أفعال الله  قديمة أو حادثة؟ وكيف نوفق بين ذلك؟ جزاكم الله عنا وعن المسلمين خير الجزاء.","title":"مسألة أزلية أفعال الله تعالى وحدوثها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فأفعال الله -سبحانه جل وعلا-، أصلها قديم، وأنواعها تحدث شيئًا بعد شيء، فهو الخلاق، لم يزل خلاقًا ، لم يزل فعالًا لما يريد ، لكن أفعاله تجدد بحسب حال الواقع، فخلق آدم وقع بعد أن كان عدمًا، وهكذا خلق الملائكة، وهكذا خلق السماوات، وهكذا خلق الأرض، وهكذا خلق من بعد ذلك، وهكذا رضاه عمن مضى ورضاه عمن يأتي من المؤمنين، وغضبه على من مضى وغضبه على من يأتي من الكفار، وهكذا ، فجنس أفعاله وصفاته قديمة، والصفات قسمان:\nقسم ذاتي، كعلمه، وسمعه، وبصره، فهذا لم يزل سبحانه سميعًا، بصيرًا، عليمًا، قادرًا على كل شيء -جل وعلا-، وأفعال متعددة تتعلق بالمخلوقين تجدد بفعل المخلوقين، فخلق السماوات، وخلق الأرض، وقع بعد أن كان عدمًا، وخلق آدم وقع بعد أن كان عدمًا، وهكذا خلق الجنة والنار، وهكذا غير ذلك، كلها تقع شيئًا بعد شيء، وهو سبحانه موصوف بأنه الخلاق القادر على كل شيء، ولكنه يفعل ما يشاء، كما قال تعالى: إِنَّ بَطْشَ رَبِّكَ لَشَدِيدٌ ۝ إِنَّهُ هُوَ يُبْدِئُ وَيُعِيدُ ۝ وَهُوَ الْغَفُورُ الْوَدُودُ ۝ ذُو الْعَرْشِ الْمَجِيدُ ۝ فَعَّالٌ لِمَا يُرِيدُ [البروج:12-16] وقال سبحانه: يَفْعَلُ مَا يَشَاءُ [آل عمران:40] فهو سبحانه يفعل ما يشاء، قديمًا وحديثًا -جل وعلا- لم يزل خلاقًا، لم يزل قادرًا، لم يزل عالمًا، لم يزل حيًا قيومًا سميعًا بصيرًا، إلى غير هذا ، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14246/مسالة-ازلية-افعال-الله-تعالى-وحدوثها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57301.mp3","categories":["الأسماء والصفات"]},{"id":15693,"question":"من أسئلة السائل من تشاد -سماحة الشيخ- يقول: أين الله؟ هل هو على عرشه؟ أم في كل مكان؟ وما حكم من يقول: بأن الله في كل مكان؟","title":"إثبات علو الباري وحكم من قال إنه في كل مكان","answer":"الجواب: الله سبحانه فوق العرش، في العلو، فوق جميع الخلق، عند أهل السنة والجماعة، هكذا جاءت الرسل بهذا -عليهم الصلاة والسلام-، كل الرسل جاؤوا بأن الله فوق العرش، فوق جميع الخلق، ، قال تعالى: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى[طه:5] قال سبحانه: أَأَمِنتُمْ مَنْ فِي السَّمَاءِ [الملك:16] قال -جل وعلا-: إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ وَالْعَمَلُ الصَّالِحُ يَرْفَعُهُ [فاطر:10] قال -جل وعلا-: تَعْرُجُ الْمَلائِكَةُ وَالرُّوحُ إِلَيْهِ فِي يَوْمٍ كَانَ مِقْدَارُهُ خَمْسِينَ أَلْفَ سَنَةٍ [المعارج:4] قال -جل وعلا-: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] في سبعة مواضع، صرح فيها سبحانه بأنه فوق العرش، قد استوى عليه، استواءً يليق بجلاله وعظمته، لا يشابه الخلق في استوائهم، ولا في غير ذلك من صفاته -جل وعلا-، قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] قال تعالى: قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ[الإخلاص:1-4] قال سبحانه: هَلْ تَعْلَمُ لَهُ سَمِيًّا [مريم:65] استفهام إنكار، يعني: لا سمي له، ولا كفء له،  «جاء رجل من الصحابة إلى النبي ﷺ بجارية يريد أن يعتقها، قال لها النبي ﷺ: يا جارية، أين الله؟ قالت: في السماء، قال لها: من أنا؟ قالت: أنت رسول الله، قال: أعتقها فإنها مؤمنة أخرجه مسلم في صحيحه. لما سألها: أين الله؟ قالت: في السماء، فقال: أعتقها فإنها مؤمنة دل ذلك على أن ربنا في السماء، في العلو، فوق العرش، فوق جميع الخلق، وهذا معنى قوله سبحانه: أَأَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الأَرْضَ فَإِذَا هِيَ تَمُورُ ۝ أَمْ أَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ [الملك:16-17] هكذا جاء في سورة الملك، وهذا إجماع أهل السنة والجماعة، أجمع الصحابة، كما أجمعت الرسل -عليهم الصلاة والسلام- أن الله فوق العرش، أن الله في العلو -جل وعلا-، ومن هذا قوله -جل وعلا-: وَقَالَ فِرْعَوْنُ يَا هَامَانُ ابْنِ لِي صَرْحًا لَعَلِّي أَبْلُغُ الأَسْبَابَ ۝ أَسْبَابَ السَّمَوَاتِ فَأَطَّلِعَ إِلَى إِلَهِ مُوسَى [غافر:36-37] دل على أن موسى أخبره أن الله في العلو، وأنه فوق العرش؛ ولهذا قال فرعون ما قال. ومن قال: إن الله في كل مكان، أو ليس في العلو، فهو كافر، مكذب لله، ولرسوله، ومكذب لإجماع أهل السنة والجماعة، كـالجهمية وأشباههم، والمعتزلة فهؤلاء من أكفر الناس؛ لإنكارهم أسماء الله وصفاته -جل وعلا-، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14247/اثبات-علو-الباري-وحكم-من-قال-انه-في-كل-مكان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57302.mp3","categories":["الأسماء والصفات"]},{"id":15694,"question":"من أسئلة هذا السائل، يقول -يا سماحة الشيخ-: حديث النزول، قول: ينزل ربنا في الثلث الأخير هل ينزل ربنا ، أم تنزل الرحمة؟","title":"إثبات صفة النزول لله تعالى","answer":"الجواب: تواترت الأحاديث عن رسول الله ﷺ في الصحيحين وغيرهما؛ أن الله -جل وعلا-: ينزل ربنا إلى سماء الدنيا كل ليلة يقول النبي ﷺ: ينزل ربنا إلى سماء الدنيا كل ليلة، حين يبقى ثلث الليل الآخر، فينادي، فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له أخبر عن نفسه أنه ينزل، لكن لا يعلم كيف النزول إلا هو، كما لا يعلم كيف الاستواء إلا هو ، ينزل كما يشاء، وكما يليق بجلاله، لا يعلم كيف نزوله إلا هو، فنقول: ينزل، ولا نكيف، ولا نمثل، ولا نزيد، ولا ننقص، بل نقول: ينزل ربنا، كما قال: ينزل ربنا إلى سماء الدنيا كل ليلة، حين يبقى ثلث الليل الآخر، فيقول: من يدعوني فأستجيب له، من يسألني فأعطيه، من يستغفرني فأغفر له وفي اللفظ الآخر: هل من سائل فيعطى سؤله؟ هل من داعٍ فيستجاب له؟ هل من مستغفر فيغفر له؟ وفي اللفظ الآخر: هل من تائب، فيتاب عليه؟. يجب على كل مسلم أن يؤمنوا بهذا النزول إيمانًا قاطعًا، يقينًا، على الوجه اللائق بالله، لا يكيف، كما نقول في الاستواء: الاستواء معلوم، والكيف مجهول، فهكذا نقول: النزول معلوم، والكيف مجهول، هكذا قال أئمة السلف، كـمالك، وربيعة بن أبي عبد الرحمن شيخه، وسفيان الثوري، والأوزاعي، وأحمد بن حنبل، وغيرهم من أئمة الإسلام، قالوا في الاستواء -وهكذا في النزول-: استوى كما يليق بجلاله، استوى بلا كيف، الاستواء معلوم، والكيف مجهول، والإيمان به واجب، والسؤال -يعني: عن الكيف- بدعة. فهكذا نقول: يغضب، ويرضى ، غضبًا يليق بجلاله، لا يشابه غضب المخلوقين، وهكذا يسمع ويبصر، لا كسمع المخلوقين، ولا كبصر المخلوقين، سمعًا يليق بجلاله، وبصرًا يليق بجلاله، لا يشبه صفات المخلوقين، وهكذا بقية الصفات، بابها واحد، نثبتها لله على الوجه اللائق بجلال الله، لا يشابه خلقه في شيءٍ من صفاته، قال تعالى: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] سبحانه!\nهذا قول أهل السنة والجماعة، وهم أصحاب النبي ﷺ وأتباعهم بإحسان إلى يوم القيامة، نعم. المقدم: أحسن الله إليكم سماحة الشيخ، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14249/اثبات-صفة-النزول-لله-تعالى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57303.mp3","categories":["الأسماء والصفات"]},{"id":15815,"question":"مع مطلع هذه الحلقة نعود إلى رسالة وصلت إلينا من البويعية، باعثها سوداني مقيم من هناك، يقول: أخوكم (ف. ع. ص) أخونا عرضنا بعض أسئلة له في حلقة مضت، وفي هذه الحلقة يسأل سماحتكم فيقول: جرى بيني وبين أحد الإخوة نقاش على النحو التالي:إذ سألته عن وجود الله تعالى، فقال: إن الله لا يتصف بالزمان ولا المكان، فاستدليت له بقول الله : الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى[طه:5] فقال: إنك كافر، إن الله ليس في السماء، ما حكم التكفير؟ وما حكم من يعتقد مثل هذه العقيدة؟ وكيف نصحح معتقد الناس؟جزاكم الله خيرًا.","title":"حكم من ينكر استواء الله على العرش","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذا الرجل الذي قال لك هذا الكلام، وأن الله سبحانه ليس فوق العرش هو الكافر، هو الضال المضل؛ لأنه كذب الله، وكذب رسوله -عليه الصلاة والسلام-، فالله يقول -جل وعلا-: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى[طه:5] ويقول سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ[الأعراف:54] قال هذا سبحانه في سبعة مواضع من القرآن، وأخبر سبحانه أنه في السماء، قال: أَأَمِنتُمْ مَنْ فِي السَّمَاءِ[الملك:16] ولما جاء رجل بجارية إلى النبي ﷺ يريد أن يعتقها قال لها النبي ﷺ: أين الله؟ قالت: في السماء، قال: من أنا؟ قالت: أنت رسول الله، قال: أعتقها، فإنها مؤمنة. فالذي يقول: إن الله ليس في السماء، أو ليس فوق العرش كافر ضال جهمي خبيث، فالله يوصف بأنه في السماء، وأنه فوق العرش، فوق جميع الخلق  كما أخبر عن نفسه -جل وعلا-، فعليك أن تخبر من سألك عن هذا فتقول له: إن الله فوق العرش، فوق جميع الخلق، قد استوى على العرش استواءً يليق بجلاله ، لا يشابه خلقه في شيء من صفاته -جل وعلا-، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14402/حكم-من-ينكر-استواء-الله-على-العرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_744/nour_74401.mp3","categories":["الأسماء والصفات"]},{"id":16102,"question":"من المستمع أبو عبدالعزيز من الرياض أسئلة حول استقرار الله  على عرشه، يسأل أسئلة مترابطة تقريبًا، فيقول: ما هو مذهب أهل السنة والجماعة في استقرار الله  على العرش، وهل الإمام أبو حنيفة -رحمة الله عليه- قال: بأن الله في كل مكان بذاته؟ وما حكم الصلاة خلف من يفند أن الله  في كل مكان بذاته؟ أجيبونا عن هذه الأسئلة، ووضحوا؟ جزاكم الله خيرًا.","title":"مذهب أهل السنة والجماعة في صفة الاستواء","answer":"الجواب: مذهب أهل السنة والجماعة، وهم الصحابة، أصحاب النبي ﷺ وأتباعهم بإحسان، وهو قول الرسل جميعًا -عليهم الصلاة والسلام- أن الله فوق العرش، وعلمه في كل مكان  كما قال الله : الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] وقال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54] ذكر هذا سبحانه في سبعة مواضع في كتابه العظيم أنه فوق العرش، جل وعلا. ومعنى على العرش يعني: فوق العرش، قد علا عليه، واستقر فوقه  هكذا قال أهل السنة، على العرش، يعني: استوى عليه يعني: علا وارتفع، وفي عبارة بعضهم: واستقر، المعنى: أنه فوق العرش، والعرش سقف المخلوقات، وهو أعلاها، والله فوقه  هذا قول أهل الحق جميعًا، وأبو حنيفة منهم ممن يقول بهذا -رضي الله عنه ورحمه- ولا يقول: إن الله في كل مكان، حاشا وكلا.  بل هذا قول المعتزلة، والجهمية، وأشباههم، وهذا كفر وضلال، الذي يقول: إن الله في كل مكان، هذا كافر ضال، نسأل الله العافية، الله سبحانه فوق العرش، وعلمه في كل مكان -جل وعلا- يعلم كل شيء  لكنه بذاته فوق العرش  فوق جميع الخلق. والواجب على المؤمن أن يعتقد هذا الاعتقاد الذي دل عليه كتاب الله، وسنة الرسول -عليه الصلاة والسلام- وأجمع عليه سلف الأمة من أصحاب النبي ﷺ وأتباعهم بإحسان، ولا يجوز أن يقول: إن الله في كل مكان، هذا قول أهل الباطل من الجهمية، والمعتزلة، ومن سار على نهجهم، تعالى الله عن ذلك علوًا كبيرًا  نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14747/مذهب-اهل-السنة-والجماعة-في-صفة-الاستواء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_803/nour_80305.mp3","categories":["الأسماء والصفات"]},{"id":17082,"question":"هذا سائل من سوريا يقول يا سماحة الشيخ: كيف أفرق بين الأسماء والصفات؟ جزاكم الله خيرًا.","title":"كيفية التفريق بين الأسماء والصفات","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالأسماء واضحة إذا كان المقصود أسماء الله وصفاته؛ لأن السؤال مجمل، فأسماء الله ما سمى به نفسه؛ كالعزيز والحكيم والقدير والسميع والبصير هذه يقال لها: أسماء، والصفات: السمع، البصر، العلم.. القدرة، وما أشبه ذلك، هذا الفرق بينهما، الأسماء ما سمى به نفسه، سماه -جل وعلا-: كالعليم والحكيم والسميع والبصير. والصفات: ما وصف به نفسه، من العلم والقدرة والسمع والبصر والرحمة والعفو.. ونحو ذلك. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15891/كيفية-التفريق-بين-الاسماء-والصفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58901.mp3","categories":["الأسماء والصفات"]},{"id":17674,"question":"من أسئلة هذا السائل يقول يا سماحة الشيخ: هل يجوز التسمي بالأسماء التي تعتبر من صفات الله ، فإن بعض الناس يتسمى برحمة، فما حكم ذلك؟","title":"حكم التسمي بصفة من صفات الله","answer":"الجواب: ما أعلم فيه شيئًا، رحمة ما أعلم في هذا شيئًا، فالله اسمه الرحيم ما هو رحمة اسمه الرحيم اسم الله الرحيم والرحمن، أما الرحمة ما هي باسمه ما هي من أسمائه لكن من صفاته. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16605/حكم-التسمي-بصفة-من-صفات-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59503.mp3","categories":["الأسماء والصفات"]},{"id":18350,"question":"هذا السائل (إبراهيم . أ. أ) من المعهد العلمي بالحوطة يقول: سماحة الشيخ! ما هو مذهب أهل السنة والجماعة في العلو؟","title":"مذهب أهل السنة والجماعة في العلو","answer":"الجواب: مذهب أهل السنة والجماعة الإيمان بعلو الله، وأنه سبحانه فوق العرش، فوق جميع الخلق كما قال جل وعلا: فَالْحُكْمُ لِلَّهِ الْعَلِيِّ الْكَبِيرِ[غافر:12] قال جل وعلا: وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ[البقرة:255]. وقال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ[الأعراف:54] وقال سبحانه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى[طه:5] وقال جل وعلا: إِلَيْهِ يَصْعَدُ الْكَلِمُ الطَّيِّبُ وَالْعَمَلُ الصَّالِحُ يَرْفَعُهُ[فاطر:10] والآيات في هذا المعنى كثيرة. فأهل السنة والجماعة يؤمنون إيمانًا قطعيًا بأنه سبحانه في العلو فوق العرش فوق جميع الخلق، ليس بينهم خلاف في هذا والحمد لله. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17414/مذهب-اهل-السنة-والجماعة-في-العلو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78321.mp3","categories":["الأسماء والصفات"]},{"id":18659,"question":"سماحة الشيخ، ما مذهب أهل السنة والجماعة في الأسماء والصفات؟","title":"مذهب أهل السنة والجماعة في الأسماء والصفات","answer":"الجواب: مذهب أهل السنة والجماعة في الأسماء والصفات إثباتها لله على الوجه اللائق بالله، على الوجه اللائق بجلاله ، من غير تحريف ولا تعطيل، ولا تكييف ولا تمثيل، الصحابة  وأتباعهم بإحسان هم أهل السنة والجماعة، قاعدتهم: الإيمان بأسماء الله وصفاته، وإثباتها لله، وأنها حق، وأنها ثابتة على الوجه اللائق بالله، من غير تحريف لها لا بالزيادة، ولا بالنقص، ولا تعطيل لها كما تفعل الجهمية، ولا تمثيل كما تفعل المشبهة، بل يؤمنون بأنها حق، وأن الله -جل وعلا- مسمى بها، وموصوف بمعانيها، إثباتًا بلا تمثيل، وتنزيهًا بلا تعطيل؛ خلافًا للجهمية والمعتزلة، ومن شرع في ركابهم.\nالجهمية نفوا أسماء الله وصفاته، والمعتزلة نفوا الصفات، قالوا: سميع بلا سمع، عليم بلا علم، وهذا غاية في التعطيل نعوذ بالله، وهذا ضلال وكفر، فأهل السنة والجماعة يقولون: عليم بعلم، سميع بسمع، رحيم برحمة، يثبتون أسماءه وصفاته -جل وعلا-، هذا قول أهل السنة والجماعة، يثبتون أسماء الله، ويثبتون الصفات التي دلت عليها الأسماء، وأنها تليق بالله لا يشابهه فيها خلقه، كما قال سبحانه: قُلْ هُوَ اللَّهُ أَحَدٌ ۝ اللَّهُ الصَّمَدُ ۝ لَمْ يَلِدْ وَلَمْ يُولَدْ ۝ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ[الإخلاص:3-4] لا أحد يكافئه؛ لأنه كامل في كل شيء .\nوله المثل الأعلى، له الوصف الأعلى في كل شيء، وقال تعالى: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ[الشورى:11] لكماله في ذاته وصفاته لا يماثله شيء، كل المخلوقات ناقصة، وله الكمال المطلق ، علم المخلوق ناقص، رحمته ناقصة، سمعه ناقص إلى غير ذلك، أما صفات الله فهي كاملة لا يعتريها نقص، وثابتة لله لا يشابه فيها خلقه. سميع يسمع أقوال عباده، يسمع دعاءهم وإن كانوا في جوف البحر، وإن كانوا في الطبقات السفلى، يسمع دعاءهم، ويسمع حركاتهم، ويعلم أحوالهم، لا يخفى عليه خافية إِنَّ اللَّهَ بِكُلِّ شَيْءٍ عَلِيمٌ[المجادلة:7] ويقول سبحانه: لِتَعْلَمُوا أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا[الطلاق:12] ، نعم.\nالمقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17792/مذهب-اهل-السنة-والجماعة-في-الاسماء-والصفات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78805.mp3","categories":["الأسماء والصفات"]},{"id":18660,"question":"هذا سائل من اليمن عبد الله، يقول في هذا  ما معنى القول في دلالة الأسماء الحسنى: دلالة على الذات مطابقة، ودلالة على الصفات المشتقة، ودلالة على الصفات التي ما اشتقت منها التزامًا؟نرجو توضيح ذلك سماحة الشيخ.","title":"معنى دلالتا المطابقة والالتزام في الأسماء الحسنى","answer":"الجواب: هذا نعم صحيح وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا[الأعراف:180] الأسماء تدل على ذاته، الرحمن تدل ذاته، وأنه سبحانه ذات قائمة بنفسها، موصوفة بالرحمة، وهكذا السميع والعليم، والحكيم والقدير، تدل على الذات والصفة جميعًا دلالة مطابقة، الرحمن على الذات والرحمة، العزيز على الذات والعزة، الحكيم على الذات والحكمة، القدير على الذات والقدرة، وهكذا بقية الأسماء. وبالالتزام تدل على بقية الصفات؛ لأنه الكامل  فكونه الرحمن يدل على الرحمة، ويدل على أنه -جل وعلا- قادر على كل شيء، وأنه سميع بصير إلى غير ذلك باللزوم؛ لأن كماله يقتضي أنه سميع، وأنه قادر، وأنه عليم إلى غير ذلك؛ لأنه له الكمال المطلق، فمن لازم كونه رحمن، ومن لازم كونه سميع، ومن لازم كونه عليم؛ بقية الصفات الأخرى الدالة على كماله  نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17788/معنى-دلالتا-المطابقة-والالتزام-في-الاسماء-الحسنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_788/nour_78804.mp3","categories":["الأسماء والصفات"]},{"id":18737,"question":"رسالة وصلت إلى البرنامج من أحد المستمعين بدأها بقوله: نحمد الله  على أن من علينا ببرنامج (نور على الدرب) ونشكر علماءنا الأفاضل، وندعو لهم بالتوفيق والسداد في تبصير الأمة المسلمة بأمور دينها ودنياها، نرجو أن يجيب على هذه الأسئلة سماحة الشيخ عبد العزيز بن باز، مقدم الأسئلة: أبو مؤمن خلف الله علي مصري يعمل باليمن.أخونا يسأل في سؤاله الأول ويقول: سألني أخ مسلم: أين الله؟ فقلت له: في السماء، فقال لي: فما رأيك في قوله تعالى: وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ [البقرة:255] وذكر آيات كثيرة، ثم قال: لو زعمنا أن الله في السماء؛ لحددنا جهة معينة، فما رأي سماحتكم في ذلك؟ وهل هذه الأسئلة من الأمور التي نهينا عن السؤال عنها؟","title":"الدليل على علو الله فوق العرش","answer":"الجواب: قد أصبت في جوابك، وهذا الجواب الذي أجبت به هو الجواب الذي أجاب به النبي -عليه الصلاة والسلام-، فالله -جل وعلا- في السماء، في العلو  كما قال : أَأَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يَخْسِفَ بِكُمُ الأَرْضَ فَإِذَا هِيَ تَمُورُ ۝ أَمْ أَمِنتُمْ مَنْ فِي السَّمَاءِ أَنْ يُرْسِلَ عَلَيْكُمْ حَاصِبًا فَسَتَعْلَمُونَ كَيْفَ نَذِيرِ [الملك:16-17] وقال -جل وعلا-: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] وقال سبحانه: إِنَّ رَبَّكُمُ اللَّهُ الَّذِي خَلَقَ السَّمَوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ [الأعراف:54]. فهو  فوق العرش في جهة العلو، فوق جميع الخلق، عند جميع أهل العلم من أهل السنة، قد أجمع أهل السنة والجماعة -رحمة الله عليهم- على أن الله في السماء فوق العرش فوق جميع الخلق ، وهذا هو المنقول عن رسول الله ﷺ وعن أصحابه  وعن أتباعهم بإحسان، كما أنه موجود في كتاب الله القرآن. وقد سأل النبي ﷺ جارية جاء بها سيدها ليعتقها، فقال لها الرسول ﷺ: أين الله؟ قالت: في السماء، قال: من أنا؟ قالت: أنت رسول الله، قال: أعتقها، فإنها مؤمنة رواه مسلم في الصحيح، فالرسول ﷺ أقر هذه الجارية على الجواب، الذي قلته أنت، قال لها: أين الله؟ قالت: في السماء، قال: من أنا؟ قالت: أنت رسول الله، قال: أعتقها، فإنها مؤمنة وما ذاك إلا لأن إيمانها بأن الله في السماء يدل على إخلاصها لله، وتوحيدها لله، وأنها مؤمنة به سبحانه، وبعلوه فوق جميع خلقه، وبرسوله محمد -عليه الصلاة والسلام- حيث قالت: أنت رسول الله. \nأما قوله -جل وعلا-: وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ [البقرة:255] هذا لا ينافي ذلك، الكرسي فوق السماوات، والعرش فوق الكرسي، والله فوق العرش، فوق جميع الخلق  وتحديد الجهة لا مانع منه جهة العلو، بأن الله في العلو. وإنما يشبه بهذا بعض المتكلمين وبعض المبتدعة، ويقولون: ليس في جهة، وهذا كلام فيه تفصيل، فإن أرادوا: ليس في جهة مخلوقة، وأنه ليس في داخل السماوات، وليس في داخل الأرض، ونحو هذا صحيح، أما إن أرادوا أنه ليس في العلو، هذا باطل، وهذا خلاف ما دل عليه كتاب الله، وما دلت عليه سنة رسول الله -عليه الصلاة والسلام-، وما دل عليه إجماع سلف الأمة. فقد أجمع علماء الإسلام أن الله في السماء فوق العرش، فوق جميع الخلق، والجهة التي هو فيها جهة العلو، وهي ما فوق جميع الخلق، وهذه الأسئلة ليست بدعة، ولم ننه عنها، بل هذه الأسئلة مأمور بها نعلمها الناس، كما سأل عنها النبي ﷺ قال: أين الله وسأله أبو رزين قال: أين ربنا؟ فأخبره أنه في العلو ، فالله  في العلو في جهة العلو فوق السماوات، فوق العرش، فوق جميع الخلق، وليس في الأرض، ولا في داخل الأرض، ولا في داخل السماوات.    ومن قال: إن الله في الأرض، وأن الله في كل مكان كـالجهمية والمعتزلة ونحوهم فهو كافر عند أهل السنة والجماعة؛ لأنه مكذب لله ولرسوله في إخبارهما بأنه سبحانه في السماء فوق العرش -جل وعلا-، فلا بد من الإيمان بأن الله فوق العرش، فوق جميع الخلق، وأنه في السماء، يعني: في العلو، معنى السماء يعني: العلو، فالسماء يطلق على معنيين: أحدهما: السماوات المبنية، يقال لها: سماء.\nوالثاني: العلو، يقال له: سماء، فالله سبحانه في العلو، في جهة العلو فوق جميع الخلق، وإذا أريد: السماء المبينة المعنى هو: عليها، في يعني: على، في السماء يعني: على السماء وفوقها، كما قال الله سبحانه: فَسِيرُوا فِي الأَرْضِ [آل عمران:137] سيروا في الأرض يعني: عليها فوقها، وكما قال الله  عن فرعون أنه قال: لَأُصَلِّبَنَّكُمْ فِي جُذُوعِ النَّخْلِ [طه:71] يعني: على جذوع النخل، فلا منافاة بين قول من قال: في السماء يعني: على السماء، وبين من قال: إنه في العلو؛ لأن السماء المراد به العلو، فالله في العلو، فوق السماوات فوق جميع الخلق، وفوق العرش . ومن قال: معنى في: على، يعني: أنه فوق السماوات المبنية فوقها، ولا شك أنه فوقها، فوق العرش، فوق جميع الخلق ، فأنت على عقيدة صالحة، وأبشر بالخير، والحمد لله الذي هداك لذلك، ولا تلتفت إلى أقوال المشبهين والملبسين؛ فإنهم في ضلال. وأنت بحمد الله ومن معك على هذه العقيدة أنتم على الحق في إيمانكم بأن الله في السماء، فوق العرش، فوق جميع الخلق ، وعلمه في كل مكان -جل وعلا-، ولا يشابه الخلق في شيء من صفاته ، وليس في حاجة إلى العرش، ولا إلى السماء، بل هو غني عن كل شيء ، والسماوات مفتقرة إليه، والعرش مفتقر أيضًا، وهو الذي أقام العرش، وهو الذي أقام الكرسي، وهو الذي أقام السماوات، وهو الذي أمسكها ، كما قال : وَمِنْ آيَاتِهِ أَنْ تَقُومَ السَّمَاءُ وَالأَرْضُ بِأَمْرِهِ [الروم:25] قال سبحانه: إِنَّ اللَّهَ يُمْسِكُ السَّمَوَاتِ وَالأَرْضَ أَنْ تَزُولا [فاطر:41] فالله الذي أمسك السماوات، وأمسك العرش، وأمسك هذه المخلوقات، فلولا إمساكه لها، وإقامته لها؛ لاندك بعضها على بعض، ولكنه -جل وعلا- هو الذي أقامها وأمسكها حتى يأتي أمر القيامة، فإذا جاء يوم القيامة صار لها حال أخرى. فهو سبحانه على كل شيء قدير، وبكل شيء عليم، وهو العالي فوق جميع خلقه، وصفاته كلها علا، وأسماؤه كلها حسنى، فالواجب على أهل العلم والإيمان أن يصفوا الله سبحانه بما وصف به نفسه، وبما وصفه به رسوله -عليه الصلاة والسلام-، من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، بل مع الإيمان بأنه سبحانه لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17882/الدليل-على-علو-الله-فوق-العرش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87509.mp3","categories":["التفسير","الأسماء والصفات","فتاوى متنوعة"]},{"id":18923,"question":"يقول السائل: اسم الله الأعظم، هل هو من ضمن الأسماء الحسنى التسعة والتسعين؟","title":"هل اسم الله الأعظم من ضمن التسعة والتسعين اسمًا؟","answer":"الجواب: كل أسماء الله يقال لها: الأعظم، كلها عظمى، كل أسماء الله عظمى، نعم. المقدم: حفظكم الله يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18077/هل-اسم-الله-الاعظم-من-ضمن-التسعة-والتسعين-اسما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88212.mp3","categories":["الأسماء والصفات"]},{"id":18956,"question":"هناك سؤال سماحة الشيخ، الحقيقة يتعلق في العقيدة من السائل قحطان بن سعيد من محافظة حضرموت يقول في هذا  سماحة الشيخ، هل تعلم صفات الله  واجب أم مستحب؟ أم أنه سواء تعلم ذلك أم لم يتعلم هذه الصفات؟ وماذا تقولون في الذين يقولون: بأن تعلم هذه الصفات لا ينبغي؛ لأنه يجعل الإنسان يوسوس له كلمة كيف؟ وماذا؟ وما الكتب التي تنصحوننا بتعلمها في هذا الباب؟ مأجورين.","title":"حكم تعلم أسماء الله تعالى وصفاته","answer":"الجواب: تعلم أسماء الله وصفاته من القرآن العظيم، والسنة المطهرة من أفضل القربات؛ لأن هذا يعين على تعظيم الله، وتقديسه، وسؤاله بأسمائه وصفاته ، والله يقول: وَلِلَّهِ الأَسْمَاءُ الْحُسْنَى فَادْعُوهُ بِهَا[الأعراف:180] دل على أنه يشرع لنا أن نعرفها حتى ندعوه بها. ويقول النبي ﷺ: إن لله تسعة وتسعين اسمًا، من أحصاها دخل الجنة، وهو وتر يحب الوتر دل على أنه ينبغي لأهل العلم ولأهل الإيمان تعلم أسماء الله وصفاته حتى يسألوه بها، وحتى يثنوا عليه بها، وحتى يعملوا بمقتضاها؛ فتحصل لهم الجنة، هكذا ينبغي للمؤمن، ويعلم أن الله -جل وعلا- ذو الأسماء الحسنى، وأنه لا شبيه له، ولا كفء له، ولا ند له، وأنه الكامل في ذاته، وأسمائه، وصفاته، وأفعاله، ولا يشبه الله بخلقه؛ لأنه سبحانه يقول: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ[الشورى:11]. فهو الرحمن برحمة لا كرحمتنا، وهو العلي علو لا كعلونا، وهو المستوي على العرش لا كاستوائنا، رحيم لا كرحمتنا، يغضب لا كغضبنا، يضحك لا كضحكنا، إلى غير هذا من صفاته ، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18141/حكم-تعلم-اسماء-الله-تعالى-وصفاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79209.mp3","categories":["الأسماء والصفات"]},{"id":19217,"question":"السؤال الثاني لأخينا يقول: هل رأى رسول الله ﷺ ربه ليلة الإسراء والمعراج، علمًا أني سمعت رجلًا يقول في قوله تعالى: وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى ۝ عِنْدَ سِدْرَةِ الْمُنْتَهَى ۝ عِنْدَهَا جَنَّةُ الْمَأْوَى [النجم:14-15]، أن جبريل عليه السلام لا يستطيع الوصول إلى هذا المكان إنما هو الله سبحانه؟ أرشدوني جزاكم الله خيرًا.","title":"هل رأى النبي ربه ليلة الإسراء والمعراج؟","answer":"الجواب: الصواب أن نبينا ﷺ لم ير ربه ليلة الإسراء والمعراج، وإنما رأى جبرائيل، هذا هو الصواب، كما قال الله سبحانه: وَالنَّجْمِ إِذَا هَوَى ۝ مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى ۝ وَمَا يَنْطِقُ عَنِ الْهَوَى ۝ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى ۝ عَلَّمَهُ شَدِيدُ الْقُوَى [النجم:1-5]، هذا جبرائيل عليه الصلاة والسلام، ذُو مِرَّةٍ [النجم: 6]، يعني: ذو قوة فَاسْتَوَى ۝ وَهُوَ بِالأُفُقِ الأَعْلَى ۝ ثُمَّ دَنَا [النجم:1-8]، يعني: جبرائيل فَتَدَلَّى ۝ فَكَانَ قَابَ قَوْسَيْنِ أَوْ أَدْنَى [النجم:8-9]، يعني: من محمد عليه الصلاة والسلام. فَأَوْحَى إِلَى عَبْدِهِ [النجم: 10]، يعني: أوحى جبرائيل إلى عبده، يعني: إلى عبد الله، الضمير يعود على الله لأنه معروف من السياق، فَأَوْحَى إِلَى عَبْدِهِ مَا أَوْحَى ۝ مَا كَذَبَ الْفُؤَادُ مَا رَأَى ۝ أَفَتُمَارُونَهُ عَلَى مَا يَرَى ۝ وَلَقَدْ رَآهُ نَزْلَةً أُخْرَى ۝ عِنْدَ سِدْرَةِ الْمُنْتَهَى [النجم:10-14]، كل هذا في جبرائيل، هذا هو الصواب. المقام كله في جبرائيل لا في الله  هذا هو الحق، وقد وقع في رواية شريك بن عبد الله بن أبي نمر عن أنس بعض الأغلاط، وذكر ما يدل على أنه هو الله  ولكنهم.. ولكن أهل الحق من أئمة الحديث غلطوا شريكًا في ذلك، فالصواب أن الآية في جبرائيل، وأنه هو الذي رآه محمد عليه الصلاة والسلام، رآه نزلة أخرى ۝ عند سدرة المنتهى هذا هو جبرائيل عليه الصلاة والسلام، وكان رآه مرتين في صورته التي خلقه الله عليها، رآه في الأفق، ورآه عند السدرة، وله ستمائة جناح، كل جناح منها مد البصر، وهذه من آيات الله العظيمة . وفي صحيح مسلم عن أبي ذر  قال: سألت النبي ﷺ: هل رأيت ربك؟ فقال عليه الصلاة والسلام: رأيت نورًا، وفي اللفظ الآخر قال: نور أنى أراه!، فبين ﷺ أنه لم ير ربه، وإنما رأى نورًا، وسئلت عائشة عن ذلك، فأفادت أنه لم ير ربه، وتلت قوله تعالى: لا تُدْرِكُهُ الأَبْصَارُ وَهُوَ يُدْرِكُ الأَبْصَارَ [الأنعام: 103]، يعني: في الدنيا. وأما في الآخرة فيراه النبي ﷺ والمؤمنون، يرونه يوم القيامة ويرونه في الجنة كما يشاء  هذا بإجماع أهل السنة والجماعة، أن المؤمنين يرونه يوم القيامة في عرصات القيامة، ويراه المؤمنون أيضًا في الجنة، كما تواترت به الأخبار عن رسول الله عليه الصلاة والسلام أنه قال للصحابة: هل تضارون في رؤية الشمس صحوًا ليس دونها سحاب ؟ قالوا: لا ، قال: هل تضارون رؤية القمر ليلة البدر ليس دونه سحاب؟ قالوا: لا، قال: فإنكم سترون ربكم كذلك، يعني: ترونه كما ترون هذه الشمس وهذا القمر، يعني: رؤية حقيقة، فهذا واضح في إثبات الرؤية وأن المؤمنين يرون ربهم جل وعلا يوم القيامة وفي دار الكرامة كما ترى الشمس وكما يرى القمر. وهذا تشبيه للرؤية بالرؤية لا بالمرئي، ليست تشبيه المرئي بالمرئي، ربنا لا شبيه له ، ليس كمثله شيء ، ولكن الرسول ﷺ شبه الرؤية في وضوحها وأنها يقين كرؤية الشمس والقمر، يعني: أنها رؤية واضحة ثابتة يقينية لا شبهة فيها، أما المرئي سبحانه فليس له شبيه ولا نظير جل وعلا، وهذا هو قول أهل الحق، هذا قول أهل السنة والجماعة. وقد ثبت هذا في الصحيحين من حديث أبي هريرة ومن حديث جرير بن عبد الله البجلي ومن أحاديث أخرى كثيرة متواترة عن رسول الله عليه الصلاة والسلام في إثبات رؤية الله جل وعلا يوم القيامة يراه المؤمنون، ويراه المؤمنون أيضًا في الجنة. أما الكفار فإنهم محجوبون عن الله ، كما أخبر بهذا سبحانه في قوله: كَلَّا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ ۝ كَلَّا إِنَّهُمْ عَنْ رَبِّهِمْ يَوْمَئِذٍ لَمَحْجُوبُونَ [المطففين:14-15]، فهم محجوبون عن رؤية الله ، لا يرونه، أما أهل الإيمان فيرونه، وهذا معنى قوله سبحانه: وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ ۝ إِلَى رَبِّهَا نَاظِرَةٌ [القيامة:22-23]، وُجُوهٌ يَوْمَئِذٍ نَاضِرَةٌ [القيامة: 22]، يعني: من البهاء والحسن، ناضرة من النضارة، وهي البهاء والحسن والجمال، إِلَى رَبِّهَا نَاظِرَةٌ [القيامة: 23]، إليه سبحانه، تنظر إليه ، كما يشاء فضلاً منه وإحساناً ، وكما قال : لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ [يونس: 26]، المعنى: للذين أحسنوا في الدنيا الحسنى في الآخرة وهي الجنة، وزيادة: وهي النظر إلى وجه الله . فالواجب على كل مؤمن وعلى كل مؤمنة أن يعتقد ذلك، وأن يؤمن بذلك وأن يبرأ إلى الله من طريقة أهل البدع، الذين أنكروا الرؤية ونفوها كـالجهمية والمعتزلة ومن سار في ركابهم، هذا القول من أبطل الباطل وأضل الضلال، وجحد لما بينه الله في كتابه وما بينه رسوله عليه الصلاة والسلام. نسأل الله أن لا يحجبنا من رؤيته، وأن يوفقنا وجميع إخواننا المؤمنين لرؤيته  والتنعم بذلك في القيامة وفي دار الكرامة.","link":"https://binbaz.org.sa/fatwas/18407/هل-راى-النبي-ربه-ليلة-الاسراء-والمعراج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_889/nour_88904.mp3","categories":["الأسماء والصفات"]}]
